local config = {
  ui_story_5043_50430101_1_dialog_content = "<color=#e8d9bb>アップタウン、法廷</color>",
  ui_story_5043_50430101_2_dialog_content = "裁判官様、絶対にそんなことはありません！",
  ui_story_5043_50430101_3_dialog_content = "光の神に誓って、僕の彼女への「愛」は本物です！\nだましたことなどありません！",
  ui_story_5043_50430101_4_dialog_content = "<color=#e8d9bb>カンカン――</color>",
  ui_story_5043_50430101_5_dialog_content = "静粛に！原告の言葉をさえぎらないように。",
  ui_story_5043_50430101_6_dialog_content = "ライン裁判官、続けてください。",
  ui_story_5043_50430101_7_dialog_content = "原告の主張は、婚約期間中に被告が婚約者としての義務を\n果たさなかったということですね？",
  ui_story_5043_50430101_8_dialog_content = "そうです！",
  ui_story_5043_50430101_9_dialog_content = "弁論に入る前に、原告には意見陳述が許されます。",
  ui_story_5043_50430101_10_dialog_content = "先月は冠月祭で、ちょうど婚約7カ月の記念日でもありました。",
  ui_story_5043_50430101_11_dialog_content = "それなのに、この人はまったく気にも留めてくれなかったんです！",
  ui_story_5043_50430101_12_dialog_content = "勘弁してくれ…こう毎月毎月祝わされたんじゃ、\n僕もやってられないよ。",
  ui_story_5043_50430101_13_dialog_content = "記念日を祝わないだけならまだいいんです。\nでも、この人ときたら、何人もの人に冠月祭のプレゼントを渡していたんです！",
  ui_story_5043_50430101_14_dialog_content = "ちょっと待ってくれ。その件は説明したろ！？\n相手は皆、家族ぐるみの仕事の付き合いがある人達だ…",
  ui_story_5043_50430101_15_dialog_content = "お二人とも、けんかは良くありませんわ…",
  ui_story_5043_50430101_16_dialog_content = "<size=30>ティナ、貴方も今は裁判官ですよ。\n堂々と話してください！</size>",
  ui_story_5043_50430101_17_dialog_content = "<size=30>そ、そうでしたわね…\nそ、それでは！オホン…</size>",
  ui_story_5043_50430101_18_dialog_content = "<size=45>静粛に、静粛に！</size>",
  ui_story_5043_50430101_19_dialog_content = "<color=#e8d9bb>ガヤガヤ…ザワザワ…</color>",
  ui_story_5043_50430101_20_dialog_content = "（…僕、なんで知らないカップルの痴話げんかを\n聞かされてるんだろう…？）",
  ui_story_5043_50430101_21_dialog_content = "PlayerName、うんざりしているようね？\n顔が少しひきつっているわ。",
  ui_story_5043_50430101_22_dialog_content = "そ、そんなことは…\nいや…やっぱりカレンの目はごまかせないね。",
  ui_story_5043_50430101_23_dialog_content = "実を言うと、私も同じ気分よ。",
  ui_story_5043_50430101_24_dialog_content = "ただ表情や態度に出さないようにしているだけ。だって――",
  ui_story_5043_50430101_25_dialog_content = "うん、分かってる。\nカレンの態度は城主様の態度でもあると受け取られちゃうからね。",
  ui_story_5043_50430101_26_dialog_content = "…",
  ui_story_5043_50430101_27_dialog_content = "城主様もずっと態度を示されていないわ。",
  ui_story_5043_50430101_28_dialog_content = "申し訳ないわね。\n本当は龍州大陸のことを報告してもらおうと思っていたのだけれど…",
  ui_story_5043_50430101_29_dialog_content = "どうやら城主様にその暇はなさそうだわ。",
  ui_story_5043_50430101_30_dialog_content = "気にしないで。特に急ぎの用事が入ってるわけでもないし。",
  ui_story_5043_50430101_31_dialog_content = "<size=30>むしろ、あんなピリピリした空気の会議場に入らずに済んでよかった…</size>",
  ui_story_5043_50430101_32_dialog_content = "何か言ったかしら？",
  ui_story_5043_50430101_33_dialog_content = "何でもないよ！",
  ui_story_5043_50430101_34_dialog_content = "（そういえば、ここに来たのは<color=#FFB400>あの事件</color>以来だ…）",
  ui_story_5043_50430101_35_dialog_content = "（あの時もイルンティはあの席で、\nカレンへの判決を読み上げたんだっけ…）",
  ui_story_5043_50430101_36_dialog_content = "（あれからカレンも…ずいぶんと変わったな…）",
