  ui_story_5043_50430101_38_dialog_content = "え？あ…うん…",
  ui_story_5043_50430101_39_dialog_content = "なんだか…冠月祭の後、\n白夜城の雰囲気がだいぶ変わったなと思って…",
  ui_story_5043_50430101_40_dialog_content = "そうね。毎年この時期には、\nこういう状況がしばらく続くの。",
  ui_story_5043_50430101_41_dialog_content = "冠月祭の余韻で、新しい関係を始める男女もいれば、\nすれ違いを起こす男女もいる。",
  ui_story_5043_50430101_42_dialog_content = "おまけに享楽好きの貴族たちも、\nどうにかして冠月祭の余韻を引き延ばそうとするのよ。",
  ui_story_5043_50430101_43_dialog_content = "そのせいで法廷では毎年この時期決まって、\n大量の恋愛のもつれに関する訴え事を抱え込むことになるの。",
  ui_story_5043_50430101_44_dialog_content = "だから城主直々に傍聴へ出向く機会を増やして、\n法廷で対処しきれない突発的な事件が起こるのを防いでいるというわけよ。",
  ui_story_5043_50430101_45_dialog_content = "まぁ、傍聴席で見ているだけなら、\n被告として証言台に立たされるよりはずっと気楽でしょうね？",
  ui_story_5043_50430101_46_dialog_content = "カレン…",
  ui_story_5043_50430101_47_dialog_content = "<color=#e8d9bb>カン！カン！カン！</color>",
  ui_story_5043_50430101_48_dialog_content = "<size=45>静粛に！</size>",
  ui_story_5043_50430101_49_dialog_content = "とにかく、これは決して許されない悪質な事件です！",
  ui_story_5043_50430101_50_dialog_content = "婚約の取り消しを申し立てます！",
  ui_story_5043_50430101_51_dialog_content = "ああ、美しいお嬢さん！\n貴方のお気持ち、とてもよく分かります！",
  ui_story_5043_50430101_52_dialog_content = "私の知る限り、お二人の結婚は一族同士が\nずいぶんと前に決めたことで、ご当人同士も幼なじみだそうですね。",
  ui_story_5043_50430101_53_dialog_content = "それならば納得がいきます。そうでもなければ、被告のような男性が\n貴方のように素敵な女性と恋仲になれるはずがありませんから！",
  ui_story_5043_50430101_54_dialog_content = "は、はい…シュワーベ裁判官のおっしゃった通りです。\n私たちは確かに幼なじみで、彼のことは私が一番よく知っています。",
  ui_story_5043_50430101_55_dialog_content = "ああ、なんとうらやましい！\nこの湧きおこる嫉妬心をどう抑えればよいでしょう！？",
  ui_story_5043_50430101_56_dialog_content = "（ええ？あの裁判官、まるで口説いてるみたい…）",
  ui_story_5043_50430101_57_dialog_content = "裁判官様…？",
  ui_story_5043_50430101_58_dialog_content = "<color=#e8d9bb>カン！</color>",
  ui_story_5043_50430101_59_dialog_content = "シュワーベ裁判官、ここが法廷であることを忘れないように。",
  ui_story_5043_50430101_60_dialog_content = "ですがお嬢さん、被告の人となりに関しては、\nさすがに私や裁判長でも存じ上げません。",
  ui_story_5043_50430101_61_dialog_content = "しかし、あなたは長年のお付き合いですから、\n彼の人となりをよく知った上で熟慮の末、この訴訟を起こされたのでしょう？",
  ui_story_5043_50430101_62_dialog_content = "え…？",
  ui_story_5043_50430101_63_dialog_content = "（フン…簡単に引っ掛かったな）",
  ui_story_5043_50430101_64_dialog_content = "わ、私は…",
  ui_story_5043_50430101_65_dialog_content = "イルンティ裁判長が判決を下される前に、\n被告から何か言いたいことはありますか？",
  ui_story_5043_50430101_66_dialog_content = "<size=45>僕は子供の頃からずっと君だけを愛してきた！</size>",
  ui_story_5043_50430101_67_dialog_content = "まあ…！…あ、あなたって人は…！\nこんな所で急にそんなこと…",
  ui_story_5043_50430101_68_dialog_content = "よろしいですか？それでは――",
  ui_story_5043_50430101_69_dialog_content = "<size=45>待ってください！</size>",
  ui_story_5043_50430101_70_dialog_content = "申し訳ありません。彼とのこと、改めて考え直してみました…",
  ui_story_5043_50430101_71_dialog_content = "<color=#FFB400>訴えを取り下げ</color>させてください。",
  ui_story_5043_50430101_72_dialog_content = "（そんな簡単に取り下げられるの！？）",
  ui_story_5043_50430101_73_dialog_content = "申し訳ありません。誤解を解決しないままにしていた、\n私もいけなかったんです。",
  ui_story_5043_50430101_74_dialog_content = "いや、僕があまりにも消極的すぎたんだ。\n僕がいけなかったんだよ。",
  ui_story_5043_50430101_75_dialog_content = "却下します。法廷は厳粛なる場所です。\n訴訟の申し立ても取り下げも、正式な手続きが行われなければなりません。",
  ui_story_5043_50430101_76_dialog_content = "ただし、取り下げよりも迅速に解決できる方法があります。",
  ui_story_5043_50430101_77_dialog_content = "判決を言い渡します――",
  ui_story_5043_50430101_78_dialog_content = "<color=#e8d9bb>カン――</color>",
  ui_story_5043_50430101_79_dialog_content = "被告人は無罪。",
  ui_story_5043_50430101_80_dialog_content = "ああ、愛しの人よ！",
  ui_story_5043_50430101_81_dialog_content = "さあ、一緒に近くのサロンでお茶でも楽しみましょう？",
  ui_story_5043_50430101_82_dialog_content = "…本件の審理はここまで。閉廷。",
  ui_story_5043_50430101_83_dialog_content = "シュワーベ様、お待ちになって！",
  ui_story_5043_50430101_84_dialog_content = "シュワーベ様、無事に審理を終えられてよかったですね！\nおめでとうございます、お祝いの花束です！",
  ui_story_5043_50430101_85_dialog_content = "そ、それから、ホワイトチョコレートをお持ちしました。\nどうか、受け取ってください…",
  ui_story_5043_50430101_86_dialog_content = "（チッ…）",
