  ui_story_5043_50430101_88_dialog_content = "<color=#e8d9bb>裁判長執務室</color>",
  ui_story_5043_50430101_89_dialog_content = "「規則」は、万人に混乱の所在を知らしめるために存在する。",
  ui_story_5043_50430101_90_dialog_content = "あのような訴訟を扱うようになってどれほど経つ？",
  ui_story_5043_50430101_91_dialog_content = "ここ1か月程で増加しております。",
  ui_story_5043_50430101_92_dialog_content = "そうか。若いのはよいことだ。",
  ui_story_5043_50430101_93_dialog_content = "だが、法廷は厳粛かつ神聖な場所である。",
  ui_story_5043_50430101_94_dialog_content = "…この種の訴えは受理せぬように、\nということでしょうか？",
  ui_story_5043_50430101_95_dialog_content = "いや、まだそれには早かろう。",
  ui_story_5043_50430101_96_dialog_content = "にわかに受理が停止されれば、\n法廷に不満が募りかねん。",
  ui_story_5043_50430101_97_dialog_content = "城主様にはご指示を賜りたく存じます。",
  ui_story_5043_50430101_98_dialog_content = "臨時の専門機関を設立し、\n痴情絡みの訴えを扱わせるがよかろう。",
  ui_story_5043_50430101_99_dialog_content = "白夜城高庭直属とするが、\n法廷とは一線を画しておかねばなるまい。",
  ui_story_5043_50430101_100_dialog_content = "人選については、若手を数名取り立て、\n経験を積ませるがよかろう。",
  ui_story_5043_50430101_101_dialog_content = "そうしますと、一時的なものとはいえ、\nそちらの長が必要になりますね。",
  ui_story_5043_50430101_102_dialog_content = "すでに考えがおありですか？",
  ui_story_5043_50430101_103_dialog_content = "さきほどから1人、心当たりがある…",
  ui_story_5043_50430101_104_dialog_content = "<color=#e8d9bb>アップタウン、法廷</color>",
  ui_story_5043_50430101_105_dialog_content = "城主様とイルンティ裁判長が\n重要そうな話をしているわね。",
  ui_story_5043_50430101_106_dialog_content = "今日の会議はおそらく、取り止めになるでしょう。\n次に城主様が時間をとれるとすれば…",
  ui_story_5043_50430101_107_dialog_content = "ごめんなさい、PlayerName。\n何日も待たせることになりそうだわ。",
  ui_story_5043_50430101_108_dialog_content = "いずれあなたも分かる時が来るわ。\n「城主様」はいつも約束を破るし、他人の意見に耳も貸さない…",
  ui_story_5043_50430101_109_dialog_content = "そ、そんなことないんじゃないかな…\nそれに僕たち、おかげで久しぶりにゆっくりできるよ。",
  ui_story_5043_50430101_110_dialog_content = "裁判官の皆が資料整理してるところを\n見てるだけでも十分楽しいしね。",
  ui_story_5043_50430101_111_dialog_content = "訴状、証拠品、弁論意見書…よし、全部そろっていますね。",
  ui_story_5043_50430101_112_dialog_content = "これでほぼ整理し終わりました。\nティナ、そちらはどうですか？",
  ui_story_5043_50430101_113_dialog_content = "は…はい…？",
  ui_story_5043_50430101_114_dialog_content = "あら…ラインさん、申し訳ありません。\n先程の審理が3時間も続いたので眠くなってしまいました…ふわぁ～…",
  ui_story_5043_50430101_115_dialog_content = "まったく困ったものですね。でしたら…",
  ui_story_5043_50430101_116_dialog_content = "1日中働きづめだったでしょう。心が安らぐお茶でも飲んで、\nひと休みしてはいかがですか？さあ、どうぞ――",
  ui_story_5043_50430101_117_dialog_content = "あら…どうもありがとうございます。\nゴクッ…",
  ui_story_5043_50430101_118_dialog_content = "まあ！？",
  ui_story_5043_50430101_119_dialog_content = "これ、ホットチョコレートですわ！？",
  ui_story_5043_50430101_120_dialog_content = "ふふ、目が覚めましたか？\n「眠り病」のことは知っていますが、眠るのは仕事が終わってからにしてください。",
  ui_story_5043_50430101_121_dialog_content = "それはそうと…ここ数日はいつにもまして、\n眠くなりやすいようですね？",
  ui_story_5043_50430101_122_dialog_content = "そうでしょうか…？\n私は毎日決まって4時間しか起きていられませんわ。",
  ui_story_5043_50430101_123_dialog_content = "少なくとも今日は違うでしょう？\nきのうも終業前からあくびばかりしていましたし…",
  ui_story_5043_50430101_124_dialog_content = "まさか、夜によく眠れていないのですか？\n貴方のような方でも不眠症になるのでしょうか？",
  ui_story_5043_50430101_125_dialog_content = "じょ、冗談はおやめください。そんなことは…",
  ui_story_5043_50430101_126_dialog_content = "とにかく、こちらの資料も整理できましたわ。\n私は帰らせていただきますわね。",
  ui_story_5043_50430101_127_dialog_content = "皆様、ごきげんよう！",
  ui_story_5043_50430101_128_dialog_content = "私もそろそろ帰るとしましょう。",
  ui_story_5043_50430101_129_dialog_content = "傍聴席のカレン殿下とご同伴のお方、お先に失礼いたします。",
  ui_story_5043_50430101_130_dialog_content = "あ、またね！",
  ui_story_5043_50430101_131_dialog_content = "（カレンの「同伴」に見られてたんだ…？）",
  ui_story_5043_50430101_132_dialog_content = "これはこれは！久しいな！\n姫君の「ご同伴」君。",
  ui_story_5043_50430101_133_dialog_content = "この声は…",
  ui_story_5043_50430101_134_dialog_content = "マシュー！それからローウェイ！",
  ui_story_5043_50430101_135_dialog_content = "マシュー「閣下」、相変わらず、\n暇を持て余して口ばかりお忙しいようね。",
  ui_story_5043_50430101_136_dialog_content = "そうお怒りくださいますな、殿下。\nそれに私は暇を持て余してなどおりませんぞ。",
  ui_story_5043_50430101_137_dialog_content = "「面白いこと」があるのですが、\nお二人とも、興味はございませんかな？",
  ui_story_5043_50430101_138_dialog_content = "「面白いこと」？",
  ui_story_5043_50430101_139_dialog_content = "さよう。今入ったばかりの情報でしてな。\n一般庶民であれば明日にならなければ知り得ん情報です。",
  ui_story_5043_50430101_140_dialog_content = "話しなさい。",
  ui_story_5043_50430101_141_dialog_content = "実は最近奇妙な事件が法廷に舞い込んだのです。\nまだ担当は決まっておりませぬが…",
  ui_story_5043_50430101_142_dialog_content = "間違いなく私が担当となりましょう。",
  ui_story_5043_50430101_143_dialog_content = "裁判長に長いこと頼み込んで、ようやく許可が出たのです。",
  ui_story_5043_50430101_144_dialog_content = "ええいっ、お前は黙っておれ！",
  ui_story_5043_50430101_145_dialog_content = "とにかく、その事件というのは、\nここ最近の冠月祭の風潮とも関係があり…",
  ui_story_5043_50430101_146_dialog_content = "<color=#e8d9bb>アップタウン、居住区</color>",
  ui_story_5043_50430101_147_dialog_content = "フフフ～フフ…フンフン～♪",
  ui_story_5043_50430101_148_dialog_content = "（家に着いたら、まずはポストの中をチェックして…\nそれから小包が届いていないか確認しましょう）",
  ui_story_5043_50430101_149_dialog_content = "あ…",
  ui_story_5043_50430101_150_dialog_content = "やはり来ていませんか…",
  ui_story_5043_50430101_151_dialog_content = "（先月に<color=#FFB400>あの子</color>がくれた葉っぱと木の実、\nまだ大切にとってありますのに…）",
  ui_story_5043_50430101_152_dialog_content = "（お返しをすべき時期になっても、\n新しい住所を教えてくれないのでしょう…？）",
  ui_story_5043_50430101_153_dialog_content = "（そういえば、ここ1か月近く、お返事が来ていませんわ）",
  ui_story_5043_50430101_154_dialog_content = "（心配ですわね…いつになったら準備したクッキーを渡せるのでしょうか？）",
  ui_story_5043_50430101_155_dialog_content = "（やはり私が…もっと積極的にならなければいけませんの？）",
  ui_story_5043_50430201_1_dialog_content = "<color=#e8d9bb>翌日</color>",
  ui_story_5043_50430201_2_dialog_content = "…おおよその状況は今話した通りです。",
  ui_story_5043_50430201_3_dialog_content = "城主様の命により、このところ増加している\n恋愛絡みの訴訟を専門とする臨時部署を設けます。",
  ui_story_5043_50430201_4_dialog_content = "支部の呼称は「<color=#FFB400>恋愛訴訟部</color>」とします。",
  ui_story_5043_50430201_5_dialog_content = "承知しました。恋愛訴訟部にて引き続き職務を果たします。",
  ui_story_5043_50430201_6_dialog_content = "ただ、お尋ねしてもよろしいでしょうか？\n恋愛訴訟部の支部長はどなたですか？イルンティ裁判長が兼任なさるのですか？",
  ui_story_5043_50430201_7_dialog_content = "いいえ、私ではありません。\n城主様自ら<color=#FFB400>シュワーベ</color>をご指名になりました。",
  ui_story_5043_50430201_8_dialog_content = "城主殿下がいったい昨日のシュワーベの弁論に\n何を見出したのかは計りかねますが…",
  ui_story_5043_50430201_9_dialog_content = "彼のような弁論の方式でないと、\n恋愛訴訟には柔軟に対応できないということかもしれません。",
  ui_story_5043_50430201_10_dialog_content = "そうですね、昨日のあれほど混乱した裁判をうまく丸めた手腕は、\nさすがシュワーベとしか言いようがありません。納得いたしました。",
  ui_story_5043_50430201_11_dialog_content = "彼は確かに自身の魅力の活かし方を心得ていますから…",
  ui_story_5043_50430201_12_dialog_content = "気落ちすることはありません。",
  ui_story_5043_50430201_13_dialog_content = "正式に裁判官となってまだ日は浅いとはいえ、\n城主様はあなたたちの活躍に期待なさっています。",
  ui_story_5043_50430201_14_dialog_content = "恋愛訴訟部から戻ったあかつきには、\n全員に昇進の機会が与えられることでしょう。",
  ui_story_5043_50430201_15_dialog_content = "ありがとうございます、裁判長。",
  ui_story_5043_50430201_16_dialog_content = "もう一つ、任せたい仕事があります。",
  ui_story_5043_50430201_17_dialog_content = "恋愛訴訟部が抱える最も厄介な問題と言えるかもしれません。",
  ui_story_5043_50430201_18_dialog_content = "おそらくすでに聞き及んでいるでしょうが、\n「<color=#FFB400>首なし彫像事件</color>」のことです。",
  ui_story_5043_50430201_19_dialog_content = "なんと！？早々に大仕事を任せていただけるのですか？",
  ui_story_5043_50430201_20_dialog_content = "その反応を聞いて安心しました。\nすでに5、6人ほど断られていましたから。",
  ui_story_5043_50430201_21_dialog_content = "なぜ断られたのです？",
  ui_story_5043_50430201_22_dialog_content = "事件自体が妙なこともありますが、\n多くは恋人とサロンに行く約束があるからといった理由ですね。",
  ui_story_5043_50430201_23_dialog_content = "そうですか。分かりました…",
  ui_story_5043_50430201_24_dialog_content = "（はぁ…貴族というのは…相変わらずですね…）",
  ui_story_5043_50430201_25_dialog_content = "「首なし彫像事件」の原告は、\n<color=#FFB400>バイロン</color>というミッドタウンの貴族です。",
  ui_story_5043_50430201_26_dialog_content = "<color=#e8d9bb>4日前</color>",
  ui_story_5043_50430201_27_dialog_content = "<color=#e8d9bb>チリンチリン――</color>",
  ui_story_5043_50430201_28_dialog_content = "聞こえてます！\nもう鳴らさないでください！",
  ui_story_5043_50430201_29_dialog_content = "呼び鈴を鳴らしていたのは、あなたですか？",
  ui_story_5043_50430201_30_dialog_content = "そうだ！隣人を訴えたい！",
  ui_story_5043_50430201_31_dialog_content = "あいつが法廷の前にある<color=#FFB400>ガラテーア</color>を壊したのだ！\n私はこの目で見た！",
  ui_story_5043_50430201_32_dialog_content = "待ってください…あれは法廷の正義を象徴する彫像です。\n「ガラテーア」という名前はいつの間に…？",
  ui_story_5043_50430201_33_dialog_content = "確かにあれは数日前に壊れましたが、\nてっきり長年修理をおこたっていたせいだと…",
  ui_story_5043_50430201_34_dialog_content = "お嬢さん、言葉に気をつけたまえ。あれ、ではない！\n「<color=#FFB400>彼女</color>」だ！ガラテーアという名も私がつけたのだ。",
  ui_story_5043_50430201_35_dialog_content = "はぁ、分かりました…\nそれでは、訴状をいただけますか？",
  ui_story_5043_50430201_36_dialog_content = "拝見します…",
  ui_story_5043_50430201_37_dialog_content = "あら？バイロンさん、隣人に対する起訴内容…\n書き間違えていませんか？",
  ui_story_5043_50430201_38_dialog_content = "彫像を壊したというのはわかりますが、\nこの「<color=#FFB400>恋愛妨害</color>」という起訴内容は…？",
  ui_story_5043_50430201_39_dialog_content = "間違ってなどいない。ガラテーアは…",
  ui_story_5043_50430201_40_dialog_content = "私が<color=#FFB400>恋焦がれる女性</color>なのだから！",
  ui_story_5043_50430201_41_dialog_content = "――つまり、彫像に恋をして…\n彫像を壊した人物を訴えたいと？",
  ui_story_5043_50430201_42_dialog_content = "そうです。彫像は公共物ですから、\n誰かがそれに恋することをとがめる権利は私たちにはありません。",
  ui_story_5043_50430201_42X1_dialog_content = "したがって、この訴訟は恋愛訴訟部の管轄といえるでしょう。",
  ui_story_5043_50430201_43_dialog_content = "それと、すでに被告方の状況を調べさせてあるのですが、\n残念ながら――",
  ui_story_5043_50430201_44_dialog_content = "訴状の記載に遺漏が多く、\n被告を容疑者とするには不適切であることが分かりました。",
  ui_story_5043_50430201_45_dialog_content = "法廷は「調査・審理一貫体制」を採っています。\nですので、開廷までにできるだけ多くの情報を集めてください。",
  ui_story_5043_50430201_46_dialog_content = "さもないと、早々に休廷、審理延長ということになります。\nしかし恋愛訴訟部はあくまで臨時。時間に限りがあるのです。",
  ui_story_5043_50430201_47_dialog_content = "承知しました。恋愛訴訟部の活動期間内に解決してみせましょう。",
  ui_story_5043_50430201_48_dialog_content = "頼みましたよ。それから…\n他にも2名がこの訴訟を担当します。",
  ui_story_5043_50430201_49_dialog_content = "1人はあなたの相棒であるティナです。\n今朝、本人の意志を確認しました。",
  ui_story_5043_50430201_50_dialog_content = "事件資料の整理を任せましたが、\n今ごろはおそらく昼寝をしていることでしょう。",
  ui_story_5043_50430201_51_dialog_content = "もう1人は…少々頭が痛いですが、あなた方の<color=#FFB400>先輩</color>にあたりますので…\n何か学べることもあるでしょう。",
  ui_story_5043_50430201_52_dialog_content = "ただちに壊された彫像の前に向かい、合流してください。",
  ui_story_5043_50430201_53_dialog_content = "調査の後、ティナと情報の照らし合わせを行ってください。",
  ui_story_5043_50430201_54_dialog_content = "承知しました。今すぐ向かいます。",
  ui_story_5043_50430201_55_dialog_content = "<color=#e8d9bb>アップタウン、彫像前</color>",
  ui_story_5043_50430201_56_dialog_content = "（裁判長の言葉に含みが有りましたが…\n先輩とはいったい誰でしょう？）",
  ui_story_5043_50430201_57_dialog_content = "やれやれ、今や法廷も出身を問わず、\n庶民まで採用するようになったのか？",
  ui_story_5043_50430201_58_dialog_content = "（やはり…）",
  ui_story_5043_50430201_59_dialog_content = "確かにマシュー「閣下」より、\n裁判官としてよほど様になっているわね。",
  ui_story_5043_50430201_60_dialog_content = "カレン殿下、ごきげんよう。\n旋槍騎士ラインと申します。どうぞお見知りおきを。",
  ui_story_5043_50430201_61_dialog_content = "そんなにかしこまらないで。こちらはPlayerName。\nマシューに誘われて、私たちも協力することにしたの。",
  ui_story_5043_50430201_62_dialog_content = "貴方がうわさの空の末裔でしたか。\n聞いていたよりもずっと親しみやすそうな方ですね！",
  ui_story_5043_50430201_63_dialog_content = "そ、それほどでもないけど…どうぞよろしく。",
  ui_story_5043_50430201_64_dialog_content = "<size=32>いったいどんな噂だったんだろう…</size>",
  ui_story_5043_50430201_65_dialog_content = "庶民出身の新人よ、光の神の恩寵に感謝するがいい。\n我々がいれば任務は必ずや順調に進むであろう。",
  ui_story_5043_50430201_66_dialog_content = "足を引っ張らなければ、それで十分。",
  ui_story_5043_50430201_67_dialog_content = "む、庶民、どうしたのだ？\nあまり喜んでおらぬようではないか？",
  ui_story_5043_50430201_68_dialog_content = "法廷史上、最も奇妙な事件であるぞ。奮い立たぬか！",
  ui_story_5043_50430201_69_dialog_content = "確かにその通りですね。奇妙な彫像に奇妙な罪名、\n奇妙な原告と奇妙な先輩…まさに奇妙のオンパレードです。",
  ui_story_5043_50430201_70_dialog_content = "なにぃ！？なんたる態度だ！\nもっと先輩を敬わんか！",
  ui_story_5043_50430201_71_dialog_content = "先輩とここで口論する気はありません。\nところで、彫像はもうご覧になりましたか？",
  ui_story_5043_50430201_72_dialog_content = "この貯金箱のことか？",
  ui_story_5043_50430201_73_dialog_content = "首のなくなってできた空洞を見ていると、\nコインでも投げ入れたくなってかなわんな…",
  ui_story_5043_50430201_74_dialog_content = "まったく…少しはまじめにお願いしますよ…",
  ui_story_5043_50430201_75_dialog_content = "<color=#e8d9bb>ガサ…</color>",
  ui_story_5043_50430201_76_dialog_content = "何の音だ？",
  ui_story_5043_50430201_77_dialog_content = "グ…グォォ！！！",
  ui_story_5043_50430201_78_dialog_content = "なに！？ここはアップタウンであるぞ！\nこんなところにまで汚らわしい者どもが紛れ込んだというのか！？",
  ui_story_5043_50430201_79_dialog_content = "あり得ない…！白夜城は昼夜を問わず警備されている。\n暗鬼が紛れ込むなどということが…",
  ui_story_5043_50430201_80_dialog_content = "衛兵！",
  ui_story_5043_50430201_81_dialog_content = "はっ！",
  ui_story_5043_50430201_82_dialog_content = "最近の通行証記録を全て確認！\nナイトガーディアンにも連絡して、最新の日誌を報告させなさい！",
  ui_story_5043_50430201_83_dialog_content = "暗鬼の方は…PlayerName、任せても大丈夫ね？",
  ui_story_5043_50430201_84_dialog_content = "うん、任せて！",
  ui_story_5043_50430201_85_dialog_content = "では、暗鬼に裁きを下すといたしましょう。",
  ui_story_5043_50430202_1_dialog_content = "終わったね！皆、けがはない？",
  ui_story_5043_50430202_2_dialog_content = "吐き気はするが、大丈夫だ。",
  ui_story_5043_50430202_3_dialog_content = "一日の仕事が始まったばかりだというに、\nまたシャワーを浴びねばならぬわ！",
  ui_story_5043_50430202_4_dialog_content = "新人の庶民、けがはないか？",
  ui_story_5043_50430202_5_dialog_content = "お気遣いありがとうございます。\n私は清潔でないといられない貴族様ほどヤワではありません。ご心配なく。",
  ui_story_5043_50430202_6_dialog_content = "それは失礼したな。\nだが、一番の潔癖症はローウェイだぞ。",
  ui_story_5043_50430202_7_dialog_content = "全身を服で覆っているからな。\n空気さえ汚らわしいと言わんばかりだ。",
  ui_story_5043_50430202_8_dialog_content = "彫像が壊されたら、\nさっそく役を下ろされるところだった。",
  ui_story_5043_50430202_9_dialog_content = "無視するでない！",
  ui_story_5043_50430202_10_dialog_content = "もう十分見た。早く法廷で保管すべき。",
  ui_story_5043_50430202_11_dialog_content = "重要な<color=#FFB400>物証</color>、放置はできない。",
  ui_story_5043_50430202_12_dialog_content = "原告に言わせれば、「<color=#FFB400>被害者</color>」でしょうね。",
  ui_story_5043_50430202_13_dialog_content = "もう一度よく見ておきましょう…",
  ui_story_5043_50430202_14_dialog_content = "ふむ…断面は外側よりも新しい…\nということは、劣化による断裂とは考えにくいですね。",
  ui_story_5043_50430202_15_dialog_content = "亀裂の入り方を見ても、大きな外力がかかったことは間違いありません。",
  ui_story_5043_50430202_16_dialog_content = "PlayerNameさんはどう思われますか？",
  ui_story_5043_50430202_17_dialog_content = "僕も1つ気になることがあるんだ。",
  ui_story_5043_50430202_18_option_content = "頭がなくなってる",
  ui_story_5043_50430202_19_dialog_content = "この彫像、単に壊されただけには見えないな。\n断面がきれいだし、それに…",
  ui_story_5043_50430202_20_dialog_content = "首から下の部分には何の損傷もない。\n頭だけが消えてる。",
  ui_story_5043_50430202_21_option_content = "破片がない",
  ui_story_5043_50430202_22_dialog_content = "彫像の周りがきれいすぎるよ。\n破片はどこにいったのかな？",
  ui_story_5043_50430202_23_dialog_content = "そのことなら…おそらく物証の採取を担当する者たちが\n掃除したのだと思いますが。",
  ui_story_5043_50430202_24_dialog_content = "そ、そういうことなら…\nおかしな点はやっぱり――消えた頭だね。",
  ui_story_5043_50430202_25_dialog_content = "おっしゃる通りです。こうして見ると、\n彫像の頭は何者かに<color=#FFB400>盗まれた</color>ように見えます…",
  ui_story_5043_50430202_26_dialog_content = "取り込み中すまんが、先程からお前たち、\n<color=#FFB400>アレ</color>には気づいておらんのか？",
  ui_story_5043_50430202_27_dialog_content = "白夜城の空に、いつの間にやら…",
  ui_story_5043_50430202_28_dialog_content = "<color=#FFB400>月</color>が昇っている。",
  ui_story_5043_50430202_29_dialog_content = "ほ、本当だ！",
  ui_story_5043_50430202_30_dialog_content = "奇妙なことが次々と起こりますね。\nいったいどうなっているのでしょうか？",
  ui_story_5043_50430202_31_dialog_content = "面白い。月見としゃれこむか。",
  ui_story_5043_50430202_32_dialog_content = "お待ちください…まだ仕事が終わっていませんよ！",
  ui_story_5043_50430202_33_dialog_content = "あら、皆さんおそろいですか？",
  ui_story_5043_50430202_34_dialog_content = "ティナ、こちらはPlayerNameさん。\nかの空の末裔です。",
  ui_story_5043_50430202_35_dialog_content = "ふふ、冠月祭の時にお会いしましたわ。",
  ui_story_5043_50430202_36_dialog_content = "ごきげんよう、PlayerNameさん。\n朝からお会いできるなんて嬉しいですわ。",
  ui_story_5043_50430202_37_dialog_content = "こちらこそ、ティナ。\nもう朝じゃないけどね…",
  ui_story_5043_50430202_38_dialog_content = "ティナにとっては目が覚めた時が「朝」なのです。",
  ui_story_5043_50430202_39_dialog_content = "ティナ、ちょうどよいところに来た。\n調査結果を交換するとしよう。",
  ui_story_5043_50430202_40_dialog_content = "それでしたら…同時に言うことにしましょう。\nこちらの調査は――",
  ui_story_5043_50430202_41_dialog_content = "収穫ナシですわ/収穫ナシだ。",
  ui_story_5043_50430202_42_dialog_content = "あら、やはりそうでしたか。\nそちらも何の進展もなかったのですね。",
  ui_story_5043_50430202_43_dialog_content = "私、裁判長からいただいた訴訟内容の資料を\n何度も詳しく読み返しましたの。",
  ui_story_5043_50430202_44_dialog_content = "でも、いくら読んでも前後のつじつまが合いませんし、\n話の筋道も通りませんし…私には理解できませんわ。",
  ui_story_5043_50430202_45_dialog_content = "こちらはあえて言うなら、\n不確かなものの、ある推測に至りました。",
  ui_story_5043_50430202_46_dialog_content = "私とPlayerNameさんは\n彫像の頭は何者かによって持ち去られたと考えています。",
  ui_story_5043_50430202_47_dialog_content = "まぁ…そんなことをする人がおりますの？",
  ui_story_5043_50430202_48_dialog_content = "あり得ぬとは言えんな。\nどこぞの下級裁判官が新しい被り物を探していたのやもしれん。",
  ui_story_5043_50430202_49_dialog_content = "いずれにせよ、何の進展もなかったのならば、\n今日はここまでとしようではないか。",
  ui_story_5043_50430202_50_dialog_content = "お待ちください！実は…その…",
  ui_story_5043_50430202_51_dialog_content = "皆さんをお訪ねしたのは、\n個人的なお願いがあるからですの。",
  ui_story_5043_50430202_52_dialog_content = "ふむ、「個人的なこと」とは何でしょう…？\nそのような問題に関わることは好きではないのですが…",
  ui_story_5043_50430202_53_dialog_content = "そうですか…ただ、私最近とても困っていまして。\n皆さんのご意見が聞きたいのです…",
  ui_story_5043_50430202_54_dialog_content = "やれやれ。今、こんな時にか？",
  ui_story_5043_50430202_55_dialog_content = "まぁ、分からん話でもない。\nどうせ色恋沙汰であろう？",
  ui_story_5043_50430202_56_dialog_content = "急に乗り気になった。",
  ui_story_5043_50430202_57_dialog_content = "それは…とにかく、皆さんを我が家へお招きしますわ。\nお菓子を用意してありますの。",
  ui_story_5043_50430202_58_dialog_content = "PlayerNameさんも一緒にいらしてください。",
  ui_story_5043_50430202_59_dialog_content = "空の末裔は見ただけで他人の心が読めるそうですね。\n私の悩みをぜひ聞いていただきたいですわ。",
  ui_story_5043_50430202_60_dialog_content = "誘ってもらえてうれしいよ。\nただ、空の末裔の能力はそれほどじゃないけど…",
  ui_story_5043_50430301_1_dialog_content = "<color=#e8d9bb>アップタウン居住区、ティナの家</color>",
  ui_story_5043_50430301_2_dialog_content = "実は…",
  ui_story_5043_50430301_3_dialog_content = "先月、冠月祭に贈り物を受け取りましたの。",
  ui_story_5043_50430301_4_dialog_content = "中身はどこにでもあるようものばかりでしたけれど、\n小包には気持ちが詰まっていましたわ。",
  ui_story_5043_50430301_5_dialog_content = "お、お待ちください。聞き間違いではありませんよね？\nティナ…恋をしているということですか？",
  ui_story_5043_50430301_6_dialog_content = "あら？こういう気持ちも「恋」なのでしょうか？\n私はそうは思いませんけれど…",
  ui_story_5043_50430301_7_dialog_content = "話を聞く限り、まさに恋って感じだよ。",
  ui_story_5043_50430301_8_dialog_content = "PlayerNameさんまでそうおっしゃるのでしたら…",
  ui_story_5043_50430301_9_dialog_content = "…いえ、今はそのことはいいのです。\nまずは話を最後まで聞いてくださいませ。",
  ui_story_5043_50430301_10_dialog_content = "冠月祭からもう1か月経ちますわ。\n風習に従えば、今度は私がお返しをする番です。",
  ui_story_5043_50430301_11_dialog_content = "ですから、クッキーを焼きましたの。\nどれもこれも選びに選び抜いた形のクッキーですわ。",
  ui_story_5043_50430301_12_dialog_content = "あとは送るだけなのですけれど…",
  ui_story_5043_50430301_13_dialog_content = "プレゼントを受け取って以降、\nあちらからの連絡がまったくないのです。",
  ui_story_5043_50430301_14_dialog_content = "こっそり会うこともかなわないばかりか、\n手紙も読めませんの。",
  ui_story_5043_50430301_15_dialog_content = "そのせいで最近はよく眠れず…\n毎日16時間しか寝ていませんの…",
  ui_story_5043_50430301_16_dialog_content = "何とたちの悪いやからだ！",
  ui_story_5043_50430301_17_dialog_content = "マシューよりも悪質。",
  ui_story_5043_50430301_18_dialog_content = "そのような奴、放っておけばよかろう。",
  ui_story_5043_50430301_19_dialog_content = "でも、今はまだあきらめたくありませんの。\n何か事情があるのかもしれませんわ。",
  ui_story_5043_50430301_20_dialog_content = "あの姿では、どこへ行っても多くの人の注意を引いてしまいますでしょうし。",
  ui_story_5043_50430301_21_dialog_content = "救いようがありませんね。",
  ui_story_5043_50430301_22_dialog_content = "ん…？",
  ui_story_5043_50430301_23_dialog_content = "<size=32>PlayerNameさん、マシューさん、ローウェイさん、\nお気づきになりましたか…？</size>",
  ui_story_5043_50430301_24_dialog_content = "<size=32>ティナの話を聞いていると…\nどこか知っている人物のような気がしませんか？</size>",
  ui_story_5043_50430301_25_dialog_content = "<size=32>そういえばそうだね！\n「どこへ行っても注意を引いてしまう」…</size>",
  ui_story_5043_50430301_26_dialog_content = "<size=32>「熱心な相手を冷たくあしらい、\nうわべだけは取りつくろう」…</size>",
  ui_story_5043_50430301_27_dialog_content = "<size=32>そして「性格が悪く、大げさで、傲慢なナルシスト」。</size>",
  ui_story_5043_50430301_28_dialog_content = "<size=32>それをお前が言うか？</size>",
  ui_story_5043_50430301_29_dialog_content = "<size=32>とにかく…ティナが言っているのはやはり、\n<color=#FFB400>シュワーベ</color>のことですよね…？</size>",
  ui_story_5043_50430301_30_dialog_content = "あら？何を小声で話していらっしゃいますの？",
  ui_story_5043_50430301_31_dialog_content = "オホン…ティナ、あなたの想い人がどなたか、見当がつきました。",
  ui_story_5043_50430301_32_dialog_content = "そ、そんな！？もう分かりましたの？\nもう少し隠しておくつもりでしたのに…",
  ui_story_5043_50430301_33_dialog_content = "（ティナ、ずいぶん慌ててる…）",
  ui_story_5043_50430301_34_dialog_content = "初めて会ったのは、サラール家の荘園でした。",
  ui_story_5043_50430301_35_dialog_content = "ちょうどダンスパーティに呼ばれた日のことです。",
  ui_story_5043_50430301_36_dialog_content = "招待状に書かれていた時間よりも少し早く着いてしまい、\nお庭に案内され、そこでしばらく時間をつぶしていました。",
  ui_story_5043_50430301_37_dialog_content = "でも、サラール家の荘園のお庭はとても立派で、\nいくらもしないうちにトピアリーの迷路で迷ってしまったのです。",
  ui_story_5043_50430301_38_dialog_content = "長いこと迷って、あちこち歩いている時、\nガゼボにいる彼を見かけましたの。",
  ui_story_5043_50430301_39_dialog_content = "あちらもとても驚いた様子で、美しい青空の下、\n私たちは長い間互いに見つめ合っていましたわ…",
  ui_story_5043_50430301_40_dialog_content = "その時初めて気づいたのです。彼が本当はとてもやさしく、穏やかで善良であることに…\nその姿は周りの草花ともしっくりきていましたわ。",
  ui_story_5043_50430301_41_dialog_content = "その後、彼が先にガゼボを立ち去りました。\nでも私はその日のパーティーが終わるまで、もう他の方など目にも入りませんでした。",
  ui_story_5043_50430301_42_dialog_content = "チッ、実にロマンチックな出会いだな。",
  ui_story_5043_50430301_43_dialog_content = "（サラール家の荘園…やはりシュワーベ・サラールで間違いないようですね）",
  ui_story_5043_50430301_44_dialog_content = "（優しくて、穏やかで、善良…！？まぁ、いいか…）",
  ui_story_5043_50430301_45_dialog_content = "もう察しがついているのなら、\n皆さんに1つお願いしたいことがありますの。",
  ui_story_5043_50430301_46_dialog_content = "「<color=#FFB400>DGA</color>」計画を手伝っていただきたいのです！",
  ui_story_5043_50430301_47_dialog_content = "なんですか、その名前は…",
  ui_story_5043_50430301_48_dialog_content = "「<color=#FFB400>できるかぎり、偶然を装って会う</color>」計画、\n略して「DGA」計画です！",
  ui_story_5043_50430301_49_dialog_content = "どうせ実行できないと言っても、\nあきらめる気はないのであろう？",
  ui_story_5043_50430301_50_dialog_content = "お恥ずかしながら…",
  ui_story_5043_50430301_51_dialog_content = "いいでしょう。同僚として、お手伝いします。",
  ui_story_5043_50430301_52_dialog_content = "私もだ。",
  ui_story_5043_50430301_53_dialog_content = "グアァ…",
  ui_story_5043_50430301_54_dialog_content = "汚らわしい、こんな所に！！",
  ui_story_5043_50430301_55_dialog_content = "あら！本当ですわ、誰か？誰かいないの！？",
  ui_story_5043_50430301_56_dialog_content = "まぁ、いいでしょう。\n「神の手」もしばらく使っていませんでしたし…",
  ui_story_5043_50430301_57_dialog_content = "私が直々に片づけることにいたしますわ。",
  ui_story_5043_50430301_58_dialog_content = "…家に暗鬼が出たんだよ？ゴキブリとは違うよ！？",
  ui_story_5043_50430302_1_dialog_content = "とても気持ちのいい戦いでした…ふわぁ～…",
  ui_story_5043_50430302_2_dialog_content = "今気づいたけど、ティナって左ききだったんだね？",
  ui_story_5043_50430302_3_dialog_content = "うふふ、そうですの。「神の手」の力を受け継ぐために、\n幼い頃から訓練を受けてきましたわ。",
  ui_story_5043_50430302_4_dialog_content = "それにしても、戦いはやはり疲れますわね…",
  ui_story_5043_50430302_5_dialog_content = "これから寝るというのなら、私たちは帰りますよ？",
  ui_story_5043_50430302_6_dialog_content = "眠くなどありません！元気いっぱいですわ！",
  ui_story_5043_50430302_7_dialog_content = "先程の話を続けましょう。\nどうか「DGA」計画を手伝ってください！",
  ui_story_5043_50430302_8_dialog_content = "手伝うのはいいけど、具体的には何をすればいいの？",
  ui_story_5043_50430302_9_dialog_content = "実は…私、こういった経験がほとんどないので…\n皆さんにお聞きしたくて…",
  ui_story_5043_50430302_10_dialog_content = "いったいどんなことに気をつければよいのでしょう？",
  ui_story_5043_50430302_11_dialog_content = "そうですね…書物に人は恥を知ってはじめて勇者になるという言葉があります。\n自らの過ちを認めることが変化の第一歩という意味です。",
  ui_story_5043_50430302_12_dialog_content = "相手に自分を受け入れてもらいたければ――\nまずは<color=#FFB400>自分から告白</color>することです。",
  ui_story_5043_50430302_13_dialog_content = "相手がよく現れる場所で待ち伏せし…",
  ui_story_5043_50430302_14_dialog_content = "ひとたび姿を見かけたら、すかさず行動に出て、\n相手に考える隙を与えてはいけません！",
  ui_story_5043_50430302_15_dialog_content = "まあ！なるほど…",
  ui_story_5043_50430302_16_dialog_content = "庶民出身の新人、それは違うな。積極的なだけでは足りん。\n<color=#FFB400>己を隠す</color>ことも必要だ。",
  ui_story_5043_50430302_17_dialog_content = "本心を明かさず、\n緊張した眼差しを悟られないようにするのだ。",
  ui_story_5043_50430302_18_dialog_content = "積極的に出たものの、相手をまっすぐ見られないという時は、\n恥じらっていると装えば絶大な効果を生むであろう。",
  ui_story_5043_50430302_19_dialog_content = "そうなのですか！分かりました…",
  ui_story_5043_50430302_20_dialog_content = "それから――<color=#FFB400>探りも必要</color>。",
  ui_story_5043_50430302_21_dialog_content = "何でもない話題を振って、相手の態度を確める。",
  ui_story_5043_50430302_22_dialog_content = "数回のやりとりで、相手の本性が見えてくる。",
  ui_story_5043_50430302_23_dialog_content = "うーん…難しそうですね…でも、やってみます！",
  ui_story_5043_50430302_24_dialog_content = "僕は<color=#FFB400>真心を見せる</color>ことが大事だと思うな。",
  ui_story_5043_50430302_25_dialog_content = "長い間一緒にいると、お互いのクセや欠点が分かってくる。",
  ui_story_5043_50430302_26_dialog_content = "その時にはもう、いくら隠そうとしても無理でしょ？\nでも真心さえあれば、きっと大丈夫だよ。",
  ui_story_5043_50430302_27_dialog_content = "その通りですね！そこまで仲良くなれれば、の話ですが…",
  ui_story_5043_50430302_28_dialog_content = "分かりました、ありがとうございます！",
  ui_story_5043_50430302_29_dialog_content = "ところで…今教えてくださった方法、\n皆さんは実際に試したことがおありですか？",
  ui_story_5043_50430302_30_dialog_content = "オホン…",
  ui_story_5043_50430302_31_dialog_content = "実践経験はないんだ…ごめん…",
  ui_story_5043_50430302_32_dialog_content = "皆さんを責めるつもりで言ったのではありません！\nならば…やはり自分で試してみるしかありませんわね。",
  ui_story_5043_50430302_33_dialog_content = "とはいっても、いったいどこへ行けば会えるのでしょう？",
  ui_story_5043_50430302_34_dialog_content = "この時間帯ならばおそらく、\n人の集まるにぎやかな所にいるでしょう。",
  ui_story_5043_50430302_35_dialog_content = "え？そうなのですか…？",
  ui_story_5043_50430302_36_dialog_content = "うむ、にぎやかな所と言えば、おそらくあそこであろう。",
  ui_story_5043_50430302_37_dialog_content = "貴族と庶民が無分別に集まる――\n「月」の下だ。",
  ui_story_5043_50430302_38_dialog_content = "ど、どうしてそうなるの！？",
  ui_story_5043_50430302_39_dialog_content = "「月」に関する情報をちらほらと耳にしたのでな。\n我々もこの目で見ておく必要があろう。",
  ui_story_5043_50430302_40_dialog_content = "自分が行きたいだけ。",
  ui_story_5043_50430302_41_dialog_content = "マシューさんがおっしゃらなくても、実は私も興味がありましたの。\nそうとなれば、すぐに参りましょう！",
  ui_story_5043_50430302_42_dialog_content = "あ、でも少々お待ちください！",
  ui_story_5043_50430302_43_dialog_content = "初めて会った時の<color=#FFB400>手袋</color>をしていきます。\n手をつないだ思い出の手袋ですの。",
  ui_story_5043_50430302_44_dialog_content = "それから、クッキーも持って行きましょう！",
  ui_story_5043_50430401_1_dialog_content = "<color=#e8d9bb>アップタウン、居住区</color>",
  ui_story_5043_50430401_2_dialog_content = "この「月」のような気球が\n最近よく空に浮かんでいるというのですか？",
  ui_story_5043_50430401_3_dialog_content = "まったく気づきませんでした…",
  ui_story_5043_50430401_4_dialog_content = "太陽とアップタウンこそ肉眼で見えるものの中で、\n最も高い位置にあるものと思っていましたから。",
  ui_story_5043_50430401_5_dialog_content = "気づかなくて当然だ。お前たち庶民には\n美しい空を見上げるという雅な趣味などありはせんからな。",
  ui_story_5043_50430401_6_dialog_content = "今なんと！？",
  ui_story_5043_50430401_7_dialog_content = "あらあら、またけんかですの？",
  ui_story_5043_50430401_8_dialog_content = "子供の頃、はじめて千星の階段を訪れた時、\n階段を上ると星が見えるとお母様が教えてくれました。",
  ui_story_5043_50430401_9_dialog_content = "階段を一段上がることに星が１つ見えて、\n全部上りきると、ちょうど1000個になるのです。",
  ui_story_5043_50430401_10_dialog_content = "子供の私はうれしくなって、\n一気に一番上まで登ってしまいましたわ。",
  ui_story_5043_50430401_11_dialog_content = "それで、星はいくつ見えたの？",
  ui_story_5043_50430401_12_dialog_content = "1つも見えませんでしたわ。\nちょうどお昼でしたから、太陽しか見えませんでした。",
  ui_story_5043_50430401_13_dialog_content = "…そりゃ夜まで待たないとね…",
  ui_story_5043_50430401_14_dialog_content = "でも、夜は眠らなければいけませんわ…",
  ui_story_5043_50430401_15_dialog_content = "…",
  ui_story_5043_50430401_16_dialog_content = "ところで、マシューさんは「月」について、\nどんな情報をお聞きになったのですか？",
  ui_story_5043_50430401_17_dialog_content = "ふん、まあ冠月祭で浮かれた愚か者どもが、\n騒ぎ立ててるにすぎんがな。",
  ui_story_5043_50430401_18_dialog_content = "白夜城に月の形をした気球を浮かべ、\n自由恋愛をたたえ、広めようとしているらしい。",
  ui_story_5043_50430401_19_dialog_content = "気球が上がると、それを合図に\n賛同する者どもが一堂に会しサロンを開く。",
  ui_story_5043_50430401_20_dialog_content = "流行を追いかけ、文化人を気取りたがる貴族どもが\nずいぶんと熱心になっておるのだ。",
  ui_story_5043_50430401_21_dialog_content = "そうだったんだ…冠月祭ってそんなに盛り上がるの？\nカレンもそんなこと言ってた気はするけど…",
  ui_story_5043_50430401_22_dialog_content = "「冠月祭」の「月」にちなんで、\n月をシンボルにしたというわけですか…",
  ui_story_5043_50430401_23_dialog_content = "貴族の方々の思考とは、ずいぶん単純なのですね。",
  ui_story_5043_50430401_24_dialog_content = "私はむしろ、その気持ちがよく分かりますわ。\nだって月は愛と同様にとても純粋で、大切なものですもの。",
  ui_story_5043_50430401_25_dialog_content = "サロンの主催者もきっと、\nそうした美しい意味を込めて月をシンボルに選んだのでしょう。",
  ui_story_5043_50430401_26_dialog_content = "素晴らしい解釈です。やはり恋に落ちた乙女の目には、\n何でも美しく映るものなのでしょうか…",
  ui_story_5043_50430401_27_dialog_content = "恋ではないと言ったはずですよ…まぁいいですわ。\nとにかく、からかわないでください！",
  ui_story_5043_50430401_28_dialog_content = "ともかく気球の位置からすれば、\n今回のサロンはミッドタウンで開かれるようだな。",
  ui_story_5043_50430401_29_dialog_content = "チッ、着いたはいいが、またとめどなく歩かねばならんのか。\n護衛隊長はいつになったら千星の階段に馬車道を造るつもりだ？",
  ui_story_5043_50430401_30_dialog_content = "誰もがお前みたいに馬車に乗れるワケじゃない。",
  ui_story_5043_50430401_31_dialog_content = "千星の階段はミッドタウンとアップタウンを結ぶ通路。",
  ui_story_5043_50430401_32_dialog_content = "マシュー、庶民の世界に足を踏み入れる準備はできたか？",
  ui_story_5043_50430401_33_dialog_content = "ええい、うるさい！",
  ui_story_5043_50430401_34_dialog_content = "<color=#e8d9bb>ミッドタウン、緑の広場</color>",
  ui_story_5043_50430401_35_dialog_content = "まあ――",
  ui_story_5043_50430401_36_dialog_content = "いつの間にミッドタウンにこのような緑地ができましたの？\nとても素敵な場所ですね。",
  ui_story_5043_50430401_37_dialog_content = "この春に造られたばかりの人工芝生だと聞いています。\n光力術で日常的なメンテナンスを行っているそうです。",
  ui_story_5043_50430401_38_dialog_content = "あれ？今の聞こえた…？",
  ui_story_5043_50430401_39_dialog_content = "会場中央の月の下から、音楽が聞こえてきたみたいだよ。",
  ui_story_5043_50430401_39X1_dialog_content = "ほう…私の入手した情報によると、サロンでは語り合い、\nダンスパーティー、讃美歌鑑賞などを行うらしい。",
  ui_story_5043_50430401_40_dialog_content = "ふむ。これはれっきとした社交ダンスの音楽ではないか。\n趣味は悪くないとみえる。",
  ui_story_5043_50430401_40X1_dialog_content = "そこのお若い方たち、月のサロンは初めてですか？",
  ui_story_5043_50430401_40X2_dialog_content = "そんなところに立っていないで、さあさあ。",
  ui_story_5043_50430401_40X3_dialog_content = "おい！この私に触るでない！吐き気がする！",
  ui_story_5043_50430401_41_dialog_content = "なるほど、月のサロンのダンスパーティの時間だったのですね！",
  ui_story_5043_50430401_42_dialog_content = "立ったままでは失礼ですわ。私たちもダンスの輪に入りましょう。\nついでに集まっている方々を観察するとしましょう。",
  ui_story_5043_50430401_43_dialog_content = "で、ですが…私にはダンスのマナーやステップといった\n軽薄な心得はありません！",
  ui_story_5043_50430401_44_dialog_content = "僕もダンスはまったく…",
  ui_story_5043_50430401_45_dialog_content = "<color=#e8d9bb>…</color>",
  ui_story_5043_50430401_46_dialog_content = "…なぜこの私が庶民出身の新人と踊らねばならんのだ！？\nええい、吐き気がする！",
  ui_story_5043_50430401_47_dialog_content = "私だって嫌ですよ！",
  ui_story_5043_50430401_48_dialog_content = "あっ！！",
  ui_story_5043_50430401_49_dialog_content = "なんと不器用な男だ！足下に注意せんか…うっ！",
  ui_story_5043_50430401_50_dialog_content = "さては…わざとやりおったな？",
  ui_story_5043_50430401_51_dialog_content = "お待ちを！何をするのです！？",
  ui_story_5043_50430401_52_dialog_content = "止めてください！髪をつかまないでください…",
  ui_story_5043_50430401_53_dialog_content = "うふふ、あちらのお二人、にぎやかですわね。",
  ui_story_5043_50430401_54_dialog_content = "PlayerNameさん、緊張されてますか？",
  ui_story_5043_50430401_55_dialog_content = "いや、大丈夫だよ…",
  ui_story_5043_50430401_56_dialog_content = "左に一歩出たら、つま先を立てて、\n右に下がって、1回転…",
  ui_story_5043_50430401_57_dialog_content = "あ、あれ？手がぶつかっちゃった！？",
  ui_story_5043_50430401_58_dialog_content = "緊張しなくていいのですよ、PlayerNameさん。\nただの社交ダンスです。",
  ui_story_5043_50430401_59_dialog_content = "そのステップで間違いありませんよ。\nもう一度踊ってみましょう。",
  ui_story_5043_50430401_60_dialog_content = "うん…頑張るよ！",
  ui_story_5043_50430401_61_dialog_content = "ふふふ、ほら、おできになりましたわ。",
  ui_story_5043_50430401_62_dialog_content = "覚えが早いですわね！",
  ui_story_5043_50430401_63_dialog_content = "ふぅ、音楽が終わりました。\n全身を動かしたら、とても気持ちがよくなりましたわ。",
  ui_story_5043_50430401_64_dialog_content = "私はもう結構です…",
  ui_story_5043_50430401_65_dialog_content = "チッ、慰謝料を請求しないだけでもありがたいと思え。",
  ui_story_5043_50430401_66_dialog_content = "それにしても、ローウェイの奴はどこへ行った…？",
  ui_story_5043_50430401_67_dialog_content = "面倒は避けられたようだ。",
  ui_story_5043_50430401_68_dialog_content = "さっき会場の外で、明らかにサロン参加者ではない\n不審な人物を見かけた。",
  ui_story_5043_50430401_69_dialog_content = "様子を見に行ったら、カレン殿下がいた。",
  ui_story_5043_50430401_70_dialog_content = "案内感謝するわ。\nあなたの言う「不審な人物」は、私が手配した者よ。",
  ui_story_5043_50430401_71_dialog_content = "まあ！？カレン殿下もおいででしたの？",
  ui_story_5043_50430401_72_dialog_content = "カレン！どうだった？暗鬼の調査の結果は？",
  ui_story_5043_50430401_73_dialog_content = "まだ結果は出ていないけれど、\n消去法でいくつかの可能性に絞られたわ。",
  ui_story_5043_50430401_74_dialog_content = "通行証には問題がなかった。\nつまり、暗鬼が何者かになりすまして白夜城に紛れ込んだ可能性は低い。",
  ui_story_5043_50430401_75_dialog_content = "夜間の警備にも落ち度はなかったし、\n白夜城上空のシールドも問題なかったわ。",
  ui_story_5043_50430401_76_dialog_content = "このところ祝日が続いていて、\n物資を運ぶ貿易商や傭兵もおおぜい白夜城に出入りしているから…",
  ui_story_5043_50430401_77_dialog_content = "衛兵の検査が行き届かず、\n貨物の中に暗鬼が紛れ込んでいた可能性は否定できないわね。",
  ui_story_5043_50430401_78_dialog_content = "カレン殿下は白夜城に紛れ込んだ暗鬼の調査をされているのですか？",
  ui_story_5043_50430401_79_dialog_content = "やはり…急いで見つけないと…",
  ui_story_5043_50430401_80_dialog_content = "心配はいりません。\n無事に決まっています。",
  ui_story_5043_50430401_81_dialog_content = "ほ、本当でしょうか…",
  ui_story_5043_50430401_82_dialog_content = "（ティナ、何を心配してるんだろう…？何かおかしいな…）",
  ui_story_5043_50430401_83_dialog_content = "とにかく、私たちの調査を逃れられるとなると、\n糸を引いている暗鬼は<color=#FFB400>変装能力</color>を使って、人混みの中に紛れ込んでいる可能性があるわ。",
  ui_story_5043_50430401_84_dialog_content = "不必要に民の恐怖をあおらないよう、\n全域捜査はしていない…",
  ui_story_5043_50430401_85_dialog_content = "代わりに隊員を私服に着替えさせて、\n不測の事態が起こらないよう、人の集まるところを見回りさせているわ。",
  ui_story_5043_50430401_86_dialog_content = "冠月祭後の対策に関しては、\nカレンとお父さん、考えることが似てるね。",
  ui_story_5043_50430401_87_dialog_content = "…誉め言葉には聞こえないわね。",
  ui_story_5043_50430401_88_dialog_content = "あはは…ごめん。それより僕も手伝おうか？",
  ui_story_5043_50430401_89_dialog_content = "こういう人の集まる所に暗鬼がいたら困るでしょ…",
  ui_story_5043_50430401_90_option_content = "強制感知",
  ui_story_5043_50430401_91_dialog_content = "ありがとう、PlayerName。",
  ui_story_5043_50430401_92_dialog_content = "どう？異常はない？",
  ui_story_5043_50430401_93_dialog_content = "う～ん…",
  ui_story_5043_50430401_94_dialog_content = "ダメだ。こんなににぎやかだと、感知が効かない…",
  ui_story_5043_50430401_95_dialog_content = "カレン殿下、PlayerName！",
  ui_story_5043_50430401_96_dialog_content = "そんな所に突っ立っている場合ではございませぬぞ。\n早くこちらへ！",
  ui_story_5043_50430401_97_dialog_content = "PlayerName、せっかく来たのだから、\n私たちも見に行きましょう。",
  ui_story_5043_50430401_98_dialog_content = "この月の気球、近くで見るとずいぶん立派ね。",
  ui_story_5043_50430401_99_dialog_content = "殿下もそう思われますか？",
  ui_story_5043_50430401_100_dialog_content = "春の息吹あふれる芝生、恋に落ちた男女、\nどこからともなく聞こえてくる聖歌隊の歌声…",
  ui_story_5043_50430401_101_dialog_content = "普段は近くで見ることのできない美しい月の下で、\n階級を越え、思う存分互いの考えを語り合う…",
  ui_story_5043_50430401_102_dialog_content = "まるで神話の中の光景ですわ。",
  ui_story_5043_50430401_103_dialog_content = "フン、「考え」などありはせんわ。\nただ愛だの恋だのと騒ぎ立てる場にすぎん。",
  ui_story_5043_50430401_104_dialog_content = "それにしても一度にこれほど多くの庶民を見るのは初めてだ。\nダウンタウンの空気が充満しておるわ…うう、吐き気が…",
  ui_story_5043_50430401_105_dialog_content = "今さら後悔しても遅い。",
  ui_story_5043_50430401_106_dialog_content = "ところで、新人の庶民。\n何をぼやっとしておるのだ？",
  ui_story_5043_50430401_107_dialog_content = "この月…何だか不思議だなと思っていたのです。",
  ui_story_5043_50430401_108_dialog_content = "糸でつないでいるわけでもないのに、飛ばされず同じ所に浮かんでいます…\n光力術で制御しているのでしょうか…？",
  ui_story_5043_50430401_109_dialog_content = "…いいえ、聞かなかったことにしてください。\n庶民の所帯じみた疑問にすぎませんので。",
  ui_story_5043_50430401_110_dialog_content = "お察しの通りです。気球を浮かせている光力術は…",
  ui_story_5043_50430401_111_dialog_content = "中の<color=#FFB400>古来の祝日からの贈り物</color>を維持するためにも使われています。",
  ui_story_5043_50430401_112_dialog_content = "失礼ですが、あなたは？",
  ui_story_5043_50430401_113_dialog_content = "白夜城のごく普通の修道女です。\n修道女と呼んでくだされば結構です。",
  ui_story_5043_50430401_114_dialog_content = "最近の月のサロンはすべて私が主催したものです。",
  ui_story_5043_50430401_115_dialog_content = "初めてお見かけしたように思いますが、\nいかがです？月のサロンはお気に召しましたか？",
  ui_story_5043_50430401_116_dialog_content = "き、来たばかりでよく分かりませんが、\n新鮮な感じがしますね…",
  ui_story_5043_50430401_117_dialog_content = "僕の知っている白夜城とは少し雰囲気が違います。",
  ui_story_5043_50430401_118_dialog_content = "ふふ、お言葉痛み入ります。光の神の祝福がありますように。\nそれでは私は失礼いたします。",
  ui_story_5043_50430401_119_dialog_content = "テーブルにあるお茶とお菓子はご自由にどうぞ。\n聖歌隊の讃美歌もお聴きになるとよいでしょう。",
  ui_story_5043_50430401_120_dialog_content = "（聖歌隊って、まさか…）",
  ui_story_5043_50430401_121_dialog_content = "月のサロンに来たんだね♪",
  ui_story_5043_50430401_122_dialog_content = "本当に来たね♪",
  ui_story_5043_50430401_123_dialog_content = "サロンで何もしないでぶらぶらしてるね♪",
  ui_story_5043_50430401_124_dialog_content = "まだ独身でしょ？独身だ♪",
  ui_story_5043_50430401_125_dialog_content = "可愛らしい子たちでしょう？",
  ui_story_5043_50430401_126_dialog_content = "どこが可愛いんですか！？",
  ui_story_5043_50430401_127_dialog_content = "丸々太って、つつけばボーン♪",
  ui_story_5043_50430401_128_dialog_content = "空の上にお高く留まってる♪",
  ui_story_5043_50430401_129_dialog_content = "何を讃えているのかな♪",
  ui_story_5043_50430401_130_dialog_content = "くだらないお貴族さんと月の気球だよ♪",
  ui_story_5043_50430401_131_dialog_content = "あら、黎明学院の聖歌隊まで呼ばれているのね。",
  ui_story_5043_50430401_132_dialog_content = "あの子たちの讃美歌ときたら…相変わらずね…",
  ui_story_5043_50430401_133_dialog_content = "男の人と女の人が月の下で楽しく語り合う♪",
  ui_story_5043_50430401_134_dialog_content = "平民と貴族が同じテーブルを囲んでケーキをほおばる♪",
  ui_story_5043_50430401_135_dialog_content = "尊敬する、可愛らしい修道女さん♪",
  ui_story_5043_50430401_136_dialog_content = "月のサロン、いい集まりだね♪",
  ui_story_5043_50430401_137_dialog_content = "一瞬何を歌っているのかよく分かりませんが、\nよくよく聴くとなかなかよい歌詞ですね…",
  ui_story_5043_50430401_138_dialog_content = "あら、こんなところで聖歌隊に会えるなんて幸運ですわ。\nお祈りしなければ。",
  ui_story_5043_50430401_139_dialog_content = "白夜に捧ぐ、光の神よ。\nどうか彼に会わせてくださいませ。",
  ui_story_5043_50430401_140_dialog_content = "光の神に願うことではなかろうが…",
  ui_story_5043_50430401_141_dialog_content = "白夜城では皆が光の神を信じてる♪",
  ui_story_5043_50430401_142_dialog_content = "でも貴族と平民は自由に結婚できないよ♪",
  ui_story_5043_50430401_143_dialog_content = "尊敬する、可哀想な修道女さん♪",
  ui_story_5043_50430401_144_dialog_content = "愚かなお偉いさんたちを怒らせた、\n大きな災いが降ってくるよ♪",
  ui_story_5043_50430401_145_dialog_content = "え、ええ？",
  ui_story_5043_50430401_146_dialog_content = "この辺り一帯を粛清する。\n不法に集会を開く者どもをすべて捉えるのだ。",
  ui_story_5043_50430401_147_dialog_content = "首謀者を必ず連行せよ。",
  ui_story_5043_50430401_148_dialog_content = "きゃあ――",
  ui_story_5043_50430401_149_dialog_content = "アップタウンの護衛隊だ、捕まるぞ！逃げろ！",
  ui_story_5043_50430401_150_dialog_content = "わ、私はアップタウンに住まう貴族であるぞ。\n捕えられるものなら、捕えるがいい…",
  ui_story_5043_50430401_151_dialog_content = "うわぁ！？",
  ui_story_5043_50430401_152_dialog_content = "ああ…<color=#FFB400>クッキー</color>が！",
  ui_story_5043_50430401_153_dialog_content = "彼に贈るクッキーが<color=#FFB400>失くなってしまいました</color>！",
  ui_story_5043_50430401_154_dialog_content = "<color=#e8d9bb>ガヤガヤ…ザワザワ…</color>",
  ui_story_5043_50430401_155_dialog_content = "（そんなはずは！私の護衛隊ではないわ！）",
  ui_story_5043_50430401_156_dialog_content = "あなたたち、私の命令もなく…",
  ui_story_5043_50430401_157_dialog_content = "カレン殿下！",
  ui_story_5043_50430401_158_dialog_content = "アップタウンの護衛隊ではありません。",
  ui_story_5043_50430401_159_dialog_content = "ですが、アップタウン以外で兵を持っている貴族は稀です。",
  ui_story_5043_50430401_160_dialog_content = "サロンの参加者たちはきっと、\n今回の取締をアップタウンの意志だととらえるでしょう！",
  ui_story_5043_50430401_161_dialog_content = "…言いたいことは分かるわ。\nけれど混乱をおさめる方が先よ！",
  ui_story_5043_50430401_162_dialog_content = "皆さん、慌てずに私に付いてきてください！",
  ui_story_5043_50430401_163_dialog_content = "<color=#e8d9bb>バンッ――</color>",
  ui_story_5043_50430401_164_dialog_content = "（何の音だ！？）",
  ui_story_5043_50430401_165_dialog_content = "PlayerName、旋槍騎士、力を貸してちょうだい。",
  ui_story_5043_50430401_166_dialog_content = "辺りにいる私服の衛兵と一緒に、\nむやみに民衆を捕らえるこの兵士たちを制圧するのよ！",
  ui_story_5043_50430401_167_dialog_content = "任せて！",
  ui_story_5043_50430401_168_dialog_content = "仰せの通りに。",
  ui_story_5043_50430501_1_dialog_content = "ずいぶんと逃げ足が速いですね！",
  ui_story_5043_50430501_2_dialog_content = "カレン殿下、追跡を続けますか？",
  ui_story_5043_50430501_3_dialog_content = "…もういいわ。自分の仕事に戻って。",
  ui_story_5043_50430501_4_dialog_content = "実に残念です…サロンが台無しになってしまったばかりか、\n探していた人物にも会えませんでした…",
  ui_story_5043_50430501_5_dialog_content = "探していた人物？誰を探していたの？",
  ui_story_5043_50430501_6_dialog_content = "私ではなく、ティナです。\nシュワーベに冠月祭のお返しを渡したいとかで…",
  ui_story_5043_50430501_7_dialog_content = "あの2人がそんな関係だったのね。",
  ui_story_5043_50430501_8_dialog_content = "これも冠月祭の影響なのかしら？\n一族同士の婚約の取り決めのない若者たちが自由恋愛をおう歌している…",
  ui_story_5043_50430501_9_dialog_content = "ただ、悪いけど…あんな軽薄な男のどこがいいのかしら？",
  ui_story_5043_50430501_10_dialog_content = "本当にそうだよね…",
  ui_story_5043_50430501_11_dialog_content = "それはそうと、ローウェイを見なかった？",
  ui_story_5043_50430501_12_dialog_content = "衛兵がいなくなってから、見かけてないけど。",
  ui_story_5043_50430501_13_dialog_content = "私が衛兵の正体を調べに行かせたのよ。\nあなたたちは事件の調査を続けるといいわ。",
  ui_story_5043_50430501_14_dialog_content = "本当は調べなくても大方予想はついているのだけれど…\n確認しておきたいの。",
  ui_story_5043_50430501_15_dialog_content = "た、大変です！",
  ui_story_5043_50430501_16_dialog_content = "分かっていますよ。準備してきたクッキーが\n失くなってしまったのですよね？",
  ui_story_5043_50430501_17_dialog_content = "散らかった食べ物の中にないか、\nもう少し探してみましょう。",
  ui_story_5043_50430501_18_dialog_content = "いいえ、「クッキーがなくなった」だけならよいのです！",
  ui_story_5043_50430501_19_dialog_content = "広場の入り口に立っていた彫像が…",
  ui_story_5043_50430501_20_dialog_content = "先程の騒ぎで<color=#FFB400>壊された</color>のだ。",
  ui_story_5043_50430501_21_dialog_content = "え！？",
  ui_story_5043_50430501_22_dialog_content = "群衆があちこち逃げまどっている時、\n何かが割れるような高い音がした。",
  ui_story_5043_50430501_23_dialog_content = "しかも実に奇妙なことに、この彫像の壊され方は\n法廷の彫像の壊され方とそっくりなのだ。",
  ui_story_5043_50430501_24_dialog_content = "まるで「首切り」か何かに「殺害」されたかのようだ。",
  ui_story_5043_50430501_25_dialog_content = "大変なことになりましたね…やはり裁判長であるあの方に、\n進捗を報告した方がよいでしょう。",
  ui_story_5043_50430501_26_dialog_content = "それもそうだな。月のサロンにおらぬとなれば、\nおそらく――",
  ui_story_5043_50430501_27_dialog_content = "<color=#e8d9bb>高庭、シュワーベの執務室</color>",
  ui_story_5043_50430501_28_dialog_content = "ふむ…なるほど、分かりました。",
  ui_story_5043_50430501_29_dialog_content = "ちょうどよいところに戻ってきてくれました。\n彫像事件は今原告の訴訟手続き待ちですから、ひとまず置いておきましょう。",
  ui_story_5043_50430501_30_dialog_content = "それよりも、この後すぐに別の恋愛訴訟が開廷になります。\nさあ、準備してください。私の愛しい部下たち！",
  ui_story_5043_50430501_31_dialog_content = "ずいぶん急だね？",
  ui_story_5043_50430501_32_dialog_content = "ここは恋愛訴訟部ですからね。\n光力術で動く馬車のように一時も休むことはないのです！",
  ui_story_5043_50430501_33_dialog_content = "裁判長の椅子に座ったことのない貴方には、\nお分かりにならないでしょうね。タンポポの坊や。",
  ui_story_5043_50430501_34_dialog_content = "タ、タンポポの坊や？？",
  ui_story_5043_50430501_35_dialog_content = "（…僕のことだよね…き、気持ち悪い！）",
  ui_story_5043_50430501_36_dialog_content = "…そのうちに慣れますよ。",
  ui_story_5043_50430501_37_dialog_content = "それはそうと、シュワーベ裁判長。\n実はティナからお話しが…",
  ui_story_5043_50430501_38_dialog_content = "おい、その件は今話すにはふさわしくなかろう？",
  ui_story_5043_50430501_39_dialog_content = "（その通りですわ…ラインさんったら、\nシュワーベ裁判長に報告なんて…）",
  ui_story_5043_50430501_40_dialog_content = "おや？私の愛しい部下たちはすでに秘密を共有するほど、\n仲良くなっていたのですか！？",
  ui_story_5043_50430501_41_dialog_content = "…とにかく、こちらが起訴状と関連資料です。\nとても単純な事件です。それでは後ほど恋愛訴訟部でお会いしましょう！",
  ui_story_5043_50430501_42_dialog_content = "確かに複雑な案件ではなさそうですわ。\nこの件もまた月のサロンと関係があるようですが…",
  ui_story_5043_50430501_43_dialog_content = "…あらっ！？お待ちください！\nこちらの「理由」をご覧になって…！",
  ui_story_5043_50430501_44_dialog_content = "<color=#e8d9bb>恋愛訴訟部</color>",
  ui_story_5043_50430501_45_dialog_content = "すごく立派な建物だね…\nソルラドさんって本当にやることが速くて、何をするにも手を抜かないよね。",
  ui_story_5043_50430501_46_dialog_content = "そうね。一日に受理する訴訟件数から考えれば、\nこれだけの予算を使っても無駄ではないでしょう。",
  ui_story_5043_50430501_47_dialog_content = "<color=#e8d9bb>カン――</color>",
  ui_story_5043_50430501_48_dialog_content = "開廷します！",
  ui_story_5043_50430501_49_dialog_content = "まず初めに訴訟当事者とその他証人の情報確認を行います！",
  ui_story_5043_50430501_50_dialog_content = "原告、白夜城ダウンタウン在住、男性。\n個人情報保護のため、氏名非公開とします。",
  ui_story_5043_50430501_51_dialog_content = "被告、白夜城ダウンタウン在住、女性。\n個人情報保護のため、氏名非公開とします。",
  ui_story_5043_50430501_52_dialog_content = "（よく聞こえない！！）",
  ui_story_5043_50430501_53_dialog_content = "本法廷は私シュワーベ・サラールが裁判長を務め――",
  ui_story_5043_50430501_54_dialog_content = "裁判官マシュー・サーイエ、ティナ・キャンベル、ライン…",
  ui_story_5043_50430501_55_dialog_content = "および若干名の陪審員によって審理が行われます。",
  ui_story_5043_50430501_56_dialog_content = "（へえ、真面目に話してるシュワーベは、結構サマになってる…）",
  ui_story_5043_50430501_57_dialog_content = "以上法廷構成員に異議がなければ、本件の審理を開始します。",
  ui_story_5043_50430501_58_dialog_content = "待たれよ！なぜ我々陪審員は\n「若干名」で済まされねばならんのだ！？",
  ui_story_5043_50430501_59_dialog_content = "異議はないようですね。\nそれでは本件の法廷審理に入ります。",
  ui_story_5043_50430501_60_dialog_content = "原告は本件の申し立て、\nおよびその事実、理由を述べてください。",
  ui_story_5043_50430501_61_dialog_content = "ううう…ぐすっ…実は、こういう訳で…",
  ui_story_5043_50430501_62_dialog_content = "僕と婚約者、つまり被告は…\n今日ミッドタウンの緑地で開かれていた月のサロンに参加しました…",
  ui_story_5043_50430501_63_dialog_content = "そ、それなのに…彼女は…",
  ui_story_5043_50430501_64_dialog_content = "原告、泣いていては分かりませんよ。\nきちんとお話しください。",
  ui_story_5043_50430501_65_dialog_content = "僕は…本当に彼女のことが好きなのです。\n今年で交際4年目ですが、彼女はコーヒーを飲みながらチョコを食べるのが好きで…",
  ui_story_5043_50430501_66_dialog_content = "原告は要点と本件に関わる内容のみをお話しください。",
  ui_story_5043_50430501_67_dialog_content = "も、申し訳ありません。\n僕は本当に…何をやってもダメな男で…",
  ui_story_5043_50430501_68_dialog_content = "最初は月のサロンで楽しく過ごしていたのですが、\n突然彼女が顔色を変え、「別れる」と言い出したのです！",
  ui_story_5043_50430501_69_dialog_content = "…こんなことになって、家族にどう説明すればいいのか…\nう、ううっ…ぐすっ…",
  ui_story_5043_50430501_70_dialog_content = "分かりました。\n続いて、被告側の陳述に入ります。",
  ui_story_5043_50430501_71_dialog_content = "もちろん、理由があってのことです。",
  ui_story_5043_50430501_72_dialog_content = "この男、つまり原告はデート中にも関わらず…",
  ui_story_5043_50430501_73_dialog_content = "サロンで他の女性からプレゼントを受け取ったんです！",
  ui_story_5043_50430501_74_dialog_content = "（だったら、この人が原告でもいい気がするけど…）",
  ui_story_5043_50430501_75_dialog_content = "僕はそんなこと…",
  ui_story_5043_50430501_76_dialog_content = "だったら説明してちょうだいよ。\nあのカゴに入った<color=#FFB400>クッキー</color>はどういうこと？",
  ui_story_5043_50430501_77_dialog_content = "（…カゴに入ったクッキー？まさか…）",
  ui_story_5043_50430501_78_dialog_content = "これです、これが物証です！",
  ui_story_5043_50430501_79_dialog_content = "クッキーはあなたの席に置いてあったのよ。\n中にはカードまで入ってたわ。",
  ui_story_5043_50430501_80_dialog_content = "何よりも最低なのは、カードには私しか知らない、\n<color=#FFB400>愛称</color>が書いてあったじゃない！",
  ui_story_5043_50430501_81_dialog_content = "なんてことでしょう…",
  ui_story_5043_50430501_82_dialog_content = "やはりそうでしたか。訴状に書いてあった通り、\nティナの用意していたクッキーはこのカップルが拾っていたのですね。",
  ui_story_5043_50430501_83_dialog_content = "<color=#e8d9bb>カン！カン！カン！</color>",
  ui_story_5043_50430501_84_dialog_content = "静粛に！",
  ui_story_5043_50430501_85_dialog_content = "法廷を軽んじる者は裁判長の私が死刑を申し渡しますよ！\n…ふふ、もちろん冗談ですが。",
  ui_story_5043_50430501_86_dialog_content = "<size=32>ねえ、ティナ。\nあれって君が失くしたクッキーだよね？</size>",
  ui_story_5043_50430501_87_dialog_content = "<size=32>あら？PlayerNameさん…！</size>",
  ui_story_5043_50430501_88_dialog_content = "<size=32>いけません。裁判中の私語は禁じられています。</size>",
  ui_story_5043_50430501_89_dialog_content = "<size=32>そうなんだ。じゃあ――</size>",
  ui_story_5043_50430501_90_option_content = "強制感知！",
  ui_story_5043_50430501_91_dialog_content = "まあ、すごい！これが空の末裔の能力ですの！？\n私もついに体験できますわ！",
  ui_story_5043_50430501_92_dialog_content = "今はそのことはいいから…\nとにかく、あのクッキーってやっぱり君のだよね？",
  ui_story_5043_50430501_93_dialog_content = "ええ、私のですわ！なんてことでしょう！\n私の不注意で仲の良いカップルの間に誤解が生じてしまいました…",
  ui_story_5043_50430501_94_dialog_content = "PlayerNameさん、どうしたらよいでしょうか？",
  ui_story_5043_50430501_95_option_content = "ありのままを話す",
  ui_story_5043_50430501_96_dialog_content = "自分が用意したクッキーだってありのままを認めて、\n他の人にあげるつもりだったことも話すんだ。",
  ui_story_5043_50430501_97_dialog_content = "…ただ、それはある意味、告白にもなるから…",
  ui_story_5043_50430501_98_dialog_content = "君がそうしたくないって言うなら、\n僕は君の意志を尊重するよ…",
  ui_story_5043_50430501_99_dialog_content = "え？告白ですか…？何の告白でしょう？",
  ui_story_5043_50430501_100_option_content = "状況を見守る",
  ui_story_5043_50430501_101_dialog_content = "まずは何もしないで、この後の展開を見守ろう！",
  ui_story_5043_50430501_102_dialog_content = "勝手に発言したら、\n「法廷を軽んじた」罪を着せられちゃうしね。",
  ui_story_5043_50430501_103_dialog_content = "法廷審理の流れに従うと、この後は何をするの？",
  ui_story_5043_50430501_104_dialog_content = "原告側と被告側双方による論告および弁論になります。",
  ui_story_5043_50430501_105_dialog_content = "PlayerNameさんがなぜクッキーのことを気にされるのか分かりませんが、\nひとまずここはシュワーベさんに任せて裁判を見守りましょう。",
  ui_story_5043_50430501_106_dialog_content = "どうやら原告も被告も審理をお急ぎのようですね。\nでは、論告および弁論に入ります。",
  ui_story_5043_50430501_107_dialog_content = "<size=32>おい、新人の庶民。このままではまずいのではないか？</size>",
  ui_story_5043_50430501_108_dialog_content = "<size=32>手をこまねいているわけにもいかんが、\nティナの顔も立てねばなるまい。</size>",
  ui_story_5043_50430501_109_dialog_content = "<size=32>私も同意見です。ですが…\nティナがどう思っているのか分かりませんし…</size>",
  ui_story_5043_50430501_110_dialog_content = "<size=32>本人に話す気がないのなら…\nシュワーベが気づくように仕向けるのはいかがでしょう？</size>",
  ui_story_5043_50430501_111_dialog_content = "<size=32>よかろう！フン、庶民にしては頭が回るようだな。</size>",
  ui_story_5043_50430501_112_dialog_content = "続いて、裁判官による原告、被告に対する尋問を行います。",
  ui_story_5043_50430501_113_dialog_content = "オホン、ええ…では、原告にお尋ねします。\nクッキーが貴方のものではないのなら、どなたのものだと思われますか？",
  ui_story_5043_50430501_114_dialog_content = "それは…僕にも分かりません。\nとにかく突然僕の目の前に現れたので…",
  ui_story_5043_50430501_115_dialog_content = "<color=#FFB400>誰かが落とした</color>ものではないでしょうか。",
  ui_story_5043_50430501_116_dialog_content = "ほう？もしその通りならば、クッキーは月のサロンの最中に現れ、\n月のサロンの最中に失くなった、ということになりますな。",
  ui_story_5043_50430501_117_dialog_content = "ならば、クッキーの贈り主の意図は、\n私が言わずともお分かりでしょうな。",
  ui_story_5043_50430501_118_dialog_content = "はい、たぶん…誰かへの<color=#FFB400>プレゼント</color>だと思います。",
  ui_story_5043_50430501_119_dialog_content = "ただ、僕へのプレゼントでないことは確かです！\n僕とは何の関係もありません！",
  ui_story_5043_50430501_120_dialog_content = "続いて被告にお尋ねします。\n貴方はなぜ、恋人がクッキーをもらったことが自身への不義だとお考えなのですか？",
  ui_story_5043_50430501_121_dialog_content = "そんなこと説明する必要もないでしょう？\nこのクッキーは明らかに<color=#FFB400>女性</color>が用意したものです！",
  ui_story_5043_50430501_122_dialog_content = "それなのに受け取るなんて、\n私と別れたいと思っているからに決まってます。",
  ui_story_5043_50430501_123_dialog_content = "問題の所在はそこですな。原告は受け取っていないと言い、\nあなたは原告に贈られたものだと言い張っている…",
  ui_story_5043_50430501_124_dialog_content = "でも、<color=#FFB400>カード</color>には明らかに2人の仲をほのめかす内容が…",
  ui_story_5043_50430501_125_dialog_content = "…いいでしょう、確かに私の思い込みもあったかもしれません。\nでも、だったら相手の女はいったい誰に贈ろうとしてたんです？",
  ui_story_5043_50430501_126_dialog_content = "今おっしゃったことこそ、この事件の要です！",
  ui_story_5043_50430501_127_dialog_content = "このクッキーを受け取るはずだった人物は\nあなたの目の前におりますぞ！",
  ui_story_5043_50430501_128_dialog_content = "私の…目の前？",
  ui_story_5043_50430501_129_dialog_content = "<color=#e8d9bb>カン！カン！カン！</color>",
  ui_story_5043_50430501_130_dialog_content = "ライン裁判官、マシュー裁判官！\n誘導尋問を禁じます！",
  ui_story_5043_50430501_131_dialog_content = "ここは法廷ですよ。事実に従い、裁決を下す所です。",
  ui_story_5043_50430501_132_dialog_content = "おやおや、シュワーベ裁判長。多くの女性から愛慕されるあなたのような色男が\nレディーの発言をさえぎるとは何たることですかな？",
  ui_story_5043_50430501_133_dialog_content = "貴方への思いがつまった物証を前にしても、\nそれがどの女性から贈られたものか、お分かりにならないとは！",
  ui_story_5043_50430501_134_dialog_content = "あ…！分かりました…\nまさかこのクッキー…本当は――",
  ui_story_5043_50430501_135_dialog_content = "な、何です…？",
  ui_story_5043_50430501_136_dialog_content = "静粛に！！",
  ui_story_5043_50430501_137_dialog_content = "皆さん、どうかお静かに。私の話を聞いてください。",
  ui_story_5043_50430501_138_dialog_content = "ティナ裁判官、勝手な発言で審理の流れを妨げないでいただきたい！",
  ui_story_5043_50430501_139_dialog_content = "シュワーベ裁判長、そのクッキーの贈り主として、\nこの私が<color=#FFB400>証人</color>となることをお許しください。",
  ui_story_5043_50430501_140_dialog_content = "（ティナ、いいですよ！その調子です！）",
  ui_story_5043_50430501_141_dialog_content = "よ、よろしい…裁判長として許可しましょう。\nでは、証言を始めてください。",
  ui_story_5043_50430501_142_dialog_content = "そのクッキーは私が作りました。",
  ui_story_5043_50430501_143_dialog_content = "胸の高鳴りと不安の入り混じる感情を抑えながら、\n手作りしたクッキーです。",
  ui_story_5043_50430501_144_dialog_content = "バタークリームを絞り出して模様を作り、\n形がきれいなものだけを選んで、こんがりと焼き上げました。",
  ui_story_5043_50430501_145_dialog_content = "この世で一番素敵なプレゼントをお返ししたい一心で作りました。",
  ui_story_5043_50430501_146_dialog_content = "でも、先程月のサロンで…うっかり失くしてしまったのです。",
  ui_story_5043_50430501_147_dialog_content = "そのカードが証拠です！",
  ui_story_5043_50430501_148_dialog_content = "カードも私が手作りしたものです。\n書いてある内容も相手の名前も一字一句違わず申し上げてみせますわ！",
  ui_story_5043_50430501_149_dialog_content = "まあ！…まさかこんな形で持ち主と会うなんて…",
  ui_story_5043_50430501_150_dialog_content = "これもまたステキなラブストーリーね。",
  ui_story_5043_50430501_151_dialog_content = "…まったく困ったものですね。美しい女性はいつだって、\nこの私に甘い負担を強いるのですから。",
  ui_story_5043_50430501_152_dialog_content = "ならば、判決を下す前に、\n証人には被告と証拠品の確認を行っていただきましょう。",
  ui_story_5043_50430501_153_dialog_content = "では、同時にカードに書かれた名前を言うことにいたしましょう。",
  ui_story_5043_50430501_154_dialog_content = "分かりました、そうしましょう。\nでは…せいのっ――",
  ui_story_5043_50430501_155_dialog_content = "<size=45><color=#FFB400>ボーン</color>！</size>",
  ui_story_5043_50430501_X156_dialog_content = "えっ？",
  ui_story_5043_50430501_156_dialog_content = "…何ですと！！/なにぃっ！！",
  ui_story_5043_50430501_157_dialog_content = "シュワーベ裁判長、人は見かけによらないものなんですね。\n名門のご出身で、浮名もずいぶんと流されていると聞きましたが…",
  ui_story_5043_50430501_158_dialog_content = "裏では…こんな「親しみやすい」名前で呼ばれていたなんて！",
  ui_story_5043_50430501_159_dialog_content = "ダウンタウン出身の者として、尊敬してしまいます。",
  ui_story_5043_50430501_160_dialog_content = "ああ、愛しの君！もう僕を疑ってないんだね。ううぅ…",
  ui_story_5043_50430501_161_dialog_content = "「ボーン」…ふふっ、これはこれは。\n実に可愛らしいではないか。",
  ui_story_5043_50430501_162_dialog_content = "シュワーベ、「ボーン」とはお主の幼名か？\nそれともあだ名か何かか？",
  ui_story_5043_50430501_163_dialog_content = "アハハハハ…",
  ui_story_5043_50430501_164_dialog_content = "そ…それは…",
  ui_story_5043_50430501_165_dialog_content = "お待ちください、いったいどういうことなのですか？",
  ui_story_5043_50430501_166_dialog_content = "そうですわ。いったいどういうことですの？",
  ui_story_5043_50430501_167_dialog_content = "このクッキーとカード…シュワーベ裁判長と何の関係がありますの？",
  ui_story_5043_50430601_1_dialog_content = "事の次第は…今お話しした通りです。",
  ui_story_5043_50430601_2_dialog_content = "クッキーは確かに私がボーンのために用意したものですが、\n先程の様子からすると、被告はどうやら勘違いをなさっていたようで…",
  ui_story_5043_50430601_3_dialog_content = "こんなことになるとは思ってもいませんでした。\n原告と被告の間の誤解が解けたのは幸いでしたが…",
  ui_story_5043_50430601_4_dialog_content = "なんと！",
  ui_story_5043_50430601_5_dialog_content = "つまり原告と被告だけでなく、\n私たちも誤解していたというわけですか？",
  ui_story_5043_50430601_6_dialog_content = "ならば「ボーン」とは誰だ？\nお前が思いを寄せる相手とは、この愚かな裁判長ではないのか！？",
  ui_story_5043_50430601_7_dialog_content = "確かにちょっとおかしいなと思うところはあったけど…\nどこで勘違いしちゃったのかな？",
  ui_story_5043_50430601_8_dialog_content = "申し訳ございません。何しろ堂々とお話しすることでもなかったので、\nはっきり申し上げなかったのがいけませんでしたわ。",
  ui_story_5043_50430601_9_dialog_content = "お手伝いをお願いするなら、\nきちんとお話しすべきだったのです…！",
  ui_story_5043_50430601_10_dialog_content = "ただ…先程の法廷では、なぜシュワーベ裁判長まで\n誤解なさったのでしょうか？",
  ui_story_5043_50430601_11_dialog_content = "私たち、お仕事と社交界でのお付き合い以外、\nほとんど接触はございませんでしょう？",
  ui_story_5043_50430601_12_dialog_content = "誰が真に思いを寄せてくれているのか、\n本人が一番よく分かるものではないのですか？",
  ui_story_5043_50430601_13_dialog_content = "その話はもう…よしましょうか…",
  ui_story_5043_50430601_14_dialog_content = "…今お話しになったことは…大した問題ではありません。\n本当に問題なのは…",
  ui_story_5043_50430601_15_dialog_content = "<size=45>今や法廷の全員が私のあだ名は\nボーンだと思い込んでしまったことです！！</size>",
  ui_story_5043_50430601_16_dialog_content = "<size=45>下級裁判官たちは今頃もう、\nこの話をそこら中に広めていることでしょう！！</size>",
  ui_story_5043_50430601_17_dialog_content = "<size=45>このウワサはすぐにアップタウンの社交界で、\nビッグニュースとしてささやかれるようになってしまいます！！</size>",
  ui_story_5043_50430601_18_dialog_content = "<size=45>それもこれも皆、\n貴方たちとその気色の悪いクッキーとカードのせいです！！</size>",
  ui_story_5043_50430601_19_dialog_content = "<size=45>貴方たちのように恋だの愛だのしか頭にない愚かな男女も、\nいつまでもしつこく付きまとう女性たちも…</size>",
  ui_story_5043_50430601_20_dialog_content = "<size=45>皆疫病神です！！</size>",
  ui_story_5043_50430601_21_dialog_content = "ほ、本当に申し訳ございません！！",
  ui_story_5043_50430601_22_dialog_content = "お待ちください。ティナは確かに過ちを犯しましたが、\nそのような言い方はひどすぎるのではありませんか。",
  ui_story_5043_50430601_23_dialog_content = "いったい何があったのかは分からないけど、\nティナの思いを寄せる人が別人で本当によかったわ。",
  ui_story_5043_50430601_24_dialog_content = "…",
  ui_story_5043_50430601_25_dialog_content = "ふぅ…",
  ui_story_5043_50430601_26_dialog_content = "先程の報告の話を続けましょうか。",
  ui_story_5043_50430601_27_dialog_content = "ミッドタウンの緑地にあった彫像が壊されたことと、\n「首なし彫像事件」の原告バイロンとは何のつながりもありません。",
  ui_story_5043_50430601_28_dialog_content = "今回はたまたま貴方たちの運が良かっただけですよ。\nへたに原告を刺激して、新たな訴状を持ってこられても困ります。",
  ui_story_5043_50430601_29_dialog_content = "それよりも彫像事件の開廷準備を急ぐべきではありませんか？\nさあ、早く出て行ってください。",
  ui_story_5043_50430601_30_dialog_content = "<color=#e8d9bb>アップタウン、法廷の外</color>",
  ui_story_5043_50430601_31_dialog_content = "プッ…フフフ…",
  ui_story_5043_50430601_32_dialog_content = "お前たちも見たであろう！？奴のあの顔を！",
  ui_story_5043_50430601_33_dialog_content = "ティナ、やるではないか！\nあの一言、かなり効いたようであったぞ！",
  ui_story_5043_50430601_34_dialog_content = "プッ。女性にあんなこと言われたのは初めてでしょうね。",
  ui_story_5043_50430601_35_dialog_content = "まあ…お二人ともからかうのはおやめください…",
  ui_story_5043_50430601_36_dialog_content = "本当に申し訳ございません。\n皆さんまで叱られてしまいました。",
  ui_story_5043_50430601_37_dialog_content = "大丈夫だよ。そんなこと気にしてないから。\nただ、気になるのは――",
  ui_story_5043_50430601_38_dialog_content = "前に言ってたよね？サラール家の荘園で会ったって。",
  ui_story_5043_50430601_39_dialog_content = "シュワーベじゃないなら、誰なの？",
  ui_story_5043_50430601_40_dialog_content = "本当にとんでもない誤解を生んでしまったようですわ。",
  ui_story_5043_50430601_41_dialog_content = "もう一度最初からお話しします…",
  ui_story_5043_50430601_42_dialog_content = "あの日確かにサラール家の荘園で独りお茶を飲みながら\n本を読んでいるシュワーベさんを見かけました。",
  ui_story_5043_50430601_43_dialog_content = "シュワーベさんもすぐに私に気づき、\nお庭の奥までよそ者が入ってきたことに驚いたご様子でした。",
  ui_story_5043_50430601_44_dialog_content = "でも、シュワーベさんは私に気づいただけで、\nもう1人の本来いるはずのない存在にはまったく気づいていませんでした。",
  ui_story_5043_50430601_45_dialog_content = "シュワーベさんの後の茂みの中から、\nボーンがおびえた様子で毛むくじゃらの頭をのぞかせ、私と目を合わせたのです。",
  ui_story_5043_50430601_46_dialog_content = "自分の隠れ場所がばらされてしまうのではないかと心配しているようでした。\nだって暗鬼があのような所にいるはずはないのですから。",
  ui_story_5043_50430601_47_dialog_content = "けれど、ボーンは本当に可愛らしく、攻撃してくる様子もまったくありませんでした。\n彼も入り組んだ迷路の中で迷ってしまっただけなのです。",
  ui_story_5043_50430601_48_dialog_content = "シュワーベさんが私に気づく前に、本を読んでいるシュワーベさんの代わりに\nあの子はお茶にたかった虫を追い払っていました。",
  ui_story_5043_50430601_49_dialog_content = "ダンスパーティが終わると、私はすぐにお庭に駆け付け、\n彼の手を取り、サラール家の荘園から連れ出しました。",
  ui_story_5043_50430601_50_dialog_content = "光力と暗力が互いに影響し合わないように、\n私はわざわざ新しく買った手袋をつけました。",
  ui_story_5043_50430601_51_dialog_content = "あの子は光霊の公用語が分かり、簡単な言葉も話せました。\nその後冠月祭の日にお礼の品を送ってきてくれたのです。",
  ui_story_5043_50430601_52_dialog_content = "以上が事のいきさつですわ。",
  ui_story_5043_50430601_53_dialog_content = "（どこにでもいるような普通の暗鬼にも名前なんてあったんだ…）",
  ui_story_5043_50430601_54_dialog_content = "お待ちください。\nでは「まったく連絡がない」とは、どういうことなのですか？",
  ui_story_5043_50430601_55_dialog_content = "白夜城に決まった住所がないのです。\nお礼を送ってくれた時の住所に手紙を出しましたが、その後連絡はありませんでした。",
  ui_story_5043_50430601_56_dialog_content = "それだけではないぞ。\n「こっそり会うことがかなわない」とはどういうことだ？",
  ui_story_5043_50430601_57_dialog_content = "言葉の通りですわ。あの日以降一度も会っていませんの。\nどこにいるのかも分かりません。",
  ui_story_5043_50430601_58_dialog_content = "「どこへ行っても注意を引いてしまう」…",
  ui_story_5043_50430601_59_dialog_content = "ええ。皆さんもご存じでしょう？\n白夜城では暗鬼は忌み嫌われるだけの存在ですから。",
  ui_story_5043_50430601_60_dialog_content = "…だから君はあの時…「恋」じゃないって言ったんだね…",
  ui_story_5043_50430601_61_dialog_content = "ですが、暗鬼は光霊を襲うことを目的とした生き物ですよ。\n無害な暗鬼などこの世に存在するのでしょうか？",
  ui_story_5043_50430601_62_dialog_content = "もし本当なら、私もぜひこの目で見てみたいものです。",
  ui_story_5043_50430601_63_dialog_content = "確かに通常の感情とは異なる思いですが、\n「恋」と呼ぶにはふさわしくありませんわ。",
  ui_story_5043_50430601_64_dialog_content = "そのようなあいまいな言葉ではなく、\nむしろ世話をしてあげたいと言った方が正確ですもの。",
  ui_story_5043_50430601_64X1_dialog_content = "だが、どんな言葉を使おうと、\nあのような汚らわしい生き物を傍に置くなど気色が悪い。",
  ui_story_5043_50430601_64X2_dialog_content = "クンクン…クンクン…",
  ui_story_5043_50430601_64X3_dialog_content = "ティナ、大げさな話ではなく、\nお前の身体から…暗鬼の臭いが漂ってきておるぞ。",
  ui_story_5043_50430601_64X4_dialog_content = "まあ？これだけ離れていても匂いましたの…？\nそれは…申し訳ございません…",
  ui_story_5043_50430601_65_dialog_content = "先に言っておくわ。法律は白夜城を守る鉄壁のようなものよ。\n私が大目に見てあげるとは思わないで。",
  ui_story_5043_50430601_66_dialog_content = "護衛隊の逮捕者リストには、あなたのいう暗鬼はまだ載っていないけれど…",
  ui_story_5043_50430601_67_dialog_content = "この件は、ここでおしまいにするべきじゃないかしら？",
  ui_story_5043_50430601_68_dialog_content = "うう…カレン殿下、ありがとうございます。\n法廷に身を置く者として、事の重大さはよく分かっています…",
  ui_story_5043_50430601_69_dialog_content = "光霊が暗鬼を養うなど、そもそも荒唐無稽な話です。",
  ui_story_5043_50430601_69X1_dialog_content = "皆さんには大変ご迷惑をお掛けしました…\n今から私も案件に専念し、調査に励みますわ。",
  ui_story_5043_50430601_69X2_dialog_content = "掛けたのは迷惑だけとは言えませんよ。\n面白いこともありましたから。",
  ui_story_5043_50430601_70_dialog_content = "ティナ…恋愛訴訟部の全員を見事に振り回してくれましたね。",
  ui_story_5043_50430601_71_dialog_content = "ハハハ！その通りだ。\nお前と仕事することにして正解であったわ！",
  ui_story_5043_50430601_72_dialog_content = "予想以上に面白いものが見られたぞ！",
  ui_story_5043_50430601_74_dialog_content = "あはは…事件調査は進まず、\nプレゼントのせいで、とんだ笑い種になってしまいましたが…",
  ui_story_5043_50430601_75_dialog_content = "私も皆さんと同じ気持ちですわ…",
  ui_story_5043_50430601_76_dialog_content = "<color=#e8d9bb>バタン――</color>",
  ui_story_5043_50430601_77_dialog_content = "ティナ！？ティナ！",
  ui_story_5043_50430601_78_dialog_content = "どうしたの…？\nあなたたち、突っ立ってないで早く手伝いなさい！",
  ui_story_5043_50430601_79_dialog_content = "ふふ、ご安心くだされ、殿下。\n眠っただけですぞ。",
  ui_story_5043_50430601_80_dialog_content = "今日は色々なことがありましたからね。\n限界だったのでしょう。",
  ui_story_5043_50430601_81_dialog_content = "当家の使用人に馬車でティナを家まで送らせるとしよう。",
  ui_story_5043_50430601_82_dialog_content = "はぁ…はぁ…カレン殿下…",
  ui_story_5043_50430601_83_dialog_content = "ほう、ローウェイ。当家の使用人になりたいか？\n我が家は厳しいが、雇ってやってもよいぞ。",
  ui_story_5043_50430601_84_dialog_content = "話してちょうだい。",
  ui_story_5043_50430601_85_dialog_content = "カレン殿下、お察しの通りでした。",
  ui_story_5043_50430601_86_dialog_content = "あの衛兵たちはトロイ家の紋章をつけていました。",
  ui_story_5043_50430601_87_dialog_content = "また、サロンにもおかしな点があることが分かりました。",
  ui_story_5043_50430601_88_dialog_content = "何ですと？",
  ui_story_5043_50430601_89_dialog_content = "毎回月のサロンが終わると必ず暗鬼が来襲するのです。",
  ui_story_5043_50430601_90_dialog_content = "しかもサロン会場近くの彫像の頭が\n必ず行方知れずになります。",
  ui_story_5043_50430601_91_dialog_content = "申し訳ございません。力は尽くしたのですが…",
  ui_story_5043_50430601_92_dialog_content = "…",
  ui_story_5043_50430601_93_dialog_content = "ありがとう、ローウェイ。",
  ui_story_5043_50430601_94_dialog_content = "すぐに休むといいわ。",
  ui_story_5043_50430702_1_dialog_content = "衛兵の正体が明らかになったからには、\n私もこれ以上傍観してはいられないわ。",
  ui_story_5043_50430702_2_dialog_content = "PlayerName、私はアップタウン護衛隊に戻って会議を開き、\n次の対策を立てなければならないわ。",
  ui_story_5043_50430702_3_dialog_content = "それから、最近の暗鬼の騒ぎについて、\n城主様にも報告しなければ。",
  ui_story_5043_50430702_4_dialog_content = "うん、こっちは大丈夫だよ。\n急いで行ってくるといいよ。",
  ui_story_5043_50430702_5_dialog_content = "ええ。遅くとも開廷日には戻るわ。",
  ui_story_5043_50430702_6_dialog_content = "気を付けて。",
  ui_story_5043_50430702_7_dialog_content = "今日は皆さんも疲れたでしょう。\n私たちも帰宅することにいたしましょう。",
  ui_story_5043_50430702_8_dialog_content = "明日の予定については…",
  ui_story_5043_50430702_9_dialog_content = "明日は何をすべきか、言わずともよく分かっておろうが。",
  ui_story_5043_50430702_10_dialog_content = "これほど疑わしいサロンとなれば、\n主催者に呼出状を突き付けねばならん。",
  ui_story_5043_50430702_11_dialog_content = "確かに今の状況からすると、\n月のサロンは怪しい所ばかりだね…",
  ui_story_5043_50430702_12_dialog_content = "では、こうしましょう。\n明日は月の気球を目印に主催者の修道女様に会いに行きましょう。",
  ui_story_5043_50430702_13_dialog_content = "誰も何があったか説明してくれないのか？",
  ui_story_5043_50430702_14_dialog_content = "あと、ティナはなぜまた眠っている？",
  ui_story_5043_50430702_15_dialog_content = "チッ、まったく世話の焼ける奴だ。\n道すがら説明してやるわ！",
  ui_story_5043_50430702_16_dialog_content = "馬車が来た。先にティナを送っていく。\nPlayerName、ライン、明日また会うとしよう。",
  ui_story_5043_50430702_17_dialog_content = "…おや？",
  ui_story_5043_50430702_18_dialog_content = "どうした？",
  ui_story_5043_50430702_19_dialog_content = "「新人の庶民」とは呼ばないのですか？",
  ui_story_5043_50430702_20_dialog_content = "ええいっ、うるさい！",
  ui_story_5043_50430702_21_dialog_content = "<color=#e8d9bb>翌日</color>",
  ui_story_5043_50430702_22_dialog_content = "まあ…そうでしたか。",
  ui_story_5043_50430702_23_dialog_content = "おっしゃる通りです。\n月のサロンの会場は毎回私が吟味を重ね、選んでおります。",
  ui_story_5043_50430702_24_dialog_content = "私は文化や芸術の空気漂う場所が好きなもので、\n彫像が立つ場所を特に好んで選ぶのです。",
  ui_story_5043_50430702_25_dialog_content = "「老人」や「男性」、「子ども」…\nそれから先程皆さんのおっしゃった2体の「女性」の彫像…",
  ui_story_5043_50430702_26_dialog_content = "どれも白夜城の文明の基礎となるものです。",
  ui_story_5043_50430702_27_dialog_content = "ですが、サロンの会場となった場所にあった彫像がすべて\n壊されてしまったのも事実です。",
  ui_story_5043_50430702_28_dialog_content = "ええ。サロンが混乱を招いていることを否定する気はございません。\n騒ぎの発生時に私がその場にいなかったという証拠もありません。",
  ui_story_5043_50430702_29_dialog_content = "白夜に捧ぐ！しかし、壊された彫像にしても、\n襲ってきた暗鬼にしても、私とは関係ありません。",
  ui_story_5043_50430702_30_dialog_content = "（この人、とても穏やかな顔をしてる。\n柔らかい話し方と同じように何の波もない）",
  ui_story_5043_50430702_31_dialog_content = "（それに、すごく堂々としてるな。信仰の力なのかな…）",
  ui_story_5043_50430702_32_dialog_content = "（本当に…事件とは関係なさそうだな…）",
  ui_story_5043_50430702_33_dialog_content = "チッ…また行き詰まったか。\n容疑だけで捕らえるわけにはいかん。",
  ui_story_5043_50430702_34_dialog_content = "修道女様、光の神も見ていらっしゃいます。\nもしおっしゃることがすべて真実なら…",
  ui_story_5043_50430702_35_dialog_content = "法廷で証言してくださいますか？",
  ui_story_5043_50430702_36_dialog_content = "ここのところサロンの件で忙しくしてはおりますが、\n法廷のご意向とあらば…",
  ui_story_5043_50430702_37_dialog_content = "できる限り、ご協力いたします。",
  ui_story_5043_50430702_38_dialog_content = "でも…！",
  ui_story_5043_50430702_39_dialog_content = "（出廷などしたら、余計な面倒を掛けてしまうのではないでしょうか…）",
  ui_story_5043_50430702_40_dialog_content = "…あら？そちらのお嬢さんは、\n何かおっしゃりたいことがあるようですね？",
  ui_story_5043_50430702_41_dialog_content = "なぜ、そのように落ち着いてらっしゃるのですか？",
  ui_story_5043_50430702_42_dialog_content = "月のサロンは白夜城の新しい一面を引き出しましたわ。\n嫌うどころか、むしろ好きと言っていいほどです。",
  ui_story_5043_50430702_43_dialog_content = "けれど、白夜城の規則や常識では、自由恋愛どころか、\n離婚さえも受け入れてはもらえません。",
  ui_story_5043_50430702_44_dialog_content = "それにも関わらず、神職者であり、敬けんな信者であるあなたが…",
  ui_story_5043_50430702_45_dialog_content = "なぜ白夜城でこのようなサロンを\n立ち上げる気になったのですか？",
  ui_story_5043_50430702_46_dialog_content = "しかも法廷のような場所に出ることも恐れないとは…\nあなたの心持には敬服いたします。",
  ui_story_5043_50430702_47_dialog_content = "ティナ…",
  ui_story_5043_50430702_48_dialog_content = "ふふ…お嬢さん、今の言葉はご自身の悩みや考えを\n映していらっしゃるようですね？",
  ui_story_5043_50430702_49_dialog_content = "このくらいの年になると、\n後先のことは考えなくなるものです。",
  ui_story_5043_50430702_50_dialog_content = "私はただ光の神を信仰する自分の心に\n従っているにすぎません。",
  ui_story_5043_50430702_51_dialog_content = "白夜城はその長い歴史の中で、禁欲に基づいた階級制度と\n複雑きわまるさまざまな礼節や儀礼を生み出しました。",
  ui_story_5043_50430702_52_dialog_content = "ですが、そのような白夜城も最初は、老人や男性、女性、子どもといった、\nごく普通の清らかな光霊たちが建てた都市でした。",
  ui_story_5043_50430702_53_dialog_content = "光の神の教義もまた、長い時間をかけ、\n歴史の流れと共に変化を遂げてきました。",
  ui_story_5043_50430702_54_dialog_content = "しかし、それらもまた誕生した当初は、\n真実と善を示す、ごく簡単なものだったのです。",
  ui_story_5043_50430702_55_dialog_content = "それこそ、光の神から賜った祝福であり、教えなのです。",
  ui_story_5043_50430702_56_dialog_content = "私は今光霊の原点に立ち帰り、自身の心に従っているだけです。",
  ui_story_5043_50430702_57_dialog_content = "そもそも私の行っていることは罪ではありません。\nただ規則や制度と相容れないというだけのことですよ。",
  ui_story_5043_50430702_58_dialog_content = "信仰も、恋愛も…すべては同じ道理の上に\n成り立っているのです。",
  ui_story_5043_50430702_59_dialog_content = "少し…分かった気がいたしますわ。\nお答えくださり、ありがとうございます。",
  ui_story_5043_50430702_60_dialog_content = "それでは、私はこれで。",
  ui_story_5043_50430702_61_dialog_content = "必要とあらば、この後の調査にも協力いたしますよ。",
  ui_story_5043_50430702_62_dialog_content = "ただ、裁判官の皆さま、何かお困りであれば、\n私の助言を参考になさってみてはいかがでしょう？",
  ui_story_5043_50430702_63_dialog_content = "はい…？",
  ui_story_5043_50430702_64_dialog_content = "仕事をこなすためではなく、開廷までに\n有力な情報を得ようと本気で思ってらっしゃるのなら…",
  ui_story_5043_50430702_65_dialog_content = "型通りの調査をするのではなく、\n原告の真の思いがどこにあるのかをお考えになるとよいですよ。",
  ui_story_5043_50430702_66_dialog_content = "ご忠告感謝いたします。参考にさせていただきます…",
  ui_story_5043_50430702_67_dialog_content = "それでは、またお会いしましょう。",
  ui_story_5043_50430801_1_dialog_content = "<color=#e8d9bb>さらに次の日</color>",
  ui_story_5043_50430801_2_dialog_content = "おい、これが調査結果だというのか？",
  ui_story_5043_50430801_3_dialog_content = "最初の事件を解決していないばかりか、\nまた別の彫像が壊されただと！？",
  ui_story_5043_50430801_4_dialog_content = "誠に申し訳ございません。事件はいまだ調査中で、\n目下のところ大きな進展はなく…",
  ui_story_5043_50430801_5_dialog_content = "「大きな」進展がないどころの話ではない！\nまったく進展などないではないか！！",
  ui_story_5043_50430801_6_dialog_content = "白夜城の法廷ともあろうものが聞いてあきれるわい！\nなんと効率の悪い！",
  ui_story_5043_50430801_7_dialog_content = "犬に頼んだ方がまだマシというものだ。\n少なくとも犯人の匂いは嗅ぎ分けられるからな！",
  ui_story_5043_50430801_8_dialog_content = "申し訳ございません。\n調査の効率を上げるよう力を尽くします…",
  ui_story_5043_50430801_9_dialog_content = "もういい！法廷は最初から民衆の愛情の行方がどうなろうと、\nどうでもいいのであろう！？",
  ui_story_5043_50430801_10_dialog_content = "この「恋愛訴訟部」とやらも、\nだたの給料泥棒の集まりではないか！",
  ui_story_5043_50430801_11_dialog_content = "高給取りのくせに、毎日寝てばかりだ！",
  ui_story_5043_50430801_12_dialog_content = "反論のしようもありませんな。\n確かそういう者がおります。",
  ui_story_5043_50430801_13_dialog_content = "ね、眠ることは仕事の助けになりますわ…",
  ui_story_5043_50430801_14_dialog_content = "もう我慢ならん！明後日には開廷するのだぞ！",
  ui_story_5043_50430801_15_dialog_content = "いいか、もし明日までにきちんとした成果を出せなければ、\n私は引き続き隣人を訴える。",
  ui_story_5043_50430801_16_dialog_content = "できなければ、イルンティ裁判長に\n苦情として報告させてもらうぞ！",
  ui_story_5043_50430801_17_dialog_content = "高い給料を取っておいて、民のもめごとも解決できぬのなら、\nこんな法廷、つぶしてしまえばいいのだ！",
  ui_story_5043_50430801_18_dialog_content = "つぶす、ですって！？",
  ui_story_5043_50430801_19_dialog_content = "そこまで深刻ではないのでは！？",
  ui_story_5043_50430801_20_dialog_content = "バイロンさん、落ち着いてください…",
  ui_story_5043_50430801_21_dialog_content = "フン、まあせいぜい励むことだな！",
  ui_story_5043_50430801_22_dialog_content = "行っちゃった…",
  ui_story_5043_50430801_23_dialog_content = "大変なことになったね。恋愛訴訟部…\n想定よりもまずい状況に置かれたみたいだ。",
  ui_story_5043_50430801_24_dialog_content = "まあいい。これで終わりだ。",
  ui_story_5043_50430801_25_dialog_content = "イルンティ裁判長は民衆の声を最も気になさる。\n苦情が届けば…",
  ui_story_5043_50430801_26_dialog_content = "そうですわね。きっと大変お怒りになりますわ。",
  ui_story_5043_50430801_27_dialog_content = "恋愛訴訟部は臨時部門ですから、\n役目を果たせていないと上が判断した場合には…",
  ui_story_5043_50430801_28_dialog_content = "すぐに廃止されてしまう可能性はありますね。",
  ui_story_5043_50430801_29_dialog_content = "言った通りになった…",
  ui_story_5043_50430801_30_dialog_content = "こうなったら、任を解かれても仕方ない。",
  ui_story_5043_50430801_31_dialog_content = "任を解かれるだと！？",
  ui_story_5043_50430801_32_dialog_content = "それはいかん！",
  ui_story_5043_50430801_33_dialog_content = "ど、どうかそんな恐ろしいことおっしゃらないで…",
  ui_story_5043_50430801_34_dialog_content = "任を解かれては、家でまた退屈な時を過ごさねばならん！\n何の楽しみもないではないか！",
  ui_story_5043_50430801_35_dialog_content = "いや、ちょっと待って…\n君が気にしてるのってそんなことなの！？",
  ui_story_5043_50430801_36_dialog_content = "お昼寝させていただけるお仕事なんて、\n他にはありませんよね…？",
  ui_story_5043_50430801_37_dialog_content = "今の仕事だって昼寝はダメでしょ！？",
  ui_story_5043_50430801_38_dialog_content = "新しいお仕事が見つからなければ、家に連れ戻されて…",
  ui_story_5043_50430801_39_dialog_content = "家業を継がされてしまいますわ…",
  ui_story_5043_50430801_40_dialog_content = "いかにも。我が家の石頭も同じことをするだろう。",
  ui_story_5043_50430801_41_dialog_content = "石頭どもの金もうけなど手伝う気はない！",
  ui_story_5043_50430801_42_dialog_content = "貴族の心配なんて…僕がする必要なかったね…",
  ui_story_5043_50430801_43_dialog_content = "でも…だったら失業したって構わないでしょ！？\n皆が楽しくなれれば、それでいいんだ！",
  ui_story_5043_50430801_44_dialog_content = "その通りです。もし本当に仕事を失ったとしても、\n生活は変わらず続いていくのです。",
  ui_story_5043_50430801_45_dialog_content = "ただ…給料がなくなってしまうことを見越して…\nジャガイモと野菜を備蓄しなければなりませんね。",
  ui_story_5043_50430801_46_dialog_content = "明日から、1日1食にします。",
  ui_story_5043_50430801_47_dialog_content = "あれ…？なんか急に深刻になった気が…！？",
  ui_story_5043_50430801_48_dialog_content = "白夜城で暮らすというのは、そもそも深刻なことなのですよ。",
  ui_story_5043_50430801_49_dialog_content = "食費も社交費も必要な出費です。\n生きている限り、毎日必ずお金が出ていきます。",
  ui_story_5043_50430801_50_dialog_content = "収入源を失うとなれば、\nきちんと計画を立てて使わなければなりません。",
  ui_story_5043_50430801_51_dialog_content = "い、生きるって本当に大変だね…",
  ui_story_5043_50430801_52_dialog_content = "あきらめるのは早いですわ。私たちにはまだ1日あります。\n今からでも何かしなければ！",
  ui_story_5043_50430801_53_dialog_content = "おっしゃる通りです。何かしら行動を起こせば、\n調査にも進展があるでしょう。",
  ui_story_5043_50430801_54_dialog_content = "ですが、今最大の問題は\n手がかりをまったくつかめていないことです。",
  ui_story_5043_50430801_55_dialog_content = "いったい何をすればよいのか…",
  ui_story_5043_50430801_56_dialog_content = "私に考えがあるぞ！",
  ui_story_5043_50430801_57_dialog_content = "よく考えてもみよ。\n我々はこれまで固定観念にとらわれていた。",
  ui_story_5043_50430801_58_dialog_content = "「連続首なし彫像事件」はその辺の刑事事件とはわけが違う。",
  ui_story_5043_50430801_59_dialog_content = "何しろ被害者は彫像なのだ。\n交友関係を当たり、犯人の動機を調べることはできん。",
  ui_story_5043_50430801_60_dialog_content = "同様に被害者は彫像であるがゆえに、\n血痕をたどり、犯人の足取りを探ることもできん。",
  ui_story_5043_50430801_61_dialog_content = "ええ、それが今私たちの前にはだかっている障害です。",
  ui_story_5043_50430801_62_dialog_content = "だが、固定観念を取り払い、\nもう一度よく考えてみるのだ。",
  ui_story_5043_50430801_63_dialog_content = "彫像の破壊行為が事件として受理されることとなった、\n決定的な要因は――",
  ui_story_5043_50430801_64_dialog_content = "<color=#FFB400>恋愛</color>ですわ！",
  ui_story_5043_50430801_65_dialog_content = "さよう。そこに恋愛感情が絡んでいたがために、\n我々恋愛訴訟部は受理せざるを得なかった。",
  ui_story_5043_50430801_66_dialog_content = "いかなる物事もいったん恋愛感情が絡むと、\n理性では単純に説明できぬものに変わる。",
  ui_story_5043_50430801_67_dialog_content = "つまり、我々が今相対しているのは事件ではない、\n感情のもつれなのだ！",
  ui_story_5043_50430801_68_dialog_content = "う～ん…何か見えてきた気がします！",
  ui_story_5043_50430801_69_dialog_content = "お待ちください。私には何がなんだか…",
  ui_story_5043_50430801_70_dialog_content = "…今の話をもう一度振り返ってみる？",
  ui_story_5043_50430801_71_dialog_content = "我々は手がかりをつかめていない。\nだが、問題の解決に手がかりが必要とは限らん。",
  ui_story_5043_50430801_72_dialog_content = "つまり、愛の前では我々裁判官とて、\nすべてをつまびらかにする必要などないのだ。",
  ui_story_5043_50430801_73_dialog_content = "大切なのは気持ちだ。",
  ui_story_5043_50430801_74_dialog_content = "あの修道女の言葉を思い出してみよ。",
  ui_story_5043_50430801_75_dialog_content = "仕事をこなすためではなく、開廷までに\n有力な情報を得ようと本気で思ってらっしゃるのなら…",
  ui_story_5043_50430801_76_dialog_content = "型通りの調査をするのではなく、\n原告の真の思いがどこにあるのかをお考えになるとよいですよ。",
  ui_story_5043_50430801_77_dialog_content = "…「気持ち」で解決するというのですか？",
  ui_story_5043_50430801_78_dialog_content = "さあ、行動を起こす時だ、我が友よ！",
  ui_story_5043_50430801_79_dialog_content = "原告のため、愛にあふれた答えを見つけてやろうではないか！",
  ui_story_5043_50430801_80_dialog_content = "<color=#e8d9bb>翌日</color>",
  ui_story_5043_50430801_81_dialog_content = "おい、なぜ私の行く手をふさぐ？",
  ui_story_5043_50430801_82_dialog_content = "さっさと中に入れんか！",
  ui_story_5043_50430801_83_dialog_content = "バイロンさん、もうしばらくお待ちください。",
  ui_story_5043_50430801_84_dialog_content = "今裁判官は公務中です。",
  ui_story_5043_50430801_85_dialog_content = "中にお入りいただける時が来ましたら、\nすぐにお通しします。",
  ui_story_5043_50430801_86_dialog_content = "公務中だと？何を言っておる！？\n私の案件こそおぬしらの公務であろう！",
  ui_story_5043_50430801_87_dialog_content = "中に閉じこもれば私から逃げられるとでも思ったか！\nもう少しマシないい訳はできんのか！",
  ui_story_5043_50430801_88_dialog_content = "バイロンさん、本当に今は…",
  ui_story_5043_50430801_89_dialog_content = "何をしていようが私には関係ない。\n今は法廷の業務時間中であろうが。",
  ui_story_5043_50430801_90_dialog_content = "お、お待ちください…",
  ui_story_5043_50430801_91_dialog_content = "どけ！",
  ui_story_5043_50430801_92_dialog_content = "まあ、仕方ないですね…",
  ui_story_5043_50430801_93_dialog_content = "<size=45>マシュー裁判官！バイロンさんがいらっしゃいました！</size>",
  ui_story_5043_50430801_94_dialog_content = "<color=#e8d9bb>パン――！パン――！パン――！</color>",
  ui_story_5043_50430801_95_dialog_content = "バイロンさん、おめでとうございます！",
  ui_story_5043_50430801_96_dialog_content = "おめでとうございます！",
  ui_story_5043_50430801_97_dialog_content = "愛を取り戻した今日――\n平凡な一日も喜ばしい時間に変わりましたぞ！",
  ui_story_5043_50430801_98_dialog_content = "なに？どういうことだ…？",
  ui_story_5043_50430801_99_dialog_content = "1日かけて、彼女の頭を作り直しましたの。",
  ui_story_5043_50430801_100_dialog_content = "もう少し遅くいらしたなら…\nさらにお美しくできたのですけれど！",
  ui_story_5043_50430801_101_dialog_content = "さよう。我々は改めて愛について考え、\nこのような解決方法にいたったのです。",
  ui_story_5043_50430801_102_dialog_content = "大切なのは何を失ったかではなく――\n何を得られるか、です。",
  ui_story_5043_50430801_103_dialog_content = "頭部が壊されたことで、\nあなたの彼女に対する愛が冷めてしまうのか？",
  ui_story_5043_50430801_104_dialog_content = "いや、そうではありません。それでも愛を求め続ける――\nあなたはただ彼女が不完全であることを嘆いているだけですからな。",
  ui_story_5043_50430801_105_dialog_content = "その悲しみと痛みを解決するには、\n元の完全な姿に戻せばいいのです。",
  ui_story_5043_50430801_106_dialog_content = "ええ。失ったものを取り戻す時、\n美しい物語が再び始まります…",
  ui_story_5043_50430801_107_dialog_content = "お、おぬしら…",
  ui_story_5043_50430801_108_dialog_content = "<size=45>いったい何をしてくれたのだ！！</size>",
  ui_story_5043_50430801_109_dialog_content = "ガラテーアの首に乗っかっている醜い塊は何だ！？\n私を愚弄するつもりか！？",
  ui_story_5043_50430801_110_dialog_content = "これが…醜い、と？",
  ui_story_5043_50430801_111_dialog_content = "お気に召さなかったようですわね…",
  ui_story_5043_50430801_112_dialog_content = "チッ、これだから庶民の美的感覚はあてにならん。",
  ui_story_5043_50430801_113_dialog_content = "今の姿が気に入らないというのなら、\nもう一度作り直して差し上げますぞ…",
  ui_story_5043_50430801_114_dialog_content = "ふざけるにも程がある！\nこのような愚かな行いは愛への冒とくだ！！",
  ui_story_5043_50430801_115_dialog_content = "おぬしらのような若僧に愛の何が分かる！？",
  ui_story_5043_50430801_116_dialog_content = "愛とは唯一無二なのだ！\n一度愛したら、一生変わることはない！",
  ui_story_5043_50430801_117_dialog_content = "ガラテーアが壊された時に私の愛はもう死んだのだ！！",
  ui_story_5043_50430801_118_dialog_content = "瓜二つの頭を再び作り出したところで、\nそれはもうガラテーアではない！！",
  ui_story_5043_50430801_119_dialog_content = "私の愛する唯一無二のガラテーアではないのだ！！",
  ui_story_5043_50430801_120_dialog_content = "まあ、そういうことでしたの…！",
  ui_story_5043_50430801_121_dialog_content = "うぅむ…つまり、私の理解が間違っていたということか？",
  ui_story_5043_50430801_122_dialog_content = "やはりダメでしたか。\n恋愛裁判は避けられそうにありませんね…",
  ui_story_5043_50430801_123_dialog_content = "もういい、この件はいったん置いておく。",
  ui_story_5043_50430801_124_dialog_content = "今日はもっと重要なことがあって訪ねてきた。",
  ui_story_5043_50430801_125_dialog_content = "今この時にも、私の「<color=#FFB400>妻</color>」が命の危険にさらされているのだ。",
  ui_story_5043_50430801_126_dialog_content = "どうか私たちの愛を守るため、\nすぐに人を遣り、妻の安全を確保してくれ！",
  ui_story_5043_50430801_127_dialog_content = "お、お待ちください！\n奥様が今命の危機にさらされている？",
  ui_story_5043_50430801_128_dialog_content = "奥様はこちらにいるではありませんか！？",
  ui_story_5043_50430801_129_dialog_content = "違う！ガラテーアは私が「<color=#FFB400>恋焦がれる女性</color>」だ！",
  ui_story_5043_50430801_130_dialog_content = "今命の危機にさらされているのは私の「<color=#FFB400>妻</color>」だ。別の女性なのだ。",
  ui_story_5043_50430801_131_dialog_content = "なんですと！？",
  ui_story_5043_50430801_132_dialog_content = "妻と恋焦がれる女性が別だというのですかな！？",
  ui_story_5043_50430801_133_dialog_content = "そうだ。妻もまた美しい女性で、\n名は「アフロディーテ」という。",
  ui_story_5043_50430801_134_dialog_content = "どうしてそうなるのですか？\n愛は唯一無二ではなかったのですか！？",
  ui_story_5043_50430801_135_dialog_content = "もちろん唯一無二だ！",
  ui_story_5043_50430801_136_dialog_content = "では、なぜ同時に2人の女性を愛していらっしゃるのです？",
  ui_story_5043_50430801_137_dialog_content = "愛は唯一無二であると同時に\n広くおおらかなものなのだ。",
  ui_story_5043_50430801_138_dialog_content = "私は妻を愛し、恋する女性も愛している。\nどちらの愛も唯一無二なのだ。",
  ui_story_5043_50430801_139_dialog_content = "たとえれば、母を愛すると同時に、\n父を愛することができるのと同じだ。",
  ui_story_5043_50430801_140_dialog_content = "そう言われてみると、確かに一理あるように思えますね…",
  ui_story_5043_50430801_141_dialog_content = "…いえ！！親への愛と異性への愛は一緒にできませんよ！？",
  ui_story_5043_50430801_142_dialog_content = "もういい！おぬしらに愛が何たるか、\n教えている暇はない！",
  ui_story_5043_50430801_143_dialog_content = "ついさっき、月の気球が「千星の階段」の上に上がった。",
  ui_story_5043_50430801_144_dialog_content = "妻はそこにおるのだ。",
  ui_story_5043_50430801_145_dialog_content = "おぬしらも知っているであろう？月の気球は月のサロンの標識だ。\nそして彫像はいつもあのサロンの最中に破壊されている。",
  ui_story_5043_50430801_146_dialog_content = "私の妻にまで何かあれば…私は…私はもう…\nすべての愛を失ってしまう…",
  ui_story_5043_50430801_147_dialog_content = "民衆の愛を守ることがおぬしらの仕事であろう？",
  ui_story_5043_50430801_148_dialog_content = "一度受け持ったからには、\nもちろん貴方の愛を守るべく力を尽くします。",
  ui_story_5043_50430801_149_dialog_content = "チッ、「2分の1の愛」であろうが。",
  ui_story_5043_50430801_150_dialog_content = "しかも事件が起こる可能性があるということは、\n手がかりも見つかるかもしれないということです。",
  ui_story_5043_50430801_151_dialog_content = "私たちは何としても\n「連続首なし彫像事件」を解決しなければなりません！",
  ui_story_5043_50430801_152_dialog_content = "ならば何をもたもたしておる！急ぐのだ！",
  ui_story_5043_50430801_153_dialog_content = "月の気球の下で、まもなくサロンが始まるぞ！",
  ui_story_5043_50430801_154_dialog_content = "<color=#e8d9bb>ミッドタウン、千星の階段付近</color>",
  ui_story_5043_50430801_155_dialog_content = "さあ、すぐそこだ。",
  ui_story_5043_50430801_156_dialog_content = "バイロンさん、奥さんはここだって言ってたね。\nということは…",
  ui_story_5043_50430801_157_dialog_content = "ありました！この彫像で間違いありません！",
  ui_story_5043_50430801_158_dialog_content = "わ！まだ壊されてないよ！",
  ui_story_5043_50430801_159_dialog_content = "この彫像を守ればいいんだよね？",
  ui_story_5043_50430801_160_dialog_content = "そうだ。犯人はおそらく、\nサロンが開かれている最中に動く。",
  ui_story_5043_50430801_161_dialog_content = "だが、サロンの参加者はどこにいる？",
  ui_story_5043_50430801_162_dialog_content = "見つけましたわ！階段の下に集まっています！",
  ui_story_5043_50430801_163_dialog_content = "本当だ。上ってこないのかな？",
  ui_story_5043_50430801_164_dialog_content = "おお、ならば我々は運がいい。",
  ui_story_5043_50430801_165_dialog_content = "サロンが階段の下で開かれるのであれば、\n階段の上にある彫像を守るのは簡単だからな。",
  ui_story_5043_50430801_166_dialog_content = "よかった…これならば、バイロンさんに合わせる顔も\nあるというものです…",
  ui_story_5043_50430801_167_dialog_content = "あら、裁判官の皆さんではありませんか？",
  ui_story_5043_50430801_168_dialog_content = "修道女様！またお会いできるとは光栄ですわ。",
  ui_story_5043_50430801_169_dialog_content = "ここは月の気球の下ですよ。\nお会いできて当然でしょう？",
  ui_story_5043_50430801_170_dialog_content = "せっかく来てくださったのですから、\n皆さんも参加していってください。",
  ui_story_5043_50430801_171_dialog_content = "階段の下で開催されているサロンにですか？",
  ui_story_5043_50430801_172_dialog_content = "お誘いは嬉しいのですが、今日は他に…",
  ui_story_5043_50430801_173_dialog_content = "いいえ、今日はサロンではございませんよ。",
  ui_story_5043_50430801_174_dialog_content = "はい？では、あれは…",
  ui_story_5043_50430801_175_dialog_content = "<size=45>皆さん、準備はよろしいですか？</size>",
  ui_story_5043_50430801_176_dialog_content = "<size=45>パレードを始めます！</size>",
  ui_story_5043_50430901_1_dialog_content = "みんなで愛をたたえよう♪",
  ui_story_5043_50430901_2_dialog_content = "聖なる白夜城でたたえよう♪",
  ui_story_5043_50430901_3_dialog_content = "愛し合う男女が愛をたたえているよ♪",
  ui_story_5043_50430901_4_dialog_content = "愛が美しさをくれたから、たたえているよ♪",
  ui_story_5043_50430901_5_dialog_content = "だから、みんなで愛をたたえよう♪",
  ui_story_5043_50430901_6_dialog_content = "愛をたたえよう！",
  ui_story_5043_50430901_7_dialog_content = "パレード隊、出発！！",
  ui_story_5043_50430901_8_dialog_content = "なんと！群れとなった者どもが階段を上ってくるぞ！",
  ui_story_5043_50430901_9_dialog_content = "これはまずいのではないか？",
  ui_story_5043_50430901_10_dialog_content = "そうですね…もしパレード隊が彫像のある場所を通るとすれば…\n混乱は必至ですわ。彫像を守るのは難しくなるでしょう…",
  ui_story_5043_50430901_11_dialog_content = "彫像が目の前で壊されでもしたら、お前たちの職は…",
  ui_story_5043_50430901_12_dialog_content = "いけません！何とかしてパレード隊を止めなければ！",
  ui_story_5043_50430901_13_dialog_content = "パレードを止める？どうかしましたか？\nパレード隊に何かあったのでしょうか？",
  ui_story_5043_50430901_14_dialog_content = "パレードはめったに行わない大規模な活動なのです。\nお止めになるというのなら、十分な理由を説明してください。",
  ui_story_5043_50430901_15_dialog_content = "この速度では、あまり余裕はありません。",
  ui_story_5043_50430901_16_dialog_content = "僕が止めに入ります。皆さんは修道女様に説明を！",
  ui_story_5043_50430901_17_dialog_content = "まったく…庶民というのは無鉄砲で困る…",
  ui_story_5043_50430901_18_dialog_content = "オホン…修道女殿、我々もできることなら\n阻止したくはありませんが…",
  ui_story_5043_50430901_19_dialog_content = "これも愛のためなのですぞ。",
  ui_story_5043_50430901_20_dialog_content = "愛のため、ですか？",
  ui_story_5043_50430901_21_dialog_content = "パレードのどさくさに紛れて悪事を働こうとする者がおるのです。",
  ui_story_5043_50430901_22_dialog_content = "主催者として、あなたも自分の起こした活動が\n「愛を壊した」との汚名を着せられることを望まないのでは？",
  ui_story_5043_50430901_23_dialog_content = "愛を、たたえよう！",
  ui_story_5043_50430901_24_dialog_content = "自由な、恋愛を！",
  ui_story_5043_50430901_25_dialog_content = "おい、ちょっと待ってくれ！",
  ui_story_5043_50430901_26_dialog_content = "進む方向を間違えたみたいだ。",
  ui_story_5043_50430901_27_dialog_content = "目的地はミッドタウンの居住区だぞ！",
  ui_story_5043_50430901_28_dialog_content = "方向転換して引き返すぞ！",
  ui_story_5043_50430901_29_dialog_content = "そうだ！引き返そう！",
  ui_story_5043_50430901_30_dialog_content = "え？方向を間違えた！？",
  ui_story_5043_50430901_31_dialog_content = "そんなはずないだろう！？\n千星の階段を上るんじゃなかったのか？",
  ui_story_5043_50430901_32_dialog_content = "伝達ミスだろう。人が多いせいで情報が交錯している。",
  ui_story_5043_50430901_33_dialog_content = "え？居住区ですって？",
  ui_story_5043_50430901_34_dialog_content = "あたしはミッドタウンの広場だって聞いたわ！",
  ui_story_5043_50430901_35_dialog_content = "まだ結構距離があるわね。\nみんな、急いで方向転換して引き返しましょ！",
  ui_story_5043_50430901_36_dialog_content = "そうだ！急いで引き返そう！",
  ui_story_5043_50430901_37_dialog_content = "戻るのか…？ここまで来て…？",
  ui_story_5043_50430901_38_dialog_content = "そうだそうだ！",
  ui_story_5043_50430901_39_dialog_content = "だが、目的地は居住区だ。",
  ui_story_5043_50430901_40_dialog_content = "違うわよ、広場よ！",
  ui_story_5043_50430901_41_dialog_content = "待ってくれ。今日のパレードは千星の階段を上るってことで、\n間違いないはずだ。",
  ui_story_5043_50430901_42_dialog_content = "そうだ！でなかったら、どうして階段の下で集合したんだ？",
  ui_story_5043_50430901_43_dialog_content = "目的地が居住区だとか広場だとか…\nその情報はいったい誰から聞いたんだ？",
  ui_story_5043_50430901_44_dialog_content = "白髪でポニーテールにしているヤツだよ。\n信頼できそうなヤツだった。",
  ui_story_5043_50430901_45_dialog_content = "信用できそうな人だったわ。\n白髪でポニーテールにしていた。",
  ui_story_5043_50430901_46_dialog_content = "おい！それ、同一人物じゃないのか！？\nお前たちだまされたんだよ！",
  ui_story_5043_50430901_47_dialog_content = "なにっ！？/ええ！？",
  ui_story_5043_50430901_48_dialog_content = "白髪でポニーテールにしているヤツ…こいつか！？",
  ui_story_5043_50430901_49_dialog_content = "いいえ、私はただ、通りかかっただけで…",
  ui_story_5043_50430901_50_dialog_content = "そいつで間違いない！",
  ui_story_5043_50430901_51_dialog_content = "その人から聞いたのよ！",
  ui_story_5043_50430901_52_dialog_content = "見ない顔だが、いつまぎれこんだ！？\n愛をたたえるパレードをぶち壊そうとするなんて、とんでもないヤツだ！",
  ui_story_5043_50430901_53_dialog_content = "そいつを縛り上げて恋愛裁判にかけてやろう！",
  ui_story_5043_50430901_54_dialog_content = "…そ、その必要はありません。自分で行きますから…",
  ui_story_5043_50430901_55_dialog_content = "行こう！このまま千星の階段を上るぞ！",
  ui_story_5043_50430901_56_dialog_content = "そいつに逃げられないように注意するんだぞ！",
  ui_story_5043_50430901_57_dialog_content = "（まずいですね…とっさに思いついた方法では、\nさすがに通用しませんか…）",
  ui_story_5043_50430901_58_dialog_content = "（行列がまた進みだしました。どうしましょう…）",
  ui_story_5043_50430901_59_dialog_content = "おやおや、これはしまった。\nミルク缶とハチミツ缶を倒してしまった！",
  ui_story_5043_50430901_60_dialog_content = "すまんな、不器用なものでな。",
  ui_story_5043_50430901_61_dialog_content = "なんだ！？大量のミルクが階段の上から流れてくるぞ！",
  ui_story_5043_50430901_62_dialog_content = "いったい何本ミルク缶を倒せばこうなるんだ！？",
  ui_story_5043_50430901_63_dialog_content = "しかもハチミツまで混ざってるぞ！！",
  ui_story_5043_50430901_64_dialog_content = "（こ、これは…マシュー式直球型解決法ですか？）",
  ui_story_5043_50430901_65_dialog_content = "（バカげた方法ではありますが、効き目はあったようですね…\nパレード隊の行進が止まりました！）",
  ui_story_5043_50430901_66_dialog_content = "まったく、今日はついてない。",
  ui_story_5043_50430901_67_dialog_content = "あきらめたらダメだ！光の神もおっしゃっているではないか！\n試練こそ幸福への道だ！",
  ui_story_5043_50430901_68_dialog_content = "その通りだ！ミルクとハチミツが流れる所こそ、\n正しき道を示しているんだ！",
  ui_story_5043_50430901_69_dialog_content = "みんな、気を付けて進め！転ぶなよ！",
  ui_story_5043_50430901_70_dialog_content = "（まだ進むのですか！？）",
  ui_story_5043_50430901_71_dialog_content = "（恐ろしい意志の強さですね…）",
  ui_story_5043_50430901_72_dialog_content = "<size=45>きゃあ――！！</size>",
  ui_story_5043_50430901_73_dialog_content = "<size=45>この階段、なんて滑りやすいのでしょう！！</size>",
  ui_story_5043_50430901_74_dialog_content = "どうした！？",
  ui_story_5043_50430901_75_dialog_content = "先頭で誰か転んだようだぞ！",
  ui_story_5043_50430901_76_dialog_content = "ううぅ…痛い、とても痛いですわ…",
  ui_story_5043_50430901_77_dialog_content = "あまりの痛みに昼間だというのに星が見えるようです…",
  ui_story_5043_50430901_78_dialog_content = "お、おい、重傷みたいだぞ！",
  ui_story_5043_50430901_79_dialog_content = "階段が滑りやすいと、確かに危ない…",
  ui_story_5043_50430901_80_dialog_content = "…どうだろう、今日はよさないか？",
  ui_story_5043_50430901_81_dialog_content = "そうだな。どこでだってパレードはできる。",
  ui_story_5043_50430901_82_dialog_content = "千星の階段に突っ立てても仕方ない。\n早くあの女の子を医者の所に連れて行ってあげよう。",
  ui_story_5043_50430901_83_dialog_content = "パレード隊が戻っていく！",
  ui_story_5043_50430901_84_dialog_content = "すごいよ、ティナ！",
  ui_story_5043_50430901_85_dialog_content = "迫真の演技だったね！",
  ui_story_5043_50430901_86_dialog_content = "ふふ、もし法廷を辞めることになったら、\n劇場で女優にでもなりましょうかしら。",
  ui_story_5043_50430901_87_dialog_content = "どうだ、絶妙な策であったろう！？",
  ui_story_5043_50430901_88_dialog_content = "うん、すごいね。絶妙だったよ！",
  ui_story_5043_50430901_89_dialog_content = "お若いというのにまったく…大胆ですね…",
  ui_story_5043_50430901_90_dialog_content = "まあ、良しといたしましょう。\n私どもの活動の名声も守れたことですし。",
  ui_story_5043_50430901_91_dialog_content = "すべての愛が守るべきもの。\nたとえ相手が彫像であっても、それは変わりませんから。",
  ui_story_5043_50430901_92_dialog_content = "さすがはサロンの主催者ですな。\n修道女殿、あなたの広いお心に感謝いたします。",
  ui_story_5043_50430901_93_dialog_content = "では、私は失礼いたします。\nここからは私がパレード隊を別の場所へと導きましょう。",
  ui_story_5043_50430901_94_dialog_content = "皆さんも、頑張ってください。",
  ui_story_5043_50430901_95_dialog_content = "大変だ！これ以上後ろに下がるな！",
  ui_story_5043_50430901_96_dialog_content = "急いで階段に戻れ！！",
  ui_story_5043_50430901_97_dialog_content = "どうしたの！？急に騒がしくなったよ！？",
  ui_story_5043_50430901_98_dialog_content = "暗鬼だと！？後からどうして暗鬼が現れるんだ！？",
  ui_story_5043_50430901_99_dialog_content = "みんな、急いで階段を上れ！",
  ui_story_5043_50430901_100_dialog_content = "なにぃ！？暗鬼だと！？",
  ui_story_5043_50430901_101_dialog_content = "確かに暗鬼だ！数は多くないよ！",
  ui_story_5043_50430901_102_dialog_content = "ラインはもう暗鬼と戦ってるよ！",
  ui_story_5043_50430901_103_dialog_content = "私たちも助けに行きましょう！",
  ui_story_5043_50430901_104_dialog_content = "待て。デモ隊が押し寄せてくる。\n彫像のことも忘れるな。",
  ui_story_5043_50430901_105_dialog_content = "暗鬼の数は多くないみたいだ。\n応援は1人で十分だと思う。",
  ui_story_5043_50430901_106_dialog_content = "ティナ、ラインの応援に行って。\n僕たちはここで彫像を守ろう。",
  ui_story_5043_50430901_107_dialog_content = "暗鬼と戦う時には、感知能力で手助けするよ！",
  ui_story_5043_50430901_108_dialog_content = "分かりました。そうしましょう！",
  ui_story_5043_50430901_109_dialog_content = "それでは彫像はお願いしますわ。\nかならず守ってくださいね！",
  ui_story_5043_50431001_1_dialog_content = "あの1匹で最後ですわ！",
  ui_story_5043_50431001_2_dialog_content = "お任せください！",
  ui_story_5043_50431001_3_dialog_content = "やりましたわね。これで敵はすべて倒しました。",
  ui_story_5043_50431001_4_dialog_content = "でも…パレード隊は全員、階段を上って行ってしまいました。",
  ui_story_5043_50431001_5_dialog_content = "PlayerNameさんは？皆さんはどうなったのでしょう？",
  ui_story_5043_50431001_6_dialog_content = "ねえ、皆！気を付けて！",
  ui_story_5043_50431001_7_dialog_content = "ここにはすごく高価な彫像があるんだ！\n壊したら弁償しなきゃなんだよ！",
  ui_story_5043_50431001_8_dialog_content = "急いで逃げるんだ！暗鬼だ！",
  ui_story_5043_50431001_9_dialog_content = "皆、慌てないで！暗鬼はもう倒したよ！",
  ui_story_5043_50431001_10_dialog_content = "<color=#e8d9bb>ドン！</color>",
  ui_story_5043_50431001_11_dialog_content = "何事だ！？",
  ui_story_5043_50431001_12_dialog_content = "大変だ！誰かが彫像にぶつかった！",
  ui_story_5043_50431001_13_dialog_content = "幸い、壊れてないみたいだけど…",
  ui_story_5043_50431001_14_dialog_content = "わああああああ！！",
  ui_story_5043_50431001_15_dialog_content = "また来たよ！！",
  ui_story_5043_50431001_16_dialog_content = "マシュー、あの人たちを止めて！！",
  ui_story_5043_50431001_17_dialog_content = "私にいったいどうしろと…",
  ui_story_5043_50431001_18_dialog_content = "<color=#e8d9bb>バン！</color>",
  ui_story_5043_50431001_19_dialog_content = "うう！",
  ui_story_5043_50431001_20_dialog_content = "大丈夫か？",
  ui_story_5043_50431001_21_dialog_content = "慰めなどいらん！さっさと助け起こさんか！？",
  ui_story_5043_50431001_22_dialog_content = "大変だ！暗鬼がデモ隊の中に紛れ込んだぞ！",
  ui_story_5043_50431001_23_dialog_content = "暗鬼が！？",
  ui_story_5043_50431001_24_dialog_content = "本当だ！暗鬼が数体、人混みの中に紛れ込んだ！",
  ui_story_5043_50431001_25_dialog_content = "いったいどこから来たの？",
  ui_story_5043_50431001_26_dialog_content = "慌てるな！この靴で頭をかち割ってやる！",
  ui_story_5043_50431001_27_dialog_content = "靴で暗鬼を倒せるの！？",
  ui_story_5043_50431001_28_dialog_content = "あ、ちょっと待って！どうして彫像に向かって投げるの！？",
  ui_story_5043_50431001_29_dialog_content = "<color=#e8d9bb>バン！</color>",
  ui_story_5043_50431001_30_dialog_content = "バイロン殿が靴の痕を気にせねばよいが…",
  ui_story_5043_50431001_31_dialog_content = "俺もやってやる！見てろ！",
  ui_story_5043_50431001_32_dialog_content = "また来た！！",
  ui_story_5043_50431001_33_dialog_content = "<color=#e8d9bb>バン！</color>",
  ui_story_5043_50431001_34_dialog_content = "おい、彫像は無事か？",
  ui_story_5043_50431001_35_dialog_content = "今のところ大丈夫だけど、これ以上続いたら…",
  ui_story_5043_50431001_36_dialog_content = "もう靴を投げないで！ほら、靴を投げたって、\n石膏像さえ壊せないんだよ！",
  ui_story_5043_50431001_37_dialog_content = "暗鬼を倒せるわけないでしょ！？",
  ui_story_5043_50431001_38_dialog_content = "それもそうだ。他にもっといい武器はないのか？",
  ui_story_5043_50431001_39_dialog_content = "あるぞ！チーズだ、石のように硬いぞ！",
  ui_story_5043_50431001_40_dialog_content = "チーズを持ち歩いてる人なんているんだ…",
  ui_story_5043_50431001_41_dialog_content = "…そんなことより、大変だ！チーズまで投げられたら、\n今度こそ彫像が…",
  ui_story_5043_50431001_42_dialog_content = "皆さん、落ち着いて！落ち着いてください！\nこれ以上物をこちらに投げないでください！",
  ui_story_5043_50431001_43_dialog_content = "これ以上投げないでください！",
  ui_story_5043_50431001_44_dialog_content = "修道女様！",
  ui_story_5043_50431001_45_dialog_content = "おい、やめるんだ！物を投げるんじゃない！\n修道女様に当たったらどうする！？",
  ui_story_5043_50431001_46_dialog_content = "ふぅ、なんとかおさまった。",
  ui_story_5043_50431001_47_dialog_content = "修道女さん、ありがとうございます！",
  ui_story_5043_50431001_48_dialog_content = "とんでもありません。当然のことをしたまでです。",
  ui_story_5043_50431001_49_dialog_content = "冠月祭にちなんだ愛をたたえる活動です。\nどなたかの愛する人を壊したなどという汚名を負うわけにはまいりません！",
  ui_story_5043_50431001_50_dialog_content = "（彫像を守ろうとしたことからすると、\nこの人は「連続首なし彫像事件」とは関係なさそうだ）",
  ui_story_5043_50431001_51_dialog_content = "群衆が去ってゆくぞ。",
  ui_story_5043_50431001_52_dialog_content = "これで一息付けそうだな。",
  ui_story_5043_50431001_53_dialog_content = "そうだね。",
  ui_story_5043_50431001_54_dialog_content = "まさか、慌てふためいた群衆が\n暗鬼よりも恐ろしいなんて思わなかったよ。",
  ui_story_5043_50431001_55_dialog_content = "いかにも。そうと知っていれば、\n暗鬼の片づけの手伝いに行ったものを。",
  ui_story_5043_50431001_56_dialog_content = "ちょっと！！何をぼうっとしているのですか！！",
  ui_story_5043_50431001_57_dialog_content = "ライン、お帰り…",
  ui_story_5043_50431001_58_dialog_content = "後ろです！",
  ui_story_5043_50431001_59_dialog_content = "後ろに暗鬼がいます！！",
  ui_story_5043_50431002_1_dialog_content = "バケモノどもめが！\n不意打ちは得意なようだが…",
  ui_story_5043_50431002_2_dialog_content = "いざ戦うとひとたまりもないではないか！",
  ui_story_5043_50431002_3_dialog_content = "気を抜いてはいけません。まだ全部倒していませんよ。",
  ui_story_5043_50431002_4_dialog_content = "我々が残らずきれいに片づけてくれるわ！",
  ui_story_5043_50431002_5_dialog_content = "待て！",
  ui_story_5043_50431002_6_dialog_content = "PlayerName、お前の横のそれは…",
  ui_story_5043_50431002_7_dialog_content = "僕の横！？",
  ui_story_5043_50431002_8_dialog_content = "腕が1本…",
  ui_story_5043_50431002_9_dialog_content = "<color=#e8d9bb>バン！！</color>",
  ui_story_5043_50431002_10_dialog_content = "大変だ！彫像が…",
  ui_story_5043_50431002_11_dialog_content = "いったい誰なの！？",
  ui_story_5043_50431002_12_dialog_content = "犯人の手をつかみました！",
  ui_story_5043_50431002_13_dialog_content = "暗鬼の中に紛れ込んでいます！\n急いで引きずり出してください！",
  ui_story_5043_50431002_14_dialog_content = "ええい、邪魔するでない！\n道を開けるのだ！",
  ui_story_5043_50431002_15_dialog_content = "むむ？誰もおらんぞ？",
  ui_story_5043_50431002_16_dialog_content = "申し訳ございません。逃げられてしまいました。",
  ui_story_5043_50431002_17_dialog_content = "手袋だけを残して逃げたのです。\nこんなトカゲのような手を使うとは…",
  ui_story_5043_50431002_18_dialog_content = "何たる失態だ！目の前で彫像を壊されるとは！",
  ui_story_5043_50431002_19_dialog_content = "どう報告しろというのだ！？",
  ui_story_5043_50431002_20_dialog_content = "少なくとも…犯人の手袋は手に入ったよ！？",
  ui_story_5043_50431002_21_dialog_content = "これって重要な手がかりだよね！？",
  ui_story_5043_50431002_22_dialog_content = "調査という点では、突破口になるでしょう。",
  ui_story_5043_50431002_23_dialog_content = "ただ…バイロンさんにとっては、\n受け入れがたい結果でしょうね…",
  ui_story_5043_50431002_24_dialog_content = "そういえば、ティナはどこに行ったの？",
  ui_story_5043_50431002_25_dialog_content = "ラインと一緒じゃなかったの？",
  ui_story_5043_50431002_26_dialog_content = "先程はかなり急いでいたので、\nついてこられなかったのかもしれません。",
  ui_story_5043_50431002_27_dialog_content = "皆さん、ご無事ですか！？",
  ui_story_5043_50431002_28_dialog_content = "申し訳ございません。階段を上っている途中で、\n暗鬼にからまれてしまいましたの。",
  ui_story_5043_50431002_29_dialog_content = "…彫像の…頭がなくなっていますわ！？",
  ui_story_5043_50431002_30_dialog_content = "はぁ…",
  ui_story_5043_50431002_31_dialog_content = "とにかく、戻って報告することにいたしましょう。",
  ui_story_5043_50431002_32_dialog_content = "<color=#e8d9bb>アップタウン、法廷</color>",
  ui_story_5043_50431002_33_dialog_content = "<size=45>ああ！妻が…！私の妻が！！</size>",
  ui_story_5043_50431002_34_dialog_content = "<size=45>私のアフロディーテが――！！</size>",
  ui_story_5043_50431002_35_dialog_content = "…",
  ui_story_5043_50431002_36_dialog_content = "終わったな。",
  ui_story_5043_50431002_37_dialog_content = "なぜだ？なぜこんなことになったのだ！？",
  ui_story_5043_50431002_38_dialog_content = "真心をささげ愛してきたというのに…\n愛を守ろうと力を尽くしたというのに…",
  ui_story_5043_50431002_39_dialog_content = "なぜだ…！？なぜ愛はことごとく私から去ってゆくのだ…！",
  ui_story_5043_50431002_40_dialog_content = "愛する者を救えなかった…1人たりとも救えなかった…",
  ui_story_5043_50431002_41_dialog_content = "バイロンさん、事の次第はよく分かりました。",
  ui_story_5043_50431002_42_dialog_content = "事の次第だと？",
  ui_story_5043_50431002_43_dialog_content = "何を言う！もう何もかも終わったのだ！",
  ui_story_5043_50431002_44_dialog_content = "この世にはもう私の愛すべき者は存在しない！",
  ui_story_5043_50431002_45_dialog_content = "光の神よ、貴方様はなぜ私にこのような罰を下すのですか…",
  ui_story_5043_50431002_46_dialog_content = "そう興奮なさらないでください。",
  ui_story_5043_50431002_47_dialog_content = "起きたことはもう変えられません。",
  ui_story_5043_50431002_48_dialog_content = "ですが、我々法廷が無念を晴らして差し上げます。",
  ui_story_5043_50431002_49_dialog_content = "法廷だと？フンッ！",
  ui_story_5043_50431002_50_dialog_content = "おぬしらが無能だから、\n妻はこのようなひどい目に遭ったのだ！",
  ui_story_5043_50431002_51_dialog_content = "裁判官が3人も集まっておきながら、\n真犯人を見つけられんばかりか、妻も守れんかったではないか！",
  ui_story_5043_50431002_52_dialog_content = "覚悟しておくがいい！間もなくイルンティ裁判長のもとに、\nおぬしらの「輝かしい業績」の報告が届くであろう！",
  ui_story_5043_50431002_53_dialog_content = "法廷の名声に泥を塗ったおぬしら無能どもを、\n裁判長は決して許さんぞ！",
  ui_story_5043_50431002_54_dialog_content = "バイロンさん、お力になれず本当に申し訳ございません。",
  ui_story_5043_50431002_55_dialog_content = "犯人が彫像を壊すのを止められなかったばかりか、\n捕まえることもできませんでした。",
  ui_story_5043_50431002_56_dialog_content = "ですが…犯人が犯行時にはめていた手袋を\n手に入れることができました。",
  ui_story_5043_50431002_57_dialog_content = "なんということだ！妻の美しい頭と引き換えに得たものが、\nただの手袋だとは！",
  ui_story_5043_50431002_58_dialog_content = "おぬしらまさか、\n自分らが大したことをしたとでも思っておるのか？",
  ui_story_5043_50431002_59_dialog_content = "白夜城の人口がどのくらいか、\n手袋がいくつ存在するか、知っておるのか？",
  ui_story_5043_50431002_60_dialog_content = "おぬしら恋愛訴訟部のみじめな作業効率では、\n手袋を手に入れたとて何ができる！？",
  ui_story_5043_50431002_61_dialog_content = "バイロンさん、一部の者に不手際があったからといって、\n恋愛訴訟部全体をけなすのはいかがかと思いますよ。",
  ui_story_5043_50431002_62_dialog_content = "部下に不手際があったのは確かですが、\n私は裁判長として、すべての案件に必ずや公正な裁きを下します。",
  ui_story_5043_50431002_63_dialog_content = "公正な裁きだと？そういうご立派なセリフは\nイルンティ裁判長への言い訳に使うがいい！",
  ui_story_5043_50431002_64_dialog_content = "恋する女性と妻が相次いで被害に遭ったにもかかわらず、\n犯人は法の裁きを逃れ悠々と暮らしている。",
  ui_story_5043_50431002_65_dialog_content = "それが公正だというのか！？",
  ui_story_5043_50431002_66_dialog_content = "ですから、そう興奮なさらないでください、バイロンさん。",
  ui_story_5043_50431002_67_dialog_content = "まだ開廷もしていないのですよ？\n「法の裁きを逃れた」は時期尚早ではありませんか？",
  ui_story_5043_50431002_68_dialog_content = "ふん、開廷までに犯人を捕まえられるとでも言うのか？",
  ui_story_5043_50431002_69_dialog_content = "ライン裁判官、手袋を証拠品として提出してください。",
  ui_story_5043_50431002_70_dialog_content = "はい。",
  ui_story_5043_50431002_71_dialog_content = "この手袋は犯行現場で犯人の手から奪ったもので、\nよろしかったですね？",
  ui_story_5043_50431002_72_dialog_content = "はい。あと一歩で犯人を捕らえられたのですが、\n犯人は手袋を捨て、逃げおおせました。",
  ui_story_5043_50431002_73_dialog_content = "ならば、この手がかりの意義は単純明快ですね。\n手袋の持ち主こそ彫像事件の真犯人です。",
  ui_story_5043_50431002_74_dialog_content = "そして、ちょうど私の部下が、\n<color=#FFB400>もう片方の手袋</color>を見つけています。",
  ui_story_5043_50431002_75_dialog_content = "どうです？この2つの手袋、一対で間違いありませんね？",
  ui_story_5043_50431002_76_dialog_content = "もう片方の手袋だと？",
  ui_story_5043_50431002_77_dialog_content = "！？",
  ui_story_5043_50431002_78_dialog_content = "本当ですね！",
  ui_story_5043_50431002_79_dialog_content = "どこで見つけたのですか？いったい誰のものなのです？",
  ui_story_5043_50431002_80_dialog_content = "これで…事件の真相は明らかになりました。",
  ui_story_5043_50431002_81_dialog_content = "衛兵、命令だ！",
  ui_story_5043_50431002_82_dialog_content = "ティナ・キャンベルを捕らえよ！",
  ui_story_5043_50431002_83_dialog_content = "何言ってるの？ティナを捕らえる！？",
  ui_story_5043_50431002_84_dialog_content = "了解です！",
  ui_story_5043_50431101_1_dialog_content = "お待ちください！何かの間違いです！",
  ui_story_5043_50431101_2_dialog_content = "ティナが犯人のはずないではありませんか！？",
  ui_story_5043_50431101_3_dialog_content = "そうだよ！ティナのはずないよ！",
  ui_story_5043_50431101_4_dialog_content = "シュワーベ、頭がどうかしたのか？",
  ui_story_5043_50431101_5_dialog_content = "まったく…貴方たちときたら…無能で困りますね。\n理由は先程お話ししたではありませんか。",
  ui_story_5043_50431101_6_dialog_content = "ライン裁判官が入手した手袋こそ決定的な証拠ですよ。\n手袋の持ち主が真犯人です。",
  ui_story_5043_50431101_7_dialog_content = "事件発生直後、犯行現場で入手した手袋と対になる、\nもう片方の手袋を部下が見つけたのです。",
  ui_story_5043_50431101_8_dialog_content = "そして、その手袋はティナ裁判官のデスクの引き出しに\n隠されていました。",
  ui_story_5043_50431101_9_dialog_content = "何ですと！？",
  ui_story_5043_50431101_10_dialog_content = "ティナ、この手袋…本当に貴方のものですか？",
  ui_story_5043_50431101_11_dialog_content = "た、確かに…このデザインの手袋を持っていますが…",
  ui_story_5043_50431101_12_dialog_content = "なぜ犯行現場に…？",
  ui_story_5043_50431101_13_dialog_content = "ティナ裁判官、自分の置かれている状況が\nまだ飲み込めていないようですね？",
  ui_story_5043_50431101_14_dialog_content = "今、貴方は容疑者なのですよ。\nその質問は私がすべきものでしょう？",
  ui_story_5043_50431101_15_dialog_content = "ああ！実に残念です！貴方のように美しい女性が、\nこのような醜い所業の犯人だったとは！",
  ui_story_5043_50431101_16_dialog_content = "胸が張り裂けそうです！",
  ui_story_5043_50431101_17_dialog_content = "そんなはずはありません！\n罪なき者の名誉を傷つけるのはやめてください！",
  ui_story_5043_50431101_18_dialog_content = "事件当時、ティナは私たちと共に暗鬼と戦っていました。",
  ui_story_5043_50431101_19_dialog_content = "私たちが証人です。ティナは犯人ではありません！",
  ui_story_5043_50431101_20_dialog_content = "ライン、貴方は裁判官ですよ。\n責任をもって発言していただきたいですね。",
  ui_story_5043_50431101_21_dialog_content = "偽証したらどういうことになるか、\n私がわざわざ説明する必要もないでしょう？",
  ui_story_5043_50431101_22_dialog_content = "奴の言ったことは事実だ。\n私が証明しよう！",
  ui_story_5043_50431101_23_dialog_content = "本当にそうでしょうか？よく考えてみてください。",
  ui_story_5043_50431101_24_dialog_content = "事件の起こった瞬間、ティナ裁判官は本当に貴方たちと共に\n暗鬼と戦っていたのですか？",
  ui_story_5043_50431101_25_dialog_content = "ティナは…",
  ui_story_5043_50431101_26_dialog_content = "そういえば、ティナはどこに行ったの？",
  ui_story_5043_50431101_27_dialog_content = "ラインと一緒じゃなかったの？",
  ui_story_5043_50431101_28_dialog_content = "先程はかなり急いでいたので、\nついてこられなかったのかもしれません。",
  ui_story_5043_50431101_29_dialog_content = "皆さん、ご無事ですか！？",
  ui_story_5043_50431101_30_dialog_content = "（まずい…ティナはあの時確かに僕たちと一緒じゃなかった）",
  ui_story_5043_50431101_31_dialog_content = "お分かりになったようですね。",
  ui_story_5043_50431101_32_dialog_content = "証言は、よく考えてからなさることです。",
  ui_story_5043_50431101_33_dialog_content = "それができなければ、一人前の裁判官とは言えませんよ。",
  ui_story_5043_50431101_34_dialog_content = "…",
  ui_story_5043_50431101_35_dialog_content = "さあ、犯人も捕まったことですし、\nこのバカらしい騒ぎもここまでといたしましょう。",
  ui_story_5043_50431101_36_dialog_content = "バイロンさん、ご満足いただけましたか？",
  ui_story_5043_50431101_37_dialog_content = "なんと！裁判官のうちの1人が犯人だったとは！",
  ui_story_5043_50431101_38_dialog_content = "どうりで何もできんかったわけだ！",
  ui_story_5043_50431101_39_dialog_content = "バイロンさん、これは何かの間違いです…",
  ui_story_5043_50431101_40_dialog_content = "おぬしらに望みを託した私がバカだった。",
  ui_story_5043_50431101_41_dialog_content = "口では愛を守るといいながら、\n実際にはぶち壊していたのだからな！",
  ui_story_5043_50431101_42_dialog_content = "裁判長、この悪党を厳しく懲らしめてくだされ！",
  ui_story_5043_50431101_43_dialog_content = "犯人には必ず裁きを下します。\nしかし、今ではありません。",
  ui_story_5043_50431101_44_dialog_content = "皆さん、お忘れになってはいませんか？\n「連続首なし彫像事件」の開廷日は明日です。",
  ui_story_5043_50431101_45_dialog_content = "開廷後、原告には法廷で陳述していただきます。",
  ui_story_5043_50431101_46_dialog_content = "わかった。",
  ui_story_5043_50431101_47_dialog_content = "私の恋焦がれる女性と妻は、\nこの事件で悲惨な目に遭わされた。",
  ui_story_5043_50431101_48_dialog_content = "裁判長、必ず公正な裁きを下してくだされよ！",
  ui_story_5043_50431101_49_dialog_content = "もちろんです。恋愛訴訟部はあらゆるけがれ無き愛の\n公正を守るためにあるのですから。",
  ui_story_5043_50431101_50_dialog_content = "衛兵、容疑者を連れて行け。",
  ui_story_5043_50431101_51_dialog_content = "お待ちください！",
  ui_story_5043_50431101_52_dialog_content = "シュワーベ裁判長、\nもう一度証拠品の手袋を調べさせていただけませんか？",
  ui_story_5043_50431101_53_dialog_content = "ティナは絶対に犯人ではありません。\n証拠品の持ち主にも間違いがないとも限りません。",
  ui_story_5043_50431101_54_dialog_content = "この状態でティナを捕らえるのは、\nあまりにも軽率すぎます！",
  ui_story_5043_50431101_55_dialog_content = "さよう。デザインが同じだからといって、対だとは限らん！",
  ui_story_5043_50431101_56_dialog_content = "同じ色、同じデザインの手袋など、\n私ならば7対は持っておるわ！",
  ui_story_5043_50431101_57_dialog_content = "皆さん…",
  ui_story_5043_50431101_58_dialog_content = "バカ騒ぎはそこまでにしていただけませんか？\n私もこんなことを続けるほど暇ではありませんしね。",
  ui_story_5043_50431101_59_dialog_content = "言いたいことややりたいことがあるなら、\n開廷後にしてください。",
  ui_story_5043_50431101_60_dialog_content = "なぜです？ただ証拠品を調べるだけですが…",
  ui_story_5043_50431101_61_dialog_content = "バカ騒ぎはもう結構。",
  ui_story_5043_50431101_62_dialog_content = "この後容疑者は独房に入れます。\n開廷まで一切の面会を禁じます。",
  ui_story_5043_50431101_63_dialog_content = "独房！？頭がおかしくなったのですか！？",
  ui_story_5043_50431101_64_dialog_content = "判決前に容疑者を独房に入れるのは違法だ。\nお前にそのような権限はなかろう！",
  ui_story_5043_50431101_65_dialog_content = "恋愛訴訟部の法廷において、\n私は「有罪」判決を下す権限を持っています。",
  ui_story_5043_50431101_66_dialog_content = "容疑者を独房に入れるのは必要な手続きの一つです。\nそれとも貴方たちは法に疑問をもっておられるのですか？",
  ui_story_5043_50431101_67_dialog_content = "クッ…",
  ui_story_5043_50431101_68_dialog_content = "お、落ち着いてください！",
  ui_story_5043_50431101_69_dialog_content = "私はシュワーベ裁判長の指示に従いますわ。\n開廷後、反論すればよいだけのことです。",
  ui_story_5043_50431101_70_dialog_content = "ティナ…",
  ui_story_5043_50431101_71_dialog_content = "私は裁判官です。白夜城の司法制度は決して罪のない者に\n罪を着せたりはしないと信じています。",
  ui_story_5043_50431101_72_dialog_content = "明日開廷さえすれば、真相は必ず明らかになります。",
  ui_story_5043_50431101_73_dialog_content = "私は法廷を信じます。",
  ui_story_5043_50431101_74_dialog_content = "皆さんのことを信じます。",
  ui_story_5043_50431101_75_dialog_content = "…",
  ui_story_5043_50431101_76_dialog_content = "…",
  ui_story_5043_50431101_77_dialog_content = "衛兵、容疑者を連れて行け。",
  ui_story_5043_50431101_78_dialog_content = "了解です！",
  ui_story_5043_50431101_79_dialog_content = "<color=#e8d9bb>アップタウン、法廷の外</color>",
  ui_story_5043_50431101_80_dialog_content = "どうしよう、ティナが捕まっちゃったよ。",
  ui_story_5043_50431101_81_dialog_content = "明日の裁判でティナは有罪になっちゃうの！？",
  ui_story_5043_50431101_82_dialog_content = "この状態で開廷すれば…そうなります。",
  ui_story_5043_50431101_83_dialog_content = "そ、そんな！ティナは絶対に無罪だよ！",
  ui_story_5043_50431101_84_dialog_content = "…それはそうと…シュワーベの様子…\nどこかおかしいと思いませんでしたか？",
  ui_story_5043_50431101_85_dialog_content = "えっ？",
  ui_story_5043_50431101_86_dialog_content = "前からヘンな感じの人だなとは思ってたけど、確かに…",
  ui_story_5043_50431101_87_dialog_content = "今日の法廷での態度はちょっと行き過ぎだったね。",
  ui_story_5043_50431101_88_dialog_content = "奴は明らかに我々に敵意を持っておる。",
  ui_story_5043_50431101_89_dialog_content = "ティナに不利な情報だけを誇張し、\nあらゆる反論を封じおった。",
  ui_story_5043_50431101_90_dialog_content = "ええ。すべてが都合よくできすぎています。",
  ui_story_5043_50431101_91_dialog_content = "事件発生の直後に証拠品と対になるもう片方の手袋を\n部下に探させています…",
  ui_story_5043_50431101_92_dialog_content = "まるで手袋がどんなデザインかを\n最初から知っていたかのようです…",
  ui_story_5043_50431101_93_dialog_content = "しかも、現場の状況をよく知っているようであった。",
  ui_story_5043_50431101_94_dialog_content = "先程の自信ありげな憎たらしい顔を見たであろう？",
  ui_story_5043_50431101_95_dialog_content = "本当にそうでしょうか？よく考えてみてください。",
  ui_story_5043_50431101_96_dialog_content = "事件の起こった瞬間、ティナ裁判官は本当に貴方たちと共に\n暗鬼と戦っていたのですか？",
  ui_story_5043_50431101_97_dialog_content = "明らかに現場にいなかった者が、\nなぜあのような質問をするのだ？",
  ui_story_5043_50431101_98_dialog_content = "そうだよね！",
  ui_story_5043_50431101_99_dialog_content = "確かに…さっきは順調すぎるくらいに、\nティナが容疑者だって結論になった。",
  ui_story_5043_50431101_100_dialog_content = "すべてがティナは有罪だってことを示してた…",
  ui_story_5043_50431101_101_dialog_content = "だが、それもこれもあくまで推測、\n最も疑わしいのはそこではない。",
  ui_story_5043_50431101_102_dialog_content = "奴の最後の言動だ。",
  ui_story_5043_50431101_103_dialog_content = "その通りです。",
  ui_story_5043_50431101_104_dialog_content = "手袋を見つけたことも現場の状況を知っていたことも、\n運が良かった、見張りがいたなど、いくらでも説明がつきます。",
  ui_story_5043_50431101_105_dialog_content = "奴の証拠収集は規則にのっとっており、\n付け入る隙はありません。",
  ui_story_5043_50431101_106_dialog_content = "いかにも。だが、最後に焦りが出たな。",
  ui_story_5043_50431101_107_dialog_content = "我々が証拠品を調べることを許さず、\nかつティナを独房に入れることを強行した。",
  ui_story_5043_50431101_108_dialog_content = "何かを見られたくないことは明らかだ。",
  ui_story_5043_50431101_109_dialog_content = "殊に我々に見せたくないのだ。",
  ui_story_5043_50431101_110_dialog_content = "ええ、規則を破ってでも、\n何かの手がかりを隠そうとしているわけですね。",
  ui_story_5043_50431101_111_dialog_content = "ティナに罪を着せた理由も、きっとそこに隠されているはずです。",
  ui_story_5043_50431101_112_dialog_content = "わあ！すごい推理だね！",
  ui_story_5043_50431101_113_dialog_content = "発言に気をつけろ。",
  ui_story_5043_50431101_114_dialog_content = "法廷の前だぞ。",
  ui_story_5043_50431101_115_dialog_content = "あ、そうだったね。声を抑えなきゃ。",
  ui_story_5043_50431101_116_dialog_content = "…ということはつまり、シュワーベが隠してる手がかりを見つければ、\nティナの罪は晴れるってことだよね？",
  ui_story_5043_50431101_117_dialog_content = "確かにその通りですが、おそらく見つけるのは無理でしょう。",
  ui_story_5043_50431101_118_dialog_content = "えっ？",
  ui_story_5043_50431101_119_dialog_content = "シュワーベは必ず開廷までに\nすべての手がかりを消してしまうでしょう。",
  ui_story_5043_50431101_120_dialog_content = "そして、その手がかりが何かを奴は知っていて、\n私たちは知りません。",
  ui_story_5043_50431101_121_dialog_content = "しかも策においては、あちらの方が上手です。",
  ui_story_5043_50431101_122_dialog_content = "この差はどうしようもありません。",
  ui_story_5043_50431101_123_dialog_content = "じゃ、じゃあ…どうすればいいの？\n開廷を待つしかないの？",
  ui_story_5043_50431101_124_dialog_content = "今ある情報だけでは、ティナは有罪判決となってしまうでしょう。",
  ui_story_5043_50431101_125_dialog_content = "開廷までに他の手がかりを収集しなければなりません。",
  ui_story_5043_50431101_126_dialog_content = "奴が隠そうとしている核心には触れられなくても、\n他に何かしら手がかりがあるはずです。",
  ui_story_5043_50431101_127_dialog_content = "ハハハ、面白そうではないか！",
  ui_story_5043_50431101_128_dialog_content = "何か考えがあるようだな？",
  ui_story_5043_50431101_129_dialog_content = "おい、バカなマネはよせ。",
  ui_story_5043_50431101_130_dialog_content = "お前は頭が固すぎるのだ！",
  ui_story_5043_50431101_131_dialog_content = "他にも調査することがある。\nこれ以上お前たちに付き合っていられない。",
  ui_story_5043_50431101_132_dialog_content = "お前たちのやろうとしてることに私は関わらない。\nだが、聞かなかったことにしてやる。",
  ui_story_5043_50431101_133_dialog_content = "クッ…",
  ui_story_5043_50431101_134_dialog_content = "これでいいのです。人数が多いとかえって面倒です。",
  ui_story_5043_50431101_135_dialog_content = "では…お二人とも少し寄ってください。",
  ui_story_5043_50431101_136_dialog_content = "うん、何？",
  ui_story_5043_50431101_137_dialog_content = "シュワーベは秘密を隠すために規則を破りました。",
  ui_story_5043_50431101_138_dialog_content = "ならば私たちも規則を破らなければ勝てません。",
  ui_story_5043_50431101_139_dialog_content = "どうするの？",
  ui_story_5043_50431101_140_dialog_content = "シュワーベ家に潜入するのです。",
  ui_story_5043_50431101_141_dialog_content = "え！？",
  ui_story_5043_50431101_142_dialog_content = "証拠品と容疑者への接触が許されないのならば、\nシュワーベ本人を探るしかありません。",
  ui_story_5043_50431101_143_dialog_content = "自宅は最も秘密を守れる安全な場所です。",
  ui_story_5043_50431101_144_dialog_content = "何か他人に言えない秘密を持っているとしたら、\n手がかりは自宅にあると考えるのが妥当でしょう。",
  ui_story_5043_50431101_145_dialog_content = "でも…違法でしょ？",
  ui_story_5043_50431101_146_dialog_content = "面白い！実に面白いではないか！",
  ui_story_5043_50431101_147_dialog_content = "よし、その方法でいこうではないか！\n奴の荘園を探るのだ！",
  ui_story_5043_50431101_148_dialog_content = "…裁判官じゃない僕が一番法律を気にしてるみたいだね…",
  ui_story_5043_50431101_149_dialog_content = "貴方も先程聞いていたでしょう？\nあちらの違法行為が私たちを追い込んだのですよ。",
  ui_story_5043_50431101_150_dialog_content = "すべてが終わったら、私が自ら進んで\n住居侵入の罪を負いましょう。",
  ui_story_5043_50431101_151_dialog_content = "ですが今はティナの冤罪を晴らすことが何よりも先です。",
  ui_story_5043_50431101_152_dialog_content = "自分から責任を負うと？",
  ui_story_5043_50431101_153_dialog_content = "まったく…お前のようなバカ正直は今後損をするぞ。",
  ui_story_5043_50431101_154_dialog_content = "うん、そうだね…今一番大事なのはティナの無罪を証明することだ！",
  ui_story_5043_50431101_155_dialog_content = "じゃあ、今すぐ出発するの？",
  ui_story_5043_50431101_156_dialog_content = "その前に少々やることがあります。",
  ui_story_5043_50431101_157_dialog_content = "お気づきになりましたか？\n先程からずっと衛兵に尾行されています。",
  ui_story_5043_50431101_158_dialog_content = "おそらくは奴の仕業でしょう。\n私たちに自由に行動させるつもりはないようです。",
  ui_story_5043_50431101_159_dialog_content = "じゃあ、尾行をまくの？",
  ui_story_5043_50431101_160_dialog_content = "ええ、今方法を考えているところです。",
  ui_story_5043_50431101_161_dialog_content = "それなら簡単だよ。逃げることなら得意なんだ。",
  ui_story_5043_50431101_162_dialog_content = "だって僕には「目」が4つあるようなものだからね。",
  ui_story_5043_50431101_163_dialog_content = "そうでした！空の末裔の感知能力をお借りすればいいのですね！",
  ui_story_5043_50431101_164_dialog_content = "よかった…では逃走のプロである空の末裔さん、\nまずは何をすればよろしいですか？",
  ui_story_5043_50431101_165_dialog_content = "単純なことだよ。",
  ui_story_5043_50431101_166_dialog_content = "一番最初にすべきことはもちろん――",
  ui_story_5043_50431101_167_dialog_content = "走る！！",
  ui_story_5043_50431102_1_dialog_content = "この先を右！",
  ui_story_5043_50431102_2_dialog_content = "貴族の私がなぜ走らねばならんのだ！",
  ui_story_5043_50431102_3_dialog_content = "どうだ？衛兵たちはまだついてきておるか？",
  ui_story_5043_50431102_4_dialog_content = "衛兵？もちろん、1人もいないよ。",
  ui_story_5043_50431102_5_dialog_content = "では、なぜまだ走っておる！？",
  ui_story_5043_50431102_6_dialog_content = "だって、シュワーベの家に行くんでしょ。",
  ui_story_5043_50431102_7_dialog_content = "今そっちへ向かってるんだよ。",
  ui_story_5043_50431102_8_dialog_content = "尾行を振りきったのなら、走る必要などなかろうが！",
  ui_story_5043_50431102_9_dialog_content = "それにお前がなぜシュワーベの家を知っておるのだ！？",
  ui_story_5043_50431102_10_dialog_content = "先程私がお教えしたのです。",
  ui_story_5043_50431102_11_dialog_content = "残された時間は多くありません。\n走ればそれだけ早く着きます。",
  ui_story_5043_50431102_12_dialog_content = "ならば、せめて追っ手を振り切ったことくらい教えぬか！\n追っ手がいるのといないのでは疲れ方が違うのだぞ！",
  ui_story_5043_50431102_13_dialog_content = "それは申し訳ありませんでした。\nすぐこの先ですよ、声を抑えてください。",
  ui_story_5043_50431102_14_dialog_content = "庶民の新人めが…！",
  ui_story_5043_50431102_15_dialog_content = "<color=#e8d9bb>アップタウン、サラール家の荘園の外</color>",
  ui_story_5043_50431102_16_dialog_content = "入口には護衛と使用人がたくさんいるみたいだね。",
  ui_story_5043_50431102_17_dialog_content = "あの人たちに見つからないように手がかりを探すなんて…",
  ui_story_5043_50431102_18_dialog_content = "ええ、とても危険な計画です。",
  ui_story_5043_50431102_19_dialog_content = "もし見つかれば、明日の法廷で被告席に立つのは私たちでしょう。",
  ui_story_5043_50431102_20_dialog_content = "覚悟は、よろしいですか？",
  ui_story_5043_50431102_21_dialog_content = "ティナの罪を晴らす唯一の方法なんだよね…",
  ui_story_5043_50431102_22_dialog_content = "危険でもやるしかないよ！",
  ui_story_5043_50431102_23_dialog_content = "我々に不利なことばかりでもなかろうが。\n荘園は広い。隠れる所はいくらでもある。",
  ui_story_5043_50431102_24_dialog_content = "加えてPlayerNameの感知能力があるのだぞ。\n危機を逃れるのはたやすい。",
  ui_story_5043_50431102_25_dialog_content = "そうだね！いつも以上に頑張るよ！",
  ui_story_5043_50431102_26_dialog_content = "だが、どうやって侵入するのだ？",
  ui_story_5043_50431102_27_dialog_content = "衛兵どもの交代を待つ余裕はなかろう…",
  ui_story_5043_50431102_28_dialog_content = "大丈夫です。正面から入るわけではありませんから。",
  ui_story_5043_50431102_29_dialog_content = "ほう？他にも門があるのか？",
  ui_story_5043_50431102_30_dialog_content = "ご覧ください。あちらに庭園があるでしょう。\nあそこなら低木がたくさん植わっているので身を隠せます。",
  ui_story_5043_50431102_31_dialog_content = "庭園側の壁を越えて侵入するのです。",
  ui_story_5043_50431102_32_dialog_content = "壁を越えるだと！？",
  ui_story_5043_50431102_33_dialog_content = "確かにあそこならいけそうだね。\n壁もそう高くない！",
  ui_story_5043_50431102_34_dialog_content = "では、行きましょう。",
  ui_story_5043_50431102_35_dialog_content = "うん！",
  ui_story_5043_50431102_36_dialog_content = "おい、待たぬか！壁を越えるなど優雅ではなかろうが！？",
  ui_story_5043_50431102_37_dialog_content = "かりにも私はサーイエ家の…",
  ui_story_5043_50431102_38_dialog_content = "…まあ、よい。\nお前たち庶民にはうんざりだ…",
  ui_story_5043_50431201_1_dialog_content = "ああ…なぜ私まで、\nこのようなバカげた真似をせねばならんのだ…",
  ui_story_5043_50431201_2_dialog_content = "ティナの罪を晴らすためだよ。耐えて。",
  ui_story_5043_50431201_3_dialog_content = "ほら、少なくとも無事に荘園に侵入できたよ。",
  ui_story_5043_50431201_4_dialog_content = "よく見ると…すごくきれいな所だね。",
  ui_story_5043_50431201_5_dialog_content = "ここがシュワーベの家？",
  ui_story_5043_50431201_6_dialog_content = "ええ。うらやましいですね。",
  ui_story_5043_50431201_7_dialog_content = "サラール家は白夜城で絶大な影響力を持っておるからな。",
  ui_story_5043_50431201_8_dialog_content = "この荘園もサラール家の財産のほんの一部でしかない。",
  ui_story_5043_50431201_9_dialog_content = "シッ！静かに。誰かいます。",
  ui_story_5043_50431201_10_dialog_content = "行ってみましょう。",
  ui_story_5043_50431201_11_dialog_content = "あ！見えたよ！",
  ui_story_5043_50431201_12_dialog_content = "あれは…シュワーベかな？",
  ui_story_5043_50431201_13_dialog_content = "シュワーベ様、申し訳ございません。\n見失ってしまいました。",
  ui_story_5043_50431201_14_dialog_content = "あの裁判官2人と空の末裔…意外にも足が速く、\nしかもあちこち何度も曲がったため、追いつけませんでした。",
  ui_story_5043_50431201_15_dialog_content = "これだけの衛兵がいながら、見失っただと？",
  ui_story_5043_50431201_16_dialog_content = "役立たずめ！",
  ui_story_5043_50431201_17_dialog_content = "申し訳ございません！",
  ui_story_5043_50431201_18_dialog_content = "もういい。見失ったものは仕方ない。",
  ui_story_5043_50431201_19_dialog_content = "奴らは焦っている。どこかでミスを犯すはずだ。\nそうすれば、こっちに有利に働く。",
  ui_story_5043_50431201_20_dialog_content = "お前たちは下がれ。",
  ui_story_5043_50431201_21_dialog_content = "はい、シュワーベ様！",
  ui_story_5043_50431201_22_dialog_content = "やはり衛兵に我々を張らせていたか。\nフン、そう何もかも思い通りには行かぬぞ！",
  ui_story_5043_50431201_23_dialog_content = "私たちは運がいいですね。\nいきなりシュワーベを見つけましたよ。",
  ui_story_5043_50431201_24_dialog_content = "見失わないようにしなければなりません。\n奴が何をするつもりなのか確かめなければ。",
  ui_story_5043_50431201_25_dialog_content = "どんなささいなことでも何かおかしな行動をとれば、\nそれが大切な手がかりです。",
  ui_story_5043_50431201_26_dialog_content = "うん、分かった！",
  ui_story_5043_50431201_27_dialog_content = "だが、気を抜いてはならんぞ。\nシュワーベは常識では推し量れぬ男だ。",
  ui_story_5043_50431201_28_dialog_content = "法廷で堂々と規則を破る奴だ。\n家ではさらに恐ろしいことをしていてもおかしくはない。",
  ui_story_5043_50431201_29_dialog_content = "…そ、そんなこと言われると…怖くなってきた…",
  ui_story_5043_50431201_30_dialog_content = "恐れは慎重さにつながる。",
  ui_story_5043_50431201_31_dialog_content = "さあ、行くぞ。見失ってはならん。",
  ui_story_5043_50431201_32_dialog_content = "シュワーベ様、お茶が入りました。",
  ui_story_5043_50431201_33_dialog_content = "うむ、ありがとう。",
  ui_story_5043_50431201_34_dialog_content = "厨房にお茶菓子を作らせております。\nすぐにお持ちいたします。",
  ui_story_5043_50431201_35_dialog_content = "必要ない。私にはまだやることがある。",
  ui_story_5043_50431201_36_dialog_content = "しばらく私の邪魔をするな。",
  ui_story_5043_50431201_37_dialog_content = "は、はい、承知いたしました！",
  ui_story_5043_50431201_38_dialog_content = "…人払いをしましたね。",
  ui_story_5043_50431201_39_dialog_content = "ふうむ…ということは、\n家の者にも秘密にしていることがあるのか？",
  ui_story_5043_50431201_40_dialog_content = "うーん…ただ一人になりたいだけかも？",
  ui_story_5043_50431201_41_dialog_content = "気を抜くでないぞ、PlayerName！",
  ui_story_5043_50431201_42_dialog_content = "先程言ったことを忘れたか？\nシュワーベは常識では推し量れぬ男だ。",
  ui_story_5043_50431201_43_dialog_content = "分かったよ。",
  ui_story_5043_50431201_44_dialog_content = "でも、たとえそうだとしても、\n自分の家の庭で何ができるっていうの？",
  ui_story_5043_50431201_45_dialog_content = "ご覧ください！手を動かしていますよ！",
  ui_story_5043_50431201_46_dialog_content = "何か持っているようですね？",
  ui_story_5043_50431201_47_dialog_content = "針だな。手に銀の針を持っておる。",
  ui_story_5043_50431201_48_dialog_content = "針！？",
  ui_story_5043_50431201_49_dialog_content = "何をするつもりだ？自分の手でも刺そうというのか？",
  ui_story_5043_50431201_50_dialog_content = "いいえ、奴が刺そうとしているのは…",
  ui_story_5043_50431201_51_dialog_content = "<color=#e8d9bb>ブスッ――</color>",
  ui_story_5043_50431201_52_dialog_content = "手に持っている人形です…",
  ui_story_5043_50431201_53_dialog_content = "ど、どうして人形にそんなことするの？",
  ui_story_5043_50431201_54_dialog_content = "…人形を使った呪いがあるのを知っているか？",
  ui_story_5043_50431201_55_dialog_content = "呪い？",
  ui_story_5043_50431201_56_dialog_content = "相手の身体の一部――通常は血液や髪の毛を使うのだが、\nそれを人形の中に入れるのだ。",
  ui_story_5043_50431201_57_dialog_content = "すると人形は本人の分身となる。",
  ui_story_5043_50431201_58_dialog_content = "分身たる人形を針で刺せば、本人に痛みを感じさせ、\nひいては傷を負わせることもできるのだ。",
  ui_story_5043_50431201_59_dialog_content = "最後には、多くが痛みで死んでしまう…",
  ui_story_5043_50431201_60_dialog_content = "<color=#e8d9bb>ブスッ――</color>",
  ui_story_5043_50431201_61_dialog_content = "チッ、また刺しおったわ！",
  ui_story_5043_50431201_62_dialog_content = "そのような呪いがあると聞いたことはあります。\nまさかシュワーベにそんな陰湿な一面があるとは…",
  ui_story_5043_50431201_63_dialog_content = "特に意外でもなかろう。\nあの情に厚い、優しいイメージはそもそも演技なのだからな。",
  ui_story_5043_50431201_64_dialog_content = "だとしても、人形で呪いなど子供だましの伝説でしょう？",
  ui_story_5043_50431201_65_dialog_content = "しかも、白夜城の教義に則れば、あのような行為はおそらく…",
  ui_story_5043_50431201_66_dialog_content = "分かった。つまり、重要なのは呪いが本当かどうかじゃなくて、\n皆が信じるかどうかなんだね。",
  ui_story_5043_50431201_67_dialog_content = "…で、シュワーベはそれを信じてる。",
  ui_story_5043_50431201_68_dialog_content = "つまり、今この時、この世界にシュワーベが恨んでる人、\n死んでほしいとまで恨んでる人がいるってことだね…",
  ui_story_5043_50431201_69_dialog_content = "<color=#e8d9bb>ブスッ――</color>",
  ui_story_5043_50431201_70_dialog_content = "あいつ…本当に殺す気でしょうか！？",
  ui_story_5043_50431201_71_dialog_content = "いったい誰をあそこまで恨んでいるというのだ？\n死を望むほどの恨みだぞ！",
  ui_story_5043_50431201_72_dialog_content = "うーん…確かに不思議だね。",
  ui_story_5043_50431201_73_dialog_content = "シュワーベの人生はあんなに華やかで輝いてて、\n誰も邪魔なんてできそうもないのに。",
  ui_story_5043_50431201_74_dialog_content = "他人には…見えない闇を持ってるってことかな？",
  ui_story_5043_50431201_75_dialog_content = "ほう、お前の今の言葉で分かったぞ。",
  ui_story_5043_50431201_76_dialog_content = "奴にはきっと誰にも知られていない、\n忘れられぬ<color=#FFB400>恋</color>の思い出があるのだ。",
  ui_story_5043_50431201_77_dialog_content = "<color=#e8d9bb>ブスッ――</color>",
  ui_story_5043_50431201_78_dialog_content = "もしそうなら、私たちも手をこまねいてはいられません。\n人の命がかかっています！",
  ui_story_5043_50431201_79_dialog_content = "そう衝動的になるでない。\nいずれにせよ、実際の犯罪行為に及ばない限り、我々とて手は出せん。",
  ui_story_5043_50431201_80_dialog_content = "だが、確かに何かせねば…\nこのまま人形を刺し続けるのを見ているわけにもいかん。",
  ui_story_5043_50431201_81_dialog_content = "ねえ…伝説は本当なのかな？",
  ui_story_5043_50431201_82_dialog_content = "人形の呪いですか？",
  ui_story_5043_50431201_83_dialog_content = "うん…",
  ui_story_5043_50431201_84_dialog_content = "伝説が本当なら、僕たちは今…",
  ui_story_5043_50431201_85_dialog_content = "「殺人事件」の現場を見てることになる…",
  ui_story_5043_50431201_86_dialog_content = "これで最後だ。",
  ui_story_5043_50431201_87_dialog_content = "さあ、1つの命が今まさに…",
  ui_story_5043_50431201_88_dialog_content = "急いでやめさせるのです！",
  ui_story_5043_50431201_89_dialog_content = "<color=#e8d9bb>ブスッ――</color>",
  ui_story_5043_50431201_90_dialog_content = "誕生した！！",
  ui_story_5043_50431201_91_dialog_content = "おやおや、なんと可愛らしいことだ。",
  ui_story_5043_50431201_92_dialog_content = "名前を付けてあげよう…そうだな…\n「チェスナット」がいい！",
  ui_story_5043_50431201_93_dialog_content = "あれって…ハリネズミのぬいぐるみ？",
  ui_story_5043_50431201_94_dialog_content = "ええ、そのようですね。ハリネズミです。",
  ui_story_5043_50431201_95_dialog_content = "確かにイガグリそっくりだな。\n名付けのセンスはあるようだ。",
  ui_story_5043_50431201_96_dialog_content = "<size=45>さっきまでの緊張感は何だったの！？</size>",
  ui_story_5043_50431201_97_dialog_content = "シッ！声が大きい！",
  ui_story_5043_50431201_98_dialog_content = "ふぅ…なんか滑稽だね…誰かを呪い殺そうとしてるなんて、\n本気で心配してたんだから…",
  ui_story_5043_50431201_99_dialog_content = "オホン…事件捜査には、あらゆる可能性の想定と分析が必要なのです。",
  ui_story_5043_50431201_100_dialog_content = "一つ一つの可能性に慎重に対処していくことが、\n真相にたどり着くための道なのですよ。",
  ui_story_5043_50431201_101_dialog_content = "そんなに真面目くさった理由で言い訳しなくても…",
  ui_story_5043_50431201_102_dialog_content = "さあ、今のことは忘れて、ティナのことを考えましょう。",
  ui_story_5043_50431201_103_dialog_content = "シュワーベが中に入りますよ。\n明日の裁判の準備をするつもりかもしれません。",
  ui_story_5043_50431201_104_dialog_content = "急いで追いましょう。",
  ui_story_5043_50431201_105_dialog_content = "はぁ、実験はまだ終わっていない。\n今日少しでも進展があるといいのだが…",
  ui_story_5043_50431201_106_dialog_content = "おい、聞いたか？今「実験」と言ったな？",
  ui_story_5043_50431201_107_dialog_content = "ええ、いったい何の研究をしているのでしょう？",
  ui_story_5043_50431201_108_dialog_content = "フン、よからぬことに決まっておるわ。\nシュワーベは常識では推し量れぬ男だ。",
  ui_story_5043_50431201_109_dialog_content = "…また「常識では推し量れない」？",
  ui_story_5043_50431201_110_dialog_content = "さっきのこと忘れたの？\n今度こそ先入観を持たずによく見てみようよ。",
  ui_story_5043_50431201_111_dialog_content = "ただ実験してるってだけなら、趣味みたいなものかも…",
  ui_story_5043_50431201_112_dialog_content = "<color=#e8d9bb>ボンッ――！</color>",
  ui_story_5043_50431201_113_dialog_content = "うわぁああ！",
  ui_story_5043_50431201_114_dialog_content = "爆発か？いったい何をしておるのだ！？",
  ui_story_5043_50431201_115_dialog_content = "わ、分からないよ。近づいてみる？",
  ui_story_5043_50431201_116_dialog_content = "ダメです！室内では身を隠せません。",
  ui_story_5043_50431201_117_dialog_content = "これ以上近づいたら、気付かれてしまいます…",
  ui_story_5043_50431201_118_dialog_content = "<color=#e8d9bb>ボンッ――！</color>",
  ui_story_5043_50431201_119_dialog_content = "また爆発したぞ！あやつ、爆薬を研究しているのではないか！？",
  ui_story_5043_50431201_120_dialog_content = "爆薬！？それはないでしょ…",
  ui_story_5043_50431201_121_dialog_content = "いや、爆薬はサラール家の家業でもあるのだ！",
  ui_story_5043_50431201_122_dialog_content = "<color=#e8d9bb>ボンッ――！</color>",
  ui_story_5043_50431201_123_dialog_content = "でも、爆薬なんて研究してどうするんだろう？",
  ui_story_5043_50431201_124_dialog_content = "白夜城のような美しく精巧に造られた街ほど、\n爆弾のような力による破壊に弱いのです。",
  ui_story_5043_50431201_125_dialog_content = "考えてもみてください。ここではたかが彫像1体が壊されただけで、\n裁判になるのですよ。",
  ui_story_5043_50431201_126_dialog_content = "もし鐘楼や教会が破壊されでもしたら、\nとんでもない騒ぎになることは明らかです。",
  ui_story_5043_50431201_127_dialog_content = "よからぬ考えの持ち主が爆薬を手にすれば、\n人々の破壊に対する恐怖を利用して、好き勝手を働くことができることでしょう。",
  ui_story_5043_50431201_128_dialog_content = "でも、ほんの少量の爆薬だよ？\n自分の家さえも吹き飛ばせない量なのに、それは大げさじゃ…",
  ui_story_5043_50431201_129_dialog_content = "今はただの「実験」にすぎません。",
  ui_story_5043_50431201_130_dialog_content = "原理さえ分かれば、光力術で爆発の威力を数十倍、数百倍にすることは簡単です。",
  ui_story_5043_50431201_131_dialog_content = "この爆薬の研究一つで、\nシュワーベは今の白夜城の社会をひっくり返すことができるのです。",
  ui_story_5043_50431201_132_dialog_content = "白夜城の統治を転覆できると言っても、過言ではありません…",
  ui_story_5043_50431201_133_dialog_content = "そ、そんな大変なことなの！？",
  ui_story_5043_50431201_134_dialog_content = "<color=#e8d9bb>ボンッ――！</color>",
  ui_story_5043_50431201_135_dialog_content = "ゴホッ、ゴホゴホッ…",
  ui_story_5043_50431201_136_dialog_content = "やはりダメか…。",
  ui_story_5043_50431201_137_dialog_content = "まさか「<color=#FFB400>キャラメルプリン</color>」を作るのが、\nこんなに大変だとは思わなかった。",
  ui_story_5043_50431201_138_dialog_content = "…",
  ui_story_5043_50431201_139_dialog_content = "…キャラメルプリンで…白夜城統治の…転覆？",
  ui_story_5043_50431201_140_dialog_content = "ぶ、不器用にも程があろう！？\n菓子を作るのにこれほど大きな音を立てるとは何事だ！",
  ui_story_5043_50431201_141_dialog_content = "君たちの推測もかなりとんでもないよ…",
  ui_story_5043_50431201_142_dialog_content = "シッ、奴が出てくるぞ。\n隠れるとしよう。",
  ui_story_5043_50431201_143_dialog_content = "ああ、また無駄に時間を使ってしまった。",
  ui_story_5043_50431201_144_dialog_content = "やはり仕事をするとするか。\n地下室の鍵は確か…ここにだったな。",
  ui_story_5043_50431201_145_dialog_content = "開廷前にもう一度調べておかなければ…",
  ui_story_5043_50431201_146_dialog_content = "シュワーベ様、お夕食のお時間です。",
  ui_story_5043_50431201_147_dialog_content = "…邪魔をするなと言わなかったか？",
  ui_story_5043_50431201_148_dialog_content = "申し訳ございません！ただ…お夕食の準備が整いましたので…",
  ui_story_5043_50431201_149_dialog_content = "分かった。先に食事としよう。",
  ui_story_5043_50431201_150_dialog_content = "シュワーベが食事に行きました。\n食堂は使用人も多い…尾行もひとまずここまでですね。",
  ui_story_5043_50431201_151_dialog_content = "おい、あやつ…立ち去る前に何か言ったな！？",
  ui_story_5043_50431201_152_dialog_content = "また「常識では推し量れない」？",
  ui_story_5043_50431201_153_dialog_content = "ええいっ、それはもうよい。\n地下室がどうのと言っておったぞ。",
  ui_story_5043_50431201_154_dialog_content = "思い出してもみよ――\n奴は鍵を取り出し、中へ入ろうとしたところで使用人に呼び止められた。",
  ui_story_5043_50431201_155_dialog_content = "見るがいい。ドアにはまだ鍵が差し込まれたままだ。",
  ui_story_5043_50431201_156_dialog_content = "入ってみぬか？中には多くの秘密が隠されているに違いない！",
  ui_story_5043_50431201_157_dialog_content = "確かにまたとないチャンスだけど…",
  ui_story_5043_50431201_158_dialog_content = "まだティナに関する手がかりも見つかってないし、\n今地下室に忍び込むのは目的に反するんじゃないかな？",
  ui_story_5043_50431201_159_dialog_content = "ティナが無罪なら、問題は必ずシュワーベにあるはずです。",
  ui_story_5043_50431201_160_dialog_content = "誰かに利用されていたとしても、\n奴の周りには何かしらの手がかりが残っているはずです。",
  ui_story_5043_50431201_161_dialog_content = "見つからないのは、私たちがまだ深く探れていないからにすぎませんよ。",
  ui_story_5043_50431201_162_dialog_content = "…そうだね。今さら引き返せない。\n行こう！地下室を見てみよう！",
  ui_story_5043_50431201_163_dialog_content = "<color=#e8d9bb>ギィ――</color>",
  ui_story_5043_50431201_164_dialog_content = "むむ、なんという暗さだ！\n何も見えんではないか！",
  ui_story_5043_50431201_165_dialog_content = "下へつながる階段があるようですね。\n手探りでなんとか進めそうです…",
  ui_story_5043_50431201_166_dialog_content = "ティナ！ティナ？いるのですか？",
  ui_story_5043_50431201_167_dialog_content = "おい、PlayerName。\nお前なら感知できるであろう？",
  ui_story_5043_50431201_168_dialog_content = "中の様子を感知能力で探ってみてくれぬか？",
  ui_story_5043_50431201_169_dialog_content = "うん、やってみるよ。",
  ui_story_5043_50431201_170_option_content = "強制感知",
  ui_story_5043_50431201_171_dialog_content = "いやはや、空の末裔がいると実に便利でよいわ。",
  ui_story_5043_50431201_172_dialog_content = "どうだ？何か分かったか？",
  ui_story_5043_50431201_173_dialog_content = "まずはロウソクか何か照明になるものがないか探すのだ。",
  ui_story_5043_50431201_174_dialog_content = "この地下室、ずいぶん深いみたいだ…",
  ui_story_5043_50431201_175_dialog_content = "あれ？何かこっちへ来る。",
  ui_story_5043_50431201_176_dialog_content = "これは…",
  ui_story_5043_50431201_177_dialog_content = "グアアア――",
  ui_story_5043_50431201_178_dialog_content = "うわああああ！！",
  ui_story_5043_50431201_179_dialog_content = "どうした？何があったのだ！？",
  ui_story_5043_50431201_180_dialog_content = "い、急いで逃げて！引き返すんだ！",
  ui_story_5043_50431201_181_dialog_content = "暗鬼の群れが上がってくるよ！！",
  ui_story_5043_50431202_1_dialog_content = "ガァ…",
  ui_story_5043_50431202_2_dialog_content = "暗鬼だと？なんと気色の悪い！",
  ui_story_5043_50431202_3_dialog_content = "貴族のお屋敷には装飾だけでなく、\n暗鬼もたくさんいるものなのですか？",
  ui_story_5043_50431202_4_dialog_content = "貴族を侮辱するでない！\n我が家には気色の悪いバケモノなどおらぬわ！",
  ui_story_5043_50431202_5_dialog_content = "急いで逃げて！また飛び掛かってくるよ！",
  ui_story_5043_50431202_6_dialog_content = "早く地下室の外へお逃げください！\n私が暗鬼を引き止めます！",
  ui_story_5043_50431202_7_dialog_content = "だ、大丈夫？",
  ui_story_5043_50431202_8_dialog_content = "白夜城の裁判官を甘く見てはいけませんよ。",
  ui_story_5043_50431202_9_dialog_content = "暗鬼め、受けてみよ…",
  ui_story_5043_50431202_10_dialog_content = "<color=#e8d9bb>パリン――！</color>",
  ui_story_5043_50431202_11_dialog_content = "なんと！部屋のシャンデリアが割れてしまったぞ！",
  ui_story_5043_50431202_12_dialog_content = "北境の晶鉱で作られたものと見える。\n高価なものであろうに。",
  ui_story_5043_50431202_13_dialog_content = "まさか弁償なんてことにはなりませんよね…？",
  ui_story_5043_50431202_14_dialog_content = "弁償のことはともかく、気を付けて！",
  ui_story_5043_50431202_15_dialog_content = "どうしてまた…",
  ui_story_5043_50431202_16_dialog_content = "<color=#e8d9bb>バン――！</color>",
  ui_story_5043_50431202_17_dialog_content = "お見事！今度はティーテーブルだ！",
  ui_story_5043_50431202_18_dialog_content = "なんと精巧な作りのテーブルだ。\nいやはや、奴の涙を流して悲しむ顔が浮かぶわ。",
  ui_story_5043_50431202_19_dialog_content = "申し訳ありません。ただ…弁償については、\n主な責任は私にはないように思いますが…",
  ui_story_5043_50431202_20_dialog_content = "話してる場合じゃないよ！もう少しでドアだ！",
  ui_story_5043_50431202_21_dialog_content = "急いで外に出なきゃ！",
  ui_story_5043_50431202_22_dialog_content = "<color=#e8d9bb>10分後</color>",
  ui_story_5043_50431202_23_dialog_content = "シュワーベ様、屋敷内のあちこちを探しましたが、\nよそ者の影はございませんでした。",
  ui_story_5043_50431202_24_dialog_content = "ただ、あちこち散らかっていて…いったい何があったのやら…",
  ui_story_5043_50431202_25_dialog_content = "…侵入者ではないことは確かか？",
  ui_story_5043_50431202_26_dialog_content = "はい。今の状況からすると侵入者ではございません。",
  ui_story_5043_50431202_27_dialog_content = "もちろん、侵入者の腕が立ち、\n何の痕跡も残さなかった可能性もございますが…",
  ui_story_5043_50431202_28_dialog_content = "法廷に被害届を出して…調査してもらいますか？",
  ui_story_5043_50431202_29_dialog_content = "シュワーベ様のお屋敷となれば、\nきっと重要案件として調べていただけるでしょう！",
  ui_story_5043_50431202_30_dialog_content = "被害届か…",
  ui_story_5043_50431202_31_dialog_content = "いや、その必要はない。",
  ui_story_5043_50431202_32_dialog_content = "たかの知れた家具が壊れたにすぎない。\n買い換えればいいだけのことだ。",
  ui_story_5043_50431202_33_dialog_content = "まずは掃除させろ。",
  ui_story_5043_50431202_34_dialog_content = "はい、シュワーベ様！",
  ui_story_5043_50431202_35_dialog_content = "（地下室のドアが開いている…）",
  ui_story_5043_50431202_36_dialog_content = "（食事前、私が開けたのか？）",
  ui_story_5043_50431202_37_dialog_content = "（何たることだ。この私がこのような低級なミスを犯すとは…）",
  ui_story_5043_50431202_38_dialog_content = "（今日は早めに休むこととしよう。\n開廷日には頭脳を明晰に保たなければならない）",
  ui_story_5043_50431202_39_dialog_content = "ああ、どうしてこんなことに…",
  ui_story_5043_50431202_40_dialog_content = "高価なシャンデリアとティーテーブルが壊れてしまった。",
  ui_story_5043_50431202_41_dialog_content = "こんな破片でも…かなりの値段になるんだろうな。",
  ui_story_5043_50431202_42_dialog_content = "はぁ…はぁ…",
  ui_story_5043_50431202_43_dialog_content = "（やっと…逃げ出せた！）",
  ui_story_5043_50431202_44_dialog_content = "どうだ、追っ手はついて来ているか？",
  ui_story_5043_50431202_45_dialog_content = "いないよ、もう大丈夫だ。",
  ui_story_5043_50431202_46_dialog_content = "チッ、まったく散々な目に遭った。\n今日は実についていない！",
  ui_story_5043_50431202_47_dialog_content = "何よりもティナどころか、\n有力な手がかりを一つもつかめなかったね。",
  ui_story_5043_50431202_48_dialog_content = "明日法廷に出たら、\nどうやってティナの罪を晴らせばいいんだろう…",
  ui_story_5043_50431202_49_dialog_content = "やるべきことはやったのです。\nあとは裁判官としての責務を最後まで全うするだけです。",
  ui_story_5043_50431202_50_dialog_content = "開廷までの時間、今日起きたことをすべて\n詳しく振り返ってみましょう。",
  ui_story_5043_50431202_51_dialog_content = "局面を打開する手がかりは、\nきっとささいなことの中に隠れているはずです。",
  ui_story_5043_50431202_52_dialog_content = "もちろん、職務であるかぎり全うすべきではあるが…",
  ui_story_5043_50431202_53_dialog_content = "決定的な手がかりを欠いているということは、\n切り札がないということだ。",
  ui_story_5043_50431202_54_dialog_content = "だが、奴には切り札がある。\nそして我々にはそれが何か見当もつかん。",
  ui_story_5043_50431202_55_dialog_content = "このまま法廷で戦うのは、\nあまりにも心許なかろう。",
  ui_story_5043_50431202_56_dialog_content = "カードゲームで勝つのは、\n大きなカードを持つ者とは限りませんよ。",
  ui_story_5043_50431202_57_dialog_content = "切り札がないのなら、技で補えばよいのです。",
  ui_story_5043_50431202_58_dialog_content = "ほう。肝心な時になると、かえって自信家になるようだな。",
  ui_story_5043_50431202_59_dialog_content = "私は真実に自信を持っているだけです。",
  ui_story_5043_50431202_60_dialog_content = "一方は真実を隠そうとし、もう一方は真実を明かそうとしている…\nこの本質からすれば、私たちはすでに優位に立っています。",
  ui_story_5043_50431202_61_dialog_content = "それにシュワーベ家に侵入して、\n何も収穫がなかったわけではありません…",
  ui_story_5043_50431301_1_dialog_content = "<color=#e8d9bb>翌日</color>",
  ui_story_5043_50431301_2_dialog_content = "（ついに…始まる――）",
  ui_story_5043_50431301_3_dialog_content = "（「連続首なし彫像事件」の審理がもうすぐ開廷する）",
  ui_story_5043_50431301_4_dialog_content = "（ライン、マシュー、ティナ…本当に真相を解明できるのかな…？）",
  ui_story_5043_50431301_5_dialog_content = "PlayerName！",
  ui_story_5043_50431301_6_dialog_content = "あ、カレン！それからローウェイも！",
  ui_story_5043_50431301_7_dialog_content = "戻ったんだね！",
  ui_story_5043_50431301_8_dialog_content = "ええ。言ったでしょう？開廷日には戻るって。",
  ui_story_5043_50431301_9_dialog_content = "ただ…",
  ui_story_5043_50431301_10_dialog_content = "どうしてティナが被告に？",
  ui_story_5043_50431301_11_dialog_content = "マシュー、見事な仕事ぶりだ。",
  ui_story_5043_50431301_12_dialog_content = "おい！もう一度言ってみよ…！",
  ui_story_5043_50431301_13_dialog_content = "…そ、そうなんだよ。",
  ui_story_5043_50431301_14_dialog_content = "おかしな証拠品のせいで、ティナが容疑者にされちゃったんだ。",
  ui_story_5043_50431301_15_dialog_content = "でも、法廷できっと逆転できるって信じてるよ！",
  ui_story_5043_50431301_16_dialog_content = "この2日間いったい何があったの？",
  ui_story_5043_50431301_17_dialog_content = "詳しいいきさつは、中に入ってから話すよ。",
  ui_story_5043_50431301_18_dialog_content = "<color=#e8d9bb>アップタウン、恋愛訴訟部</color>",
  ui_story_5043_50431301_19_dialog_content = "静粛に！",
  ui_story_5043_50431301_20_dialog_content = "この件ではすでに幾度となく法廷にご足労いただき、\n皆さんもさぞかしウンザリしていることでしょう。",
  ui_story_5043_50431301_21_dialog_content = "それにも関わらず、\n犯人の悪行を阻止できなかったことが残念でなりません。",
  ui_story_5043_50431301_22_dialog_content = "しかし、幸いなことに、\n今日その悪行に終止符が打たれます。",
  ui_story_5043_50431301_23_dialog_content = "それでは、宣言いたします――",
  ui_story_5043_50431301_24_dialog_content = "<color=#e8d9bb>カン――</color>",
  ui_story_5043_50431301_25_dialog_content = "「連続首なし彫像事件」、開廷！",
  ui_story_5043_50431301_26_dialog_content = "…",
  ui_story_5043_50431301_27_dialog_content = "…",
  ui_story_5043_50431301_28_dialog_content = "<size=30>ティナ、ライン、マシュー…</size>",
  ui_story_5043_50431301_29_dialog_content = "<size=30>信じるのよ。私たちにできるのはそれだけよ</size>",
  ui_story_5043_50431301_30_dialog_content = "まず初めに訴訟当事者とその他証人の情報確認を行います！",
  ui_story_5043_50431301_31_dialog_content = "原告、バイロン氏。",
  ui_story_5043_50431301_32_dialog_content = "被告、ティナ・キャンベル。",
  ui_story_5043_50431301_33_dialog_content = "ああ、実に残念です。\n恋愛訴訟部の裁判官が被告席に座ることになるとは…",
  ui_story_5043_50431301_34_dialog_content = "あやつ…",
  ui_story_5043_50431301_35_dialog_content = "本法廷は私シュワーベ・サラールが裁判長を務め――",
  ui_story_5043_50431301_36_dialog_content = "裁判官マシュー・サーイエとライン、\nおよび敬愛なる陪審員数名を加え、合議制による審理を行います。",
  ui_story_5043_50431301_37_dialog_content = "ふっ、若僧もようやく人を敬うことを知ったか。",
  ui_story_5043_50431301_38_dialog_content = "我々のような経験豊かな陪審員は、\n審理にとって大きな助けとなる。",
  ui_story_5043_50431301_39_dialog_content = "各位、この事件について、どう考えるかな？",
  ui_story_5043_50431301_40_dialog_content = "…",
  ui_story_5043_50431301_41_dialog_content = "…",
  ui_story_5043_50431301_42_dialog_content = "うむ。今は沈黙すべき時だな。",
  ui_story_5043_50431301_43_dialog_content = "本事件の概要はお配りした資料に書いてあります。\nご自由にご覧ください。",
  ui_story_5043_50431301_44_dialog_content = "十分な調査が行われたため、事件のいきさつはすでに明確です。",
  ui_story_5043_50431301_45_dialog_content = "続いて、「連続首なし彫像事件」の調査結果を\n簡単にご説明差し上げましょう。",
  ui_story_5043_50431301_46_dialog_content = "被告ティナ・キャンベルは自由恋愛の風潮に不満を抱き、\n彫像を破壊することによってその不満を示し、広めようとしました。",
  ui_story_5043_50431301_47_dialog_content = "最初の2つの事件においては、裁判官という立場を利用し、\n証拠を隠滅したため、痕跡を残すことはありませんでした。",
  ui_story_5043_50431301_48_dialog_content = "しかし、3回目の犯行ではバイロン氏が事前に通報したため、\nライン裁判官にも十分な準備があり…",
  ui_story_5043_50431301_49_dialog_content = "犯行現場で、その手から非常に重要な証拠品を入手することに\n成功しました。その証拠品というのが――",
  ui_story_5043_50431301_50_dialog_content = "この手袋です。",
  ui_story_5043_50431301_51_dialog_content = "見事である！犯人が誰かを示す直接の手がかりではないか！",
  ui_story_5043_50431301_52_dialog_content = "その通りです。そこで私はすぐに部下を調査に向かわせたところ、\nティナ裁判官のデスクの引き出しの中から、もう片方の手袋を見つけました。",
  ui_story_5043_50431301_53_dialog_content = "間違いなく一対の手袋だ！",
  ui_story_5043_50431301_54_dialog_content = "分析の結果、この2つの手袋は一対であり、\n同じ持ち主に属するものと判明しました。",
  ui_story_5043_50431301_55_dialog_content = "その持ち主が今被告席に座っているティナ・キャンベルです。",
  ui_story_5043_50431301_56_dialog_content = "私ではありません…",
  ui_story_5043_50431301_X56_dialog_content = "シュワーベ裁判長、見事だ！\n英雄とはやはり若き世代から輩出されるのだな！",
  ui_story_5043_50431301_57_dialog_content = "この証拠の示す事実に反論の余地はありません。\nしたがって、本法廷は被告を「器物損壊および恋愛妨害」罪に問います。",
  ui_story_5043_50431301_58_dialog_content = "もちろん、被告自身にも弁明が許されています。",
  ui_story_5043_50431301_59_dialog_content = "涙ながらに陪審員に訴えかけ、その演技が彼らの心に響き、\n無罪の票を投じてくれることを祈るとよいでしょう。",
  ui_story_5043_50431301_60_dialog_content = "あなたって人は…",
  ui_story_5043_50431301_61_dialog_content = "ありえん！",
  ui_story_5043_50431301_62_dialog_content = "この席に座った以上、\n我々が従うべき原則はただ一つ――公正である！",
  ui_story_5043_50431301_63_dialog_content = "そうであろう、各位？",
  ui_story_5043_50431301_64_dialog_content = "…",
  ui_story_5043_50431301_65_dialog_content = "…",
  ui_story_5043_50431301_66_dialog_content = "手袋については、私も何と説明すればよいのか分かりません…",
  ui_story_5043_50431301_67_dialog_content = "確かに私のものですが、\n事件当時私が付けていたものでは決してありません。",
  ui_story_5043_50431301_68_dialog_content = "あの時私は暗鬼と戦っていました。\n彫像に近づくことなどできません。",
  ui_story_5043_50431301_69_dialog_content = "現場にたどり着き、\n彫像を見た時にはすでに破壊されていたのです…",
  ui_story_5043_50431301_70_dialog_content = "それを証明できる人はいますか？",
  ui_story_5043_50431301_71_dialog_content = "それは…",
  ui_story_5043_50431301_72_dialog_content = "いいえ。あの時私は別行動だったので、\n今言ったことを証明できる方はおりませんわ…",
  ui_story_5043_50431301_73_dialog_content = "ならば、貴方の弁明は目下の結論を覆すには足りませんね。",
  ui_story_5043_50431301_74_dialog_content = "今ある証拠以上に有力な証拠を示すことができないのならば、\n貴方を「器物損壊および恋愛妨害」罪で…",
  ui_story_5043_50431301_75_dialog_content = "<size=45>待たれよ！！</size>",
  ui_story_5043_50431301_76_dialog_content = "…マシュー裁判官、どうされましたか？",
  ui_story_5043_50431301_77_dialog_content = "シュワーベ裁判長の裁決に異議を申し立てます！",
  ui_story_5043_50431301_78_dialog_content = "ティナは「連続首なし彫像事件」の犯人ではありませんぞ。\nアリバイがあるのですからな！",
  ui_story_5043_50431301_79_dialog_content = "ほう…アリバイですか？",
  ui_story_5043_50431301_80_dialog_content = "マシュー裁判官、詳しくお聞かせください。",
  ui_story_5043_50431301_81_dialog_content = "ただし、客観的に合理的にお話しくださいね。",
  ui_story_5043_50431301_82_dialog_content = "でなければ、共犯の存在を疑わずにはいられなくなります。",
  ui_story_5043_50431301_83_dialog_content = "オホン。まずは事件の始まりに戻るとしましょう。",
  ui_story_5043_50431301_84_dialog_content = "1つ目の「首なし彫像事件」が起こった時ですな。",
  ui_story_5043_50431301_85_dialog_content = "その日の犯人の動向については、私が調査済みです。",
  ui_story_5043_50431301_86_dialog_content = "残念ながら、被告にはアリバイはありませんでした。",
  ui_story_5043_50431301_87_dialog_content = "重要なのは事件発生当時ではなく、事件発生後ですぞ！",
  ui_story_5043_50431301_88_dialog_content = "あの日の午後、ティナは法廷で私と共に4時間仕事をしておりました。",
  ui_story_5043_50431301_89_dialog_content = "この点については、\n私だけでなく、他の同僚たちも証明できます。",
  ui_story_5043_50431301_90_dialog_content = "分かりました。4時間仕事をしていたのですね。\nですが…それが何だというのです？",
  ui_story_5043_50431301_91_dialog_content = "犯行後に法廷に戻り、仕事をすることは可能でしょう。",
  ui_story_5043_50431301_92_dialog_content = "いいえ！この4時間こそがアリバイそのものなのです！",
  ui_story_5043_50431301_93_dialog_content = "ティナが「眠り病」を患っていることは、\n白夜城のどの大病院でも証明可能な事実です。",
  ui_story_5043_50431301_94_dialog_content = "ティナは1日のうち、たった4時間しか起きていられないのです！",
  ui_story_5043_50431301_95_dialog_content = "…",
  ui_story_5043_50431301_96_dialog_content = "つまり、今証明した4時間の業務時間以外、\nティナは寝ていたということになるわけです！",
  ui_story_5043_50431301_97_dialog_content = "ティナに1つ目の彫像の破壊は不可能ですぞ！",
  ui_story_5043_50431301_98_dialog_content = "なんと！業務時間中に眠っていたと！？",
  ui_story_5043_50431301_99_dialog_content = "なんと恥知らずな！\n今やそんな怠け者でも給料を取れる時代なのか！？",
  ui_story_5043_50431301_100_dialog_content = "あ…そ、そうです！私はその時寝ていましたわ！",
  ui_story_5043_50431301_101_dialog_content = "目が覚めてから、「首なし彫像事件」のことを聞いたのです。",
  ui_story_5043_50431301_102_dialog_content = "いかがですかな？立派なアリバイでしょう！？",
  ui_story_5043_50431301_103_dialog_content = "貴方の弁論は成立しません。",
  ui_story_5043_50431301_104_dialog_content = "「推測」でアリバイを作ったにすぎないではありませんか。\n裁判官が「推測」に基づいて裁決を下すわけにはまいりません。",
  ui_story_5043_50431301_105_dialog_content = "事件発生時の証人でも物証でも構いません。\nいずれか一つでも示せるのであれば…",
  ui_story_5043_50431301_106_dialog_content = "分かりました！裁判長殿は証拠をお求めというわけですな。",
  ui_story_5043_50431301_107_dialog_content = "ならば、2つ目の「首なし彫像事件」を見てみましょう。",
  ui_story_5043_50431301_108_dialog_content = "2つ目の事件でも、被告には同様にアリバイがあります。",
  ui_story_5043_50431301_109_dialog_content = "私とラインが証人です。",
  ui_story_5043_50431301_110_dialog_content = "ふっ…証人というより…共犯ではありませんか？",
  ui_story_5043_50431301_111_dialog_content = "おやおや、どうやら裁判長殿は\n自身の部下である裁判官を信じられないようですな。",
  ui_story_5043_50431301_112_dialog_content = "構いませんぞ。他にも証人はおりますからな。",
  ui_story_5043_50431301_113_dialog_content = "しかも、その方の身分は実に信用に足るものですぞ。",
  ui_story_5043_50431301_114_dialog_content = "シュワーベ裁判長。もしや白夜城の姫君までも、\n共犯だとおっしゃりはせんでしょうな？",
  ui_story_5043_50431301_115_dialog_content = "…",
  ui_story_5043_50431301_116_dialog_content = "…姫君、ですと？",
  ui_story_5043_50431301_117_dialog_content = "2つ目の事件発生当時、\n我々はミッドタウンの緑の広場の混乱の只中にありました。",
  ui_story_5043_50431301_118_dialog_content = "…言いたいことは分かるわ。\nけれど混乱をおさめる方が先よ！",
  ui_story_5043_50431301_119_dialog_content = "皆さん、慌てずに私に付いてきてください！",
  ui_story_5043_50431301_120_dialog_content = "<color=#e8d9bb>パンッ――</color>",
  ui_story_5043_50431301_121_dialog_content = "（何の音だ！？）",
  ui_story_5043_50431301_122_dialog_content = "あの時、私が初めに彫像が破壊された音に気づきました。\nその後ティナ裁判官と調べに行ったのです。",
  ui_story_5043_50431301_123_dialog_content = "そして我々2人が同時に\n現場に残された首なしの彫像を目にしたのです。",
  ui_story_5043_50431301_124_dialog_content = "その間ティナ裁判官は終始私の視界の内におりましたぞ。\n完璧なアリバイです。",
  ui_story_5043_50431301_125_dialog_content = "この点はカレン殿下も修道女殿も証明できるはずです。",
  ui_story_5043_50431301_126_dialog_content = "その通りよ。\n事件が起こるまで、ティナと私たちはずっと一緒にいたわ。",
  ui_story_5043_50431301_127_dialog_content = "ティナが犯人のはずないわ。",
  ui_story_5043_50431301_128_dialog_content = "ええ、私もティナ裁判官のアリバイを証明いたします。",
  ui_story_5043_50431301_129_dialog_content = "どうですかな、シュワーベ裁判長？",
  ui_story_5043_50431301_130_dialog_content = "あなたの望まれた証人ですぞ？",
  ui_story_5043_50431301_131_dialog_content = "なるほど。分かりました。",
  ui_story_5043_50431301_132_dialog_content = "カレン殿下の証言とあらば、\n本法廷はもちろん尊重いたします。",
  ui_story_5043_50431301_133_dialog_content = "…ああ、もちろんカレン殿下だけではありませんよ。\nマシュー裁判官の熱意あふれる演説にも感動いたしました。",
  ui_story_5043_50431301_134_dialog_content = "おかげで、私が小さなミスを犯していたことに気づきました。\nティナ・キャンベルさん、貴方には濡れ衣を着せていたようです。",
  ui_story_5043_50431301_135_dialog_content = "（せ、成功したの？）",
  ui_story_5043_50431301_136_dialog_content = "よって、先程の裁決を撤回いたします。\nティナ・キャンベルは「連続首なし彫像事件」の犯人ではありません。",
  ui_story_5043_50431301_137_dialog_content = "被告は<color=#FFB400>3件目</color>の「首なし彫像事件」の犯人です。",
  ui_story_5043_50431301_138_dialog_content = "えっ…",
  ui_story_5043_50431301_139_dialog_content = "チッ。",
  ui_story_5043_50431301_140_dialog_content = "マシュー裁判官、努力したかいがあったではありませんか！\n貴方のおかげで処罰は大幅に軽くなることでしょう！",
  ui_story_5043_50431301_141_dialog_content = "しかし、です！彼女が3つ目の事件の犯人である限り…\n核心となっている証拠の信ぴょう性が覆されない限り…",
  ui_story_5043_50431301_142_dialog_content = "本法廷はティナ・キャンベルを「器物損壊および恋愛妨害」罪に問います！",
  ui_story_5043_50431301_143_dialog_content = "この点はマシュー裁判官もご賛同いただけますね？",
  ui_story_5043_50431301_144_dialog_content = "フン、屁理屈屋め…",
  ui_story_5043_50431301_145_dialog_content = "それとも、本件の核心となる証拠品に\nまだ異議を唱えるおつもりですか？",
  ui_story_5043_50431301_146_dialog_content = "…",
  ui_story_5043_50431301_147_dialog_content = "<size=30>マシュー…頑張って…！</size>",
  ui_story_5043_50431301_148_dialog_content = "<size=30>私たちの証言だけでは…</size>",
  ui_story_5043_50431301_149_dialog_content = "いいえ。私の弁論は以上です。",
  ui_story_5043_50431301_150_dialog_content = "え…？",
  ui_story_5043_50431301_151_dialog_content = "ふふ、「以上」でよろしいですか？",
  ui_story_5043_50431301_152_dialog_content = "ええ。",
  ui_story_5043_50431301_153_dialog_content = "ならば…",
  ui_story_5043_50431301_154_dialog_content = "ライン、選手交代だ。",
  ui_story_5043_50431301_155_dialog_content = "！！！",
  ui_story_5043_50431301_156_dialog_content = "ラインですと？",
  ui_story_5043_50431301_157_dialog_content = "おい、新人、腕の見せ所だ。\n気を張っていくがいい。",
  ui_story_5043_50431301_158_dialog_content = "はい。",
  ui_story_5043_50431301_159_dialog_content = "シュワーベ裁判長、陪審員の皆さま、\nおよび傍聴席の皆さま。",
  ui_story_5043_50431301_160_dialog_content = "私に数分間くださいませんか。",
  ui_story_5043_50431301_161_dialog_content = "一緒に<color=#FFB400>推理</color>をしてみようではありませんか。",
  ui_story_5043_50431301_162_dialog_content = "ほほう。若僧がなかなかやる気ではないか。",
  ui_story_5043_50431301_163_dialog_content = "ライン裁判官。庶民出身であることをお忘れになってはいけませんよ。\n自身の言動には気を付けなければ。",
  ui_story_5043_50431301_164_dialog_content = "何かミスを犯せば、貴方にはマシュー裁判官のように\n後ろ盾になってくれる一族がいないのですから。",
  ui_story_5043_50431301_165_dialog_content = "シュワーベ裁判長。庶民出身であるからといって、\nマイナス面ばかりとは限りません。",
  ui_story_5043_50431301_166_dialog_content = "少なくとも、私のミスで一族が巻き添えになることはありませんから。",
  ui_story_5043_50431301_167_dialog_content = "クッ…",
  ui_story_5043_50431301_168_dialog_content = "シュワーベ裁判長は核心的な証拠と3件目の事件を\n非常に気に掛けていらっしゃるようですね。",
  ui_story_5043_50431301_169_dialog_content = "ならば、改めてこの事件を詳しく振り返り、\n最初から整理してみることにしましょう。",
  ui_story_5043_50431301_170_dialog_content = "細部に注目し、犯人も見落としていた、\nわずかな手がかりを見つけていくのです。",
  ui_story_5043_50431301_171_dialog_content = "素晴らしい！実に専門性が高いではないか！\n専門的な推理こそ吾輩の望む法廷の姿だ！",
  ui_story_5043_50431301_172_dialog_content = "（犯人も見落としていたわずかな手がかりって…）",
  ui_story_5043_50431301_173_dialog_content = "（ライン…本当に見つけたの？）",
  ui_story_5043_50431301_174_dialog_content = "まずは昨日、事件が起こる前の千星の階段へと\n戻ってみましょう。",
  ui_story_5043_50431301_175_dialog_content = "千星の階段の上にある彫像を守るため、\n私たちはパレード隊の行進を止めようと試みました。",
  ui_story_5043_50431301_176_dialog_content = "ところが、思いもよらぬことに、\nパレード隊の最後尾に突然暗鬼が出現したのです。",
  ui_story_5043_50431301_177_dialog_content = "私はすぐに戦闘を開始しました。\nいくらも経たないうちに、ティナが駆け付けました…",
  ui_story_5043_50431302_1_dialog_content = "残り3匹となり、私はまずそのうちの1匹を\n階段から蹴り落としました。",
  ui_story_5043_50431302_2_dialog_content = "続いて、もう1匹を旋槍で突き倒しました。",
  ui_story_5043_50431302_3_dialog_content = "そして最後の一匹をティナが一発でたたき砕いたのです。",
  ui_story_5043_50431302_4_dialog_content = "もうよい。そこまで細かく振り返る必要があるか？",
  ui_story_5043_50431302_5_dialog_content = "目の前の数匹の暗鬼をすべて片づけた後、\n私とティナは彫像のある所へと戻り、皆さんと合流しました。",
  ui_story_5043_50431302_6_dialog_content = "ですが、人混みを抜けなければならず、\n進むのは大変でした。",
  ui_story_5043_50431302_7_dialog_content = "その途中でティナとは離ればなれになってしまい、\n次にティナに会ったのは事件が起こった後でした。",
  ui_story_5043_50431302_8_dialog_content = "ええ、その通りです。人混みの中を進むのは大変でしたわ。\n押されてなかなか進めませんでしたの…",
  ui_story_5043_50431302_9_dialog_content = "その点は私の理解と一致していますね。",
  ui_story_5043_50431302_10_dialog_content = "この3件目の事件では、\nティナ・キャンベルにアリバイがありません。",
  ui_story_5043_50431302_11_dialog_content = "アリバイの件はひとまず置いておきましょう。\n続いて事件の起こった時刻に戻りましょう。",
  ui_story_5043_50431302_12_dialog_content = "私が彫像の所へ戻ると、また他の暗鬼が襲ってきました。",
  ui_story_5043_50431302_13_dialog_content = "私たちは彫像の周囲で暗鬼と戦ったため、\n犯人に犯行に及ぶ隙を与えてしまいました。",
  ui_story_5043_50431302_14_dialog_content = "犯人は戦闘中の混乱を利用し、\nひそかに手を伸ばし、彫像の頭部を破壊したのです。",
  ui_story_5043_50431302_15_dialog_content = "私はその手をつかみましたが、犯人は暗鬼の中に紛れ込んでいて、\n容貌や体形の特徴を見分けることはできませんでした。",
  ui_story_5043_50431302_16_dialog_content = "そして犯人も手袋だけを残して、\n素早く私の手から逃げ出しました。",
  ui_story_5043_50431302_17_dialog_content = "ええ、それこそ本件の核心的手がかりとなった手袋です。",
  ui_story_5043_50431302_18_dialog_content = "カレン殿下とマシュー裁判官はすぐに周りの暗鬼を倒しましたが、\nそうして開けた広場には犯人の姿はありませんでした。",
  ui_story_5043_50431302_19_dialog_content = "ティナ裁判官が戻ってきたのは、その後です。",
  ui_story_5043_50431302_20_dialog_content = "以上がこの事件の全過程です。",
  ui_story_5043_50431302_21_dialog_content = "実に素晴らしいですね。\nライン裁判官は客観的事実のみをお話しになりました。",
  ui_story_5043_50431302_22_dialog_content = "おかげで、この後の推理がとても合理的に進められますね。\n手袋を手がかりに調べていけば、犯人が見つかる、というわけです。",
  ui_story_5043_50431302_23_dialog_content = "私たちはまさにその方法で被告を逮捕したのですよ。",
  ui_story_5043_50431302_24_dialog_content = "いいえ、裁判長の推理はあまりにも短絡的です。",
  ui_story_5043_50431302_25_dialog_content = "ほう？",
  ui_story_5043_50431302_26_dialog_content = "犯行現場で得られた犯人の情報はこうです――",
  ui_story_5043_50431302_27_dialog_content = "「証拠品となった手袋をはめ、素手で彫像を壊した」。",
  ui_story_5043_50431302_28_dialog_content = "一方、裁判長の捕らえた被告の特徴は――",
  ui_story_5043_50431302_29_dialog_content = "「証拠品たる手袋の法律上の所有者である若い女性」です。",
  ui_story_5043_50431302_30_dialog_content = "厳密には、両者をまったく同等と見なすことはできません。",
  ui_story_5043_50431302_31_dialog_content = "重箱の隅をつついて何の意味があるのですか？",
  ui_story_5043_50431302_32_dialog_content = "手袋の所有者こそ現場でそれをはめていた可能性が最も高いのですよ。\n何の問題があるというのです？",
  ui_story_5043_50431302_33_dialog_content = "もちろん問題はありません。\n問題は私の発言の後半にあるのです。",
  ui_story_5043_50431302_34_dialog_content = "ティナ裁判官は素手で彫像を壊せるでしょうか？",
  ui_story_5043_50431302_35_dialog_content = "おお！新たな視点だ！",
  ui_story_5043_50431302_36_dialog_content = "よく考えてみれば、いかにもその通りだ。\nうら若き女性が素手で彫像を壊せるはずあるまい。",
  ui_story_5043_50431302_37_dialog_content = "ライン裁判官、考えすぎて頭が煮詰まってしまったのではありませんか？",
  ui_story_5043_50431302_38_dialog_content = "2分前の自分の発言を思い出してください。",
  ui_story_5043_50431302_39_dialog_content = "残り3匹となり、私はまずそのうちの1匹を\n階段から蹴り落としました。",
  ui_story_5043_50431302_40_dialog_content = "続いて、もう1匹を旋槍で突き倒しました。",
  ui_story_5043_50431302_41_dialog_content = "そして最後の一匹をティナが<color=#FFB400>一発でたたき砕いたのです</color>。",
  ui_story_5043_50431302_42_dialog_content = "同僚のことをよくご存じないようですね？\nティナ裁判官は「神の手」を受け継ぐキャンベル家の者ですよ。",
  ui_story_5043_50431302_43_dialog_content = "暗鬼さえもいとも簡単に砕くことができるのです。\n彫像などたやすいことでしょう。",
  ui_story_5043_50431302_44_dialog_content = "そうであった！ティナはただのうら若き女性ではなかった！",
  ui_story_5043_50431302_45_dialog_content = "若者よ、お主の推理はまだ深みが足りんようだな。",
  ui_story_5043_50431302_46_dialog_content = "（このままじゃ…ただのこじつけになっちゃう）",
  ui_story_5043_50431302_47_dialog_content = "（ライン、何かもっと犯人も見逃してるボロはないの…？）",
  ui_story_5043_50431302_48_dialog_content = "ええ、その通りです。\nティナは「神の手」を受け継いでいます。",
  ui_story_5043_50431302_49_dialog_content = "つまり、ティナは「神の手」で彫像を壊した、\nそう考えていらっしゃるのですね？",
  ui_story_5043_50431302_50_dialog_content = "そうですよ。それが唯一正しい結論でしょう？",
  ui_story_5043_50431302_51_dialog_content = "ライン裁判官、とても緻密な思考力を持っていますね。\n賞賛に値しますよ。",
  ui_story_5043_50431302_52_dialog_content = "ですが、こうした内容は今後個人的にお話しください。\n法廷では大勢の方の時間を無駄にしてしまいますから。",
  ui_story_5043_50431302_53_dialog_content = "いいえ、どなたの時間も無駄にはしていませんよ。",
  ui_story_5043_50431302_54_dialog_content = "私が申し上げた推理はすべて、\n今裁判長もお認めになった――",
  ui_story_5043_50431302_55_dialog_content = "「ティナは神の手で彫像を壊した」という結論を\n引き出すためのものなのですから。",
  ui_story_5043_50431302_56_dialog_content = "…回りくどいことはやめてください。\nいったい何を言いたいのです？",
  ui_story_5043_50431302_57_dialog_content = "結論が出たところで、もう一度振り返ってみると、\nある事実が明らかになります。",
  ui_story_5043_50431302_58_dialog_content = "ティナを被告席に座らせた手袋こそ、\n彼女が無罪だという動かぬ証拠なのです！",
  ui_story_5043_50431302_59_dialog_content = "何ですと！？",
  ui_story_5043_50431302_60_dialog_content = "本件の最重要証拠品である、犯人が犯行時につけていた手袋を\nここにいる皆さんに示すことをお許しください。",
  ui_story_5043_50431302_61_dialog_content = "シュワーベ裁判長が保管していた間に\n何かの痕跡が消されている可能性はありますが…",
  ui_story_5043_50431302_62_dialog_content = "さすがに手袋そのものをすり替えることはしていないでしょう？",
  ui_story_5043_50431302_63_dialog_content = "証拠品を守るのは法廷の最も基本的な責任です。\n貴方は法廷を侮辱するおつもりですか？",
  ui_story_5043_50431302_64_dialog_content = "それならば安心いたしました。",
  ui_story_5043_50431302_65_dialog_content = "では皆さん。この手袋をよくご覧ください。",
  ui_story_5043_50431302_66_dialog_content = "これは…右手にはめる手袋で間違いありませんね？",
  ui_story_5043_50431302_67_dialog_content = "余計なことは言わなくて結構です！\n要点だけをお話しください！",
  ui_story_5043_50431302_68_dialog_content = "どちらの手にはめるものかなど…",
  ui_story_5043_50431302_69_dialog_content = "！！！",
  ui_story_5043_50431302_70_dialog_content = "え？",
  ui_story_5043_50431302_71_dialog_content = "あ――！",
  ui_story_5043_50431302_72_dialog_content = "右手…！？そういうことだったのね！",
  ui_story_5043_50431302_73_dialog_content = "どういうこと！？それがどうしたの？",
  ui_story_5043_50431302_74_dialog_content = "どうやらお分かりになったようですね。シュワーベ裁判長。",
  ui_story_5043_50431302_75_dialog_content = "どうあってもごまかしようのない、\n致命的なミスです。",
  ui_story_5043_50431302_76_dialog_content = "彫像を破壊することのできる「神の手」は、\n<color=#FFB400>左手</color>なのですから。",
  ui_story_5043_50431302_77_dialog_content = "しかし、この手袋は<color=#FFB400>右手</color>にはめるものです！",
  ui_story_5043_50431302_78_dialog_content = "あ！！そういうことだったんだね！",
  ui_story_5043_50431302_79_dialog_content = "左手が神の手…右手は…",
  ui_story_5043_50431302_80_dialog_content = "あなたは終始法廷で、\n事件解決の核心たるこの証拠品の重要性を強調していました。",
  ui_story_5043_50431302_81_dialog_content = "ならば、私たちも証拠を何よりも重視しなければなりません。",
  ui_story_5043_50431302_82_dialog_content = "「神の手」と反対側の手にはめる手袋が証拠品として導き出すのは、\nいったいどのような結論でしょうか？",
  ui_story_5043_50431302_83_dialog_content = "さあ、シュワーベ裁判長。\n皆さんに教えて差し上げてください。",
  ui_story_5043_50431302_84_dialog_content = "お…お前…",
  ui_story_5043_50431302_85_dialog_content = "罪を問う証拠品と罪を晴らす証拠品がまったく同じものだなんて！\nすごいよ、ライン！",
  ui_story_5043_50431302_86_dialog_content = "これでようやく僕たちに有利になったね！",
  ui_story_5043_50431302_87_dialog_content = "まさか、こんなところで足をすくわれるとは…",
  ui_story_5043_50431302_88_dialog_content = "よいでしょう。貴方たちのき弁にも\nそれなりに筋が通っていることは認めましょう。",
  ui_story_5043_50431302_89_dialog_content = "どうやら、この証拠品では\nティナ・キャンベルの罪を問うことはできないようです。",
  ui_story_5043_50431302_90_dialog_content = "「連続首なし彫像事件」の容疑者は再び謎となりました。",
  ui_story_5043_50431302_91_dialog_content = "よかった！！！",
  ui_story_5043_50431302_92_dialog_content = "カレン、成功だよ！",
  ui_story_5043_50431302_93_dialog_content = "ええ！本当によかったわ！",
  ui_story_5043_50431302_94_dialog_content = "白夜城の公正さを法廷で確かめられたことを光栄に思うわ！",
  ui_story_5043_50431302_95_dialog_content = "「容疑者は再び謎となった」…つまり…",
  ui_story_5043_50431302_96_dialog_content = "私の罪は晴れた、ということですね！",
  ui_story_5043_50431302_97_dialog_content = "当然ですよ。あなたは最初から潔白なのですから。",
  ui_story_5043_50431302_98_dialog_content = "我々に感謝することだな。\n特に新人の庶民にな。",
  ui_story_5043_50431302_99_dialog_content = "初めて大舞台に立ったわりには、\nなかなかの出来であったわ。",
  ui_story_5043_50431302_100_dialog_content = "ええ！もちろん、皆さんに感謝していますわ！",
  ui_story_5043_50431302_101_dialog_content = "私は素晴らしい同僚を恵まれましたわ！",
  ui_story_5043_50431302_102_dialog_content = "おいっ！どうなっているのだ！？",
  ui_story_5043_50431302_103_dialog_content = "これだけ大騒ぎしておきながら、\n結局解決できんというのか？",
  ui_story_5043_50431302_104_dialog_content = "…",
  ui_story_5043_50431302_105_dialog_content = "なんたることだ！",
  ui_story_5043_50431302_106_dialog_content = "こんな所で長々と偉そうな演説を聞かされた上に、\n結局また振り出しに戻っただと！？",
  ui_story_5043_50431302_107_dialog_content = "言っただろう！私の我慢にも限度がある！",
  ui_story_5043_50431302_108_dialog_content = "もし今日事件に終止符を打てないのなら、\nお前たち恋愛法廷に終止符を打ってやる！！",
  ui_story_5043_50431302_109_dialog_content = "原告、落ち着いてください。\n今日の法廷はまだ折り返し地点に来たばかりです。",
  ui_story_5043_50431302_110_dialog_content = "折り返し地点だと？",
  ui_story_5043_50431302_111_dialog_content = "ティナ、こちらへお戻りください。",
  ui_story_5043_50431302_112_dialog_content = "続いて、被告席には別の方に座っていただきます。",
  ui_story_5043_50431302_113_dialog_content = "え？別の方とは…？",
  ui_story_5043_50431302_114_dialog_content = "恋愛訴訟部による厳密な調査と収集した証拠に基づき、\n本法廷の裁判官であるラインと――",
  ui_story_5043_50431302_115_dialog_content = "裁判官マシューは――",
  ui_story_5043_50431302_116_dialog_content = "「器物損壊、恋愛妨害」の罪でシュワーベ・サラール氏を訴えます。",
  ui_story_5043_50431302_117_dialog_content = "裁判長、こちらの席へお移りください。",
  ui_story_5043_50431302_118_dialog_content = "何ですって？シュワーベを訴える！？",
  ui_story_5043_50431302_119_dialog_content = "PlayerName、これも計画の内なの？",
  ui_story_5043_50431302_120_dialog_content = "いや…",
  ui_story_5043_50431302_121_dialog_content = "昨日僕たちは確かにシュワーベを疑ってたけど…",
  ui_story_5043_50431302_122_dialog_content = "訴えるとまでは知らなかった…",
  ui_story_5043_50431302_123_dialog_content = "決定的な証拠はつかんだの？",
  ui_story_5043_50431302_124_dialog_content = "いや、まったく…",
  ui_story_5043_50431302_125_dialog_content = "私を訴えると？",
  ui_story_5043_50431302_126_dialog_content = "ライン裁判官。自分の言っている言葉の意味がお分かりですか？",
  ui_story_5043_50431302_127_dialog_content = "私は自身の職務を全うしているだけです。",
  ui_story_5043_50431302_128_dialog_content = "フン、本当に全うできるといいですがね。",
  ui_story_5043_50431302_129_dialog_content = "先に教えてあげましょう。\n3つの事件発生時、私には疑いようのないアリバイがあります。",
  ui_story_5043_50431302_130_dialog_content = "調べればすぐに分かることです。\n法廷の者なら誰でも証言できますよ。",
  ui_story_5043_50431302_131_dialog_content = "こんなバカげた難癖をつけられては、\n弁解する気さえ起こりませんがね。",
  ui_story_5043_50431302_132_dialog_content = "シュワーベ裁判長、安心してください。\n調査はもちろん実施します。",
  ui_story_5043_50431302_133_dialog_content = "あなたのおっしゃったことも確かにその通りです。\n3つの事件発生時、あなたにはアリバイがあります。",
  ui_story_5043_50431302_134_dialog_content = "ならばなぜ起訴を撤回しないのですか？",
  ui_story_5043_50431302_135_dialog_content = "ですが、犯行は犯人本人がその場に赴かなければできないとは限りません。",
  ui_story_5043_50431302_136_dialog_content = "証人をお呼びしてもよろしいでしょうか？",
  ui_story_5043_50431302_137_dialog_content = "証人？",
  ui_story_5043_50431302_138_dialog_content = "証人に証言をしていただきます。",
  ui_story_5043_50431302_139_dialog_content = "（いつ証人なんて呼んだんだろう？）",
  ui_story_5043_50431302_140_dialog_content = "（証人って…いったい誰だろう…？）",
  ui_story_5043_50431302_141_dialog_content = "あ、あの…",
  ui_story_5043_50431302_142_dialog_content = "話していいですか？",
  ui_story_5043_50431302_143_dialog_content = "暗鬼ではないか！しかも言葉を話しているぞ！？",
  ui_story_5043_50431302_144_dialog_content = "ボ、ボーン！！",
  ui_story_5043_50431302_145_dialog_content = "あ！！どうして！？",
  ui_story_5043_50431302_146_dialog_content = "暗鬼を証言台に？いったいどういうことなの…？",
  ui_story_5043_50431302_147_dialog_content = "貴方は頭がどうかしてしまったのですか？\nそのような汚らわしい者を法廷に連れ込むとは！！",
  ui_story_5043_50431302_148_dialog_content = "法廷の秩序を乱すおつもりですか？",
  ui_story_5043_50431302_149_dialog_content = "ご安心ください。\n私たちを襲うことはないと確認したうえで連れてきました。",
  ui_story_5043_50431302_150_dialog_content = "誰一人として襲われることはありません。\nこの暗鬼は真実を明らかにするためだけに証言台に立っているのです。",
  ui_story_5043_50431302_151_dialog_content = "ここにいる誰一人として、\n真実を拒みはしないでしょう？",
  ui_story_5043_50431302_152_dialog_content = "ううむ、そうであれば、証言を聞いてみるのも悪くはない。",
  ui_story_5043_50431302_153_dialog_content = "ボーン…前に会った時より痩せてしまったようですわ…",
  ui_story_5043_50431302_154_dialog_content = "これだけ特別な証人が出て来たってことは、\nきっと驚くべき証言が聞けるんだろうね…",
  ui_story_5043_50431302_155_dialog_content = "ま、まず自己紹介します。",
  ui_story_5043_50431302_156_dialog_content = "みなさん、こわがらないで。",
  ui_story_5043_50431302_157_dialog_content = "僕はもともと、ごく普通の低級暗鬼でした。",
  ui_story_5043_50431302_158_dialog_content = "カナン城でうっかり何かの実験道具をのみ込んでしまいました。",
  ui_story_5043_50431302_159_dialog_content = "それが何だったのかはわかりません…",
  ui_story_5043_50431302_160_dialog_content = "その後見た目が変わって、はっきりした意識も生まれました。",
  ui_story_5043_50431302_161_dialog_content = "チッ、どうやら啓光の奴らがまた何かを発明したようだな！",
  ui_story_5043_50431302_162_dialog_content = "一度にあれだけ長く言葉を話せるなんて、\n公用語も上達してるみたいだ…",
  ui_story_5043_50431302_163_dialog_content = "ほかの暗鬼とのつながりも弱くなっていきました。",
  ui_story_5043_50431302_164_dialog_content = "ほかの暗鬼は僕をコントロールできません。\n僕も暗鬼をコントロールできません。",
  ui_story_5043_50431302_165_dialog_content = "暗鬼の中ではいつも失敗ばかりで…\n与えられた仕事をこなせませんでした…",
  ui_story_5043_50431302_166_dialog_content = "ボスの堪忍袋の緒が切れて、結局追い出されました…",
  ui_story_5043_50431302_167_dialog_content = "どうせ迷惑を掛けるなら、\n光霊に迷惑を掛けろって言われました…",
  ui_story_5043_50431302_168_dialog_content = "うーん…暗鬼も仲間にいじめられることがあるんだね…",
  ui_story_5043_50431302_169_dialog_content = "同情してはダメよ。敵の敵は味方とは限らないわ。",
  ui_story_5043_50431302_170_dialog_content = "その後、僕は光霊の言葉と文化を学び始めました。",
  ui_story_5043_50431302_171_dialog_content = "生きるためにいろんなところではたらきました。\nいつもすぐにクビになっちゃったけど…",
  ui_story_5043_50431302_172_dialog_content = "生活はたいへんです。でも前に比べたらずっと楽しいです。",
  ui_story_5043_50431302_173_dialog_content = "僕は誰も傷つけません。",
  ui_story_5043_50431302_174_dialog_content = "ぼ、僕は…光霊の暮らしが好きです！",
  ui_story_5043_50431302_X174_dialog_content = "もう嫌われたくありません！",
  ui_story_5043_50431302_175_dialog_content = "そうですよ！ボーンが皆さんを傷つけたりするはずありません！",
  ui_story_5043_50431302_176_dialog_content = "その辺の光霊よりずっと善良で可愛いのです！\nだから、皆さん安心してください！",
  ui_story_5043_50431302_177_dialog_content = "これはこれは…暗鬼が光霊と同じように暮らすとは…",
  ui_story_5043_50431302_178_dialog_content = "時代は変わったものだな。",
  ui_story_5043_50431302_179_dialog_content = "自己紹介はそのくらいで結構ですよ。",
  ui_story_5043_50431302_180_dialog_content = "あなたは何を証言するために法廷にいらしたのですか？",
  ui_story_5043_50431302_181_dialog_content = "あ、ある光霊の悪行を話すためです。",
  ui_story_5043_50431302_182_dialog_content = "誰の悪行ですか？",
  ui_story_5043_50431302_183_dialog_content = "一番高い所に座っている、\nあの、シュワーベって名前の人です！",
  ui_story_5043_50431302_184_dialog_content = "クッ…",
  ui_story_5043_50431302_185_dialog_content = "どのような悪行ですか？",
  ui_story_5043_50431302_186_dialog_content = "あ、あの人が彫像をこわした犯人です！",
  ui_story_5043_50431302_187_dialog_content = "ですが、彼にはアリバイがあります。\n何を証拠におっしゃっているのですか？",
  ui_story_5043_50431302_188_dialog_content = "あの人はその場にいる必要ないんです。\nだって、彫像は…彫像は…",
  ui_story_5043_50431302_189_dialog_content = "彫像は、どうしたのです？",
  ui_story_5043_50431302_190_dialog_content = "暗鬼を操ってこわしたからです！！",
  ui_story_5043_50431401_1_dialog_content = "暗鬼を操る！？",
  ui_story_5043_50431401_2_dialog_content = "ああ、なんたることだ！\n自分の言っていることが分かっておるのか？",
  ui_story_5043_50431401_3_dialog_content = "暗鬼と結託するなど大罪であるぞ！",
  ui_story_5043_50431401_4_dialog_content = "笑止千万もいいところです！",
  ui_story_5043_50431401_5_dialog_content = "暗鬼ごときの一方的な証言で、白夜城貴族である私に\n暗鬼と結託したなどという汚名を着せようというのですか？",
  ui_story_5043_50431401_6_dialog_content = "まったくバカげています！\n酔っぱらいの寝言の方がまだ信用できるというものです！",
  ui_story_5043_50431401_7_dialog_content = "ライン、濡れ衣を着せるにしても、\nもう少し上品なやり方にしていただきたいですね！",
  ui_story_5043_50431401_8_dialog_content = "そうですか。では、あなたと同じことをしましょうか？",
  ui_story_5043_50431401_9_dialog_content = "何ですと…？",
  ui_story_5043_50431401_10_dialog_content = "あなたの罪を問うのに、濡れ衣など必要ありません。",
  ui_story_5043_50431401_11_dialog_content = "今ご自身でおっしゃったように、\n暗鬼の証言一つで有罪とするわけにはいきません。",
  ui_story_5043_50431401_12_dialog_content = "ですが、もしこの暗鬼が事件の中で\n特殊な役割を担っていたとしたら、どうでしょうか？",
  ui_story_5043_50431401_13_dialog_content = "…特殊な役割！？",
  ui_story_5043_50431401_14_dialog_content = "証人、お願いします。",
  ui_story_5043_50431401_15_dialog_content = "す、すみません！！",
  ui_story_5043_50431401_16_dialog_content = "僕は悪いことをしました。罪を認めます！",
  ui_story_5043_50431401_17_dialog_content = "えっ？",
  ui_story_5043_50431401_18_dialog_content = "そんなはずありません。ボーンは悪いことなどしません！",
  ui_story_5043_50431401_19_dialog_content = "いったい何をしたいのだ？先程まで他人を訴えておきながら、\n今度は自分の罪を認めると？",
  ui_story_5043_50431401_20_dialog_content = "よく考えてから発言せい！",
  ui_story_5043_50431401_21_dialog_content = "す、すみません。実は…僕が…",
  ui_story_5043_50431401_22_dialog_content = "僕が彫像をこわした犯人なんです！",
  ui_story_5043_50431401_23_dialog_content = "え！？",
  ui_story_5043_50431401_24_dialog_content = "なに？おぬしが犯人だと？",
  ui_story_5043_50431401_25_dialog_content = "おぬしが残酷にも私の「妻」と「恋する女性」を壊したのか！？",
  ui_story_5043_50431401_26_dialog_content = "はい、僕がやりました。",
  ui_story_5043_50431401_27_dialog_content = "この…悪党めが！",
  ui_story_5043_50431401_28_dialog_content = "で、でも…僕はムリヤリやらされたんです！",
  ui_story_5043_50431401_29_dialog_content = "全部シュワーベがやらせたんです！",
  ui_story_5043_50431401_30_dialog_content = "みなさん、お願いです。バツを軽くしてください――",
  ui_story_5043_50431401_31_dialog_content = "<size=45>なにぃ！？/何ですって！？/何だって！？</size>",
  ui_story_5043_50431401_32_dialog_content = "…",
  ui_story_5043_50431401_33_dialog_content = "そういうことだったのか…",
  ui_story_5043_50431401_34_dialog_content = "は、半月前のことです。",
  ui_story_5043_50431401_35_dialog_content = "僕は白夜城で、あ、新しい仕事をさがしてました。",
  ui_story_5043_50431401_36_dialog_content = "白夜城は広くて、道も分からなくて、\nいつの間にか夜になってました。",
  ui_story_5043_50431401_37_dialog_content = "そしたら…突然ミッドタウンで暗鬼に会ったんです。",
  ui_story_5043_50431401_38_dialog_content = "ううむ。確かに最近城内で何度か暗鬼の姿が\n確認されていたな。",
  ui_story_5043_50431401_39_dialog_content = "しかるべき措置を取らねばなるまい。",
  ui_story_5043_50431401_40_dialog_content = "ま、まさか白夜城で同族に会うとは思いませんでした。\n少し不思議に思いました。",
  ui_story_5043_50431401_41_dialog_content = "びっくりしていたら、その暗鬼たちは\n僕を道に迷った暗鬼だとカン違いしました。",
  ui_story_5043_50431401_42_dialog_content = "すごく強引で、僕を引きずって列にムリヤリ入れたんです。",
  ui_story_5043_50431401_43_dialog_content = "わけがわからないまま後をついて歩いて、\n最後に…",
  ui_story_5043_50431401_44_dialog_content = "サラール荘園に着きました。",
  ui_story_5043_50431401_45_dialog_content = "え！そこってシュワーベの家でしょ！？",
  ui_story_5043_50431401_46_dialog_content = "はい。そこでシュワーベを見ました。",
  ui_story_5043_50431401_47_dialog_content = "そ、それから、びっくりする光景も…",
  ui_story_5043_50431401_48_dialog_content = "あの人は奴隷みたいに暗鬼をこき使っていました。",
  ui_story_5043_50431401_49_dialog_content = "暗鬼もみんな、言うことを聞いてました。",
  ui_story_5043_50431401_50_dialog_content = "ぼ、僕は逃げ出すチャンスがなくて、\n仲間のフリをしていました。",
  ui_story_5043_50431401_51_dialog_content = "そ、それから、ほかの暗鬼と一緒に、\nち、地下室に閉じ込められました。",
  ui_story_5043_50431401_52_dialog_content = "地下室だって！？",
  ui_story_5043_50431401_53_dialog_content = "地下室は暗鬼を閉じ込めておく場所だったのか。\nどうりで…",
  ui_story_5043_50431401_54_dialog_content = "シュワーベの家の地下室を知っているの？",
  ui_story_5043_50431401_55_dialog_content = "…うーん、そのことは法廷で話すにはちょっと…",
  ui_story_5043_50431401_56_dialog_content = "あとでこっそり話すね！",
  ui_story_5043_50431401_57_dialog_content = "<size=45>デタラメです！</size>",
  ui_story_5043_50431401_58_dialog_content = "何とバカげた証言でしょう！童話か何かの受け売りですか？",
  ui_story_5043_50431401_59_dialog_content = "法廷でこの私がこのような濡れ衣を着せられるとは何たることでしょう！",
  ui_story_5043_50431401_60_dialog_content = "濡れ衣かどうかはすぐに分かります。",
  ui_story_5043_50431401_61_dialog_content = "証人、その後何がありましたか？",
  ui_story_5043_50431401_62_dialog_content = "今のお話は確かに驚くべき事実でしたが、\n目下「連続首なし彫像事件」とは関係がありません。",
  ui_story_5043_50431401_63_dialog_content = "あ、そうでした！事件の話に戻ります！",
  ui_story_5043_50431401_64_dialog_content = "時どき、シュワーベは暗鬼を何匹か連れて地下室を出ていき、\n任務を与えます。",
  ui_story_5043_50431401_65_dialog_content = "ぼ、僕は逃げ出すチャンスがほしくて、\nいつも積極的にふるまいました。",
  ui_story_5043_50431401_66_dialog_content = "思った通り選ばれました。",
  ui_story_5043_50431401_67_dialog_content = "月の気球が上がったら、\nそ、その下にある彫像をこわせと言われました。",
  ui_story_5043_50431401_68_dialog_content = "おお！今回の事件の規則性と一致しているぞ！",
  ui_story_5043_50431401_69_dialog_content = "は、初めの2回は法廷の前と緑の広場で、\n彫像をこわしました。",
  ui_story_5043_50431401_70_dialog_content = "法廷の前だと！？",
  ui_story_5043_50431401_71_dialog_content = "ああ――私の「恋焦がれる人」よ！！",
  ui_story_5043_50431401_72_dialog_content = "バイロンさん、お悔み申し上げます。",
  ui_story_5043_50431401_73_dialog_content = "僕がうまくやるからなのか、\n3回目は任務がむずかしくなりました。",
  ui_story_5043_50431401_74_dialog_content = "お、おかしな手袋をはめて、\n彫像をこわすように言われました。",
  ui_story_5043_50431401_75_dialog_content = "手袋だって！？",
  ui_story_5043_50431401_76_dialog_content = "こわした後、手袋をその場に残していけとも言われました。",
  ui_story_5043_50431401_77_dialog_content = "それで、ぼ、僕はほかの暗鬼の中に混じって、\n千星の階段へ行きました。",
  ui_story_5043_50431401_78_dialog_content = "任務中、右手をライン裁判官につかまれて、\nもう少しでつかまりそうになりました。",
  ui_story_5043_50431401_79_dialog_content = "で、でも、僕はとっさに手袋を振り払って、\n逃げることができて、手袋もその場に残せました。",
  ui_story_5043_50431401_80_dialog_content = "あなたが残した手袋はこちらですか？",
  ui_story_5043_50431401_81_dialog_content = "そうです、これです！",
  ui_story_5043_50431401_82_dialog_content = "すべてのつじつまが合った！",
  ui_story_5043_50431401_83_dialog_content = "どうやら、証人ボーンの証言と証拠品が一致したようです。",
  ui_story_5043_50431401_84_dialog_content = "では、続いて…",
  ui_story_5043_50431401_85_dialog_content = "フン、一致した？",
  ui_story_5043_50431401_86_dialog_content = "事件記録に基づいた作り話にすぎません！",
  ui_story_5043_50431401_87_dialog_content = "今言ったことを証明できるものはあるのですか？",
  ui_story_5043_50431401_88_dialog_content = "シュワーベ裁判長は自ら罪を認めた証人を\n信用できないとおっしゃるのですか？",
  ui_story_5043_50431401_89_dialog_content = "フン、罪を認めた者が犯人とは限らないでしょう？",
  ui_story_5043_50431401_90_dialog_content = "何者かが私に罪を着せるために、\nその暗鬼を買収したのでしょう。",
  ui_story_5043_50431401_91_dialog_content = "卑しい生き物をまるめこんで\n私を悪に引きずり落とすことができるのなら、割のいい話ですからね。",
  ui_story_5043_50431401_92_dialog_content = "き、君が僕を悪の道に引きずりおとしたんだ！",
  ui_story_5043_50431401_93_dialog_content = "僕は白夜城に仕事をさがしにきただけなのに、\n君の悪だくみにまき込まれて、悪いことをさせられた。",
  ui_story_5043_50431401_94_dialog_content = "もし昨日地下室を誰かが開けなかったら、\n僕はずっと自由になれなかったんだ！",
  ui_story_5043_50431401_95_dialog_content = "おや？その地下室とやら、重要な場所のようだな？",
  ui_story_5043_50431401_96_dialog_content = "お聞きになりましたか？まだデタラメを言っていますよ！",
  ui_story_5043_50431401_97_dialog_content = "我が家の荘園には地下室などありません！",
  ui_story_5043_50431401_98_dialog_content = "地下室があるかどうかは、調べればすぐにわかるよ！",
  ui_story_5043_50431401_99_dialog_content = "我が家を調べるとでも？それは違法行為ですよ！",
  ui_story_5043_50431401_100_dialog_content = "サラール家には自身の秘密を守る権利があるのですから！",
  ui_story_5043_50431401_101_dialog_content = "そんな…",
  ui_story_5043_50431401_102_dialog_content = "シュワーベ裁判長のおっしゃる通りです。\n私たちにサラール荘園を調べる権利はありません。",
  ui_story_5043_50431401_103_dialog_content = "…",
  ui_story_5043_50431401_104_dialog_content = "あなたが自分で自分の有罪を証明しない限りは。",
  ui_story_5043_50431401_105_dialog_content = "どういうこと！？",
  ui_story_5043_50431401_106_dialog_content = "チッ…",
  ui_story_5043_50431401_107_dialog_content = "シュワーベ裁判長はお分かりですよね？\nだからこそ、先程――",
  ui_story_5043_50431401_108_dialog_content = "「罪を認めた者が犯人とは限らない」とおっしゃったのです。",
  ui_story_5043_50431401_109_dialog_content = "…",
  ui_story_5043_50431401_110_dialog_content = "あなたはその点にこだわっています。\nというのも、すべての鍵はそこにあるからです。",
  ui_story_5043_50431401_111_dialog_content = "ボーンが犯人となれば、法廷は彼の話したことをすべて調査し、\nつまびらかにしなければなりません。",
  ui_story_5043_50431401_112_dialog_content = "彼が犯人と証明できれば、それはもうただの証言ではなく、\n犯人の自白なのですから。",
  ui_story_5043_50431401_113_dialog_content = "人々は暗鬼が悪役である話を信じ、\n物事の背景には人知れぬ闇が隠れていると信じたがります。",
  ui_story_5043_50431401_114_dialog_content = "法廷は捜査令状を出し、\nボーンが話した内容のすべてを明らかにするでしょう。",
  ui_story_5043_50431401_115_dialog_content = "その時には「サラール荘園に地下室があるかどうか」も、\nはっきりしますよ。",
  ui_story_5043_50431401_116_dialog_content = "チッ、そうはうまくいきませんよ。\nライン、貴方が何をしようとしているかは分かっています。",
  ui_story_5043_50431401_117_dialog_content = "くだらない事件とその辺から連れて来た暗鬼をうまく利用して、\n我がサラール家の秘密を探ろうとしているのでしょう？",
  ui_story_5043_50431401_118_dialog_content = "そうはさせません。",
  ui_story_5043_50431401_119_dialog_content = "おい！私の事件をくだらないと言ったか！？",
  ui_story_5043_50431401_120_dialog_content = "お黙りなさい！！",
  ui_story_5043_50431401_121_dialog_content = "き…貴様…",
  ui_story_5043_50431401_122_dialog_content = "もう結構です！",
  ui_story_5043_50431401_123_dialog_content = "本法廷の裁判長として、\n証人席の暗鬼と事件は無関係と判断します。",
  ui_story_5043_50431401_124_dialog_content = "目下証拠不足のため、審理の継続は困難です。\n休廷後、詳しい調査と証拠収集を行うものとします。",
  ui_story_5043_50431401_125_dialog_content = "事件詳細は確かな証拠がそろった後、\n再び審理を再開するものとし…",
  ui_story_5043_50431401_126_dialog_content = "しょ、証明できます！",
  ui_story_5043_50431401_127_dialog_content = "！！！",
  ui_story_5043_50431401_128_dialog_content = "今ここで…法廷で…証明できます！",
  ui_story_5043_50431401_129_dialog_content = "また作り話で私に濡れ衣を着せるつもりですか？",
  ui_story_5043_50431401_130_dialog_content = "証拠があります！",
  ui_story_5043_50431401_131_dialog_content = "証人、その証拠とは何ですか？",
  ui_story_5043_50431401_132_dialog_content = "犯行現場に残した手袋です！",
  ui_story_5043_50431401_133_dialog_content = "…手袋？",
  ui_story_5043_50431401_134_dialog_content = "あ、あの人が手袋をきれいにしたから、\n暗鬼の痕跡は残ってないのは知ってます。",
  ui_story_5043_50431401_135_dialog_content = "でも、彫像をこわす前、\n手袋の内側にツメでキズをつけました。",
  ui_story_5043_50431401_136_dialog_content = "あ、あれは洗っても、なくなりません！",
  ui_story_5043_50431401_137_dialog_content = "何！？",
  ui_story_5043_50431401_138_dialog_content = "そうですか。では、その傷さえ見つければ、\n手袋をはめていたのはあなただと証明できるのですね。",
  ui_story_5043_50431401_139_dialog_content = "つまり、あなたが犯人だということになります。",
  ui_story_5043_50431401_140_dialog_content = "はい！",
  ui_story_5043_50431401_141_dialog_content = "シュワーベ裁判長、\n本件の核心となる証拠品を調べさせていただけませんか？",
  ui_story_5043_50431401_142_dialog_content = "…",
  ui_story_5043_50431401_143_dialog_content = "手袋をお渡しいただけませんか？",
  ui_story_5043_50431401_144_dialog_content = "休廷するのならば、なおさら急がねばなりません。\nこれで最後です、さあ。",
  ui_story_5043_50431401_145_dialog_content = "…",
  ui_story_5043_50431401_146_dialog_content = "シュワーベ裁判長？",
  ui_story_5043_50431401_147_dialog_content = "…チッ。",
  ui_story_5043_50431401_148_dialog_content = "だから、<color=#FFB400>恋愛は嫌い</color>なのです。",
  ui_story_5043_50431401_149_dialog_content = "え！？",
  ui_story_5043_50431401_150_dialog_content = "今のって、つまり…",
  ui_story_5043_50431401_151_dialog_content = "押し寄せる平凡な奴らに取り囲まれ、\n愛だの恋だのと言われるのはもうウンザリです。",
  ui_story_5043_50431401_152_dialog_content = "独りよがりに私に近づき、私のプライベートを探ってくる…",
  ui_story_5043_50431401_153_dialog_content = "貴方たちのやっていることと同じですよ。",
  ui_story_5043_50431401_154_dialog_content = "恋愛が嫌いだと？",
  ui_story_5043_50431401_155_dialog_content = "ええ、大嫌いです！\n恋愛など永遠に覚めることのない悪夢です！",
  ui_story_5043_50431401_156_dialog_content = "同年代の女どもに取り囲まれ、\nこびへつらう言葉に耐える毎日…",
  ui_story_5043_50431401_157_dialog_content = "学生時代、机にはラブレターが山のように積まれ、\n祝日には家に山のようなプレゼントが届く…",
  ui_story_5043_50431401_158_dialog_content = "この世のすべての人に好かれるというのが、\nいかに苦しいことか、貴方たちに分かるのですか！？",
  ui_story_5043_50431401_159_dialog_content = "…",
  ui_story_5043_50431401_160_dialog_content = "…何の話？",
  ui_story_5043_50431401_161_dialog_content = "わ、私にも…分からないわ…",
  ui_story_5043_50431401_162_dialog_content = "仕事をするようになれば、\n少しは良くなるかと思っていたのに…",
  ui_story_5043_50431401_163_dialog_content = "まさか、この白夜城でおぞましい恋愛をたたえる風潮が\n起こるとは思いませんでした！",
  ui_story_5043_50431401_164_dialog_content = "しかも、この私が「恋愛法廷」の裁判長ですと！？",
  ui_story_5043_50431401_165_dialog_content = "ああ、もうウンザリなのです！\n何としても彫像を壊さなければなりません！",
  ui_story_5043_50431401_166_dialog_content = "あの浅はかな主催者は彫像の文化的な雰囲気を借りて、\n自身の活動に箔を付けようとしているのです。そんなことは私が許しません！",
  ui_story_5043_50431401_167_dialog_content = "何てことを…",
  ui_story_5043_50431401_168_dialog_content = "暴力で自身の考えを主張するなど、\nどちらが浅はかですか！",
  ui_story_5043_50431401_169_dialog_content = "つまり、あなたが暗鬼に彫像を破壊させたのですね？",
  ui_story_5043_50431401_170_dialog_content = "その通り、私が暗鬼を遣わしたのですよ。\n汚らわしい暗鬼こそ恋愛にふさわしい！",
  ui_story_5043_50431401_171_dialog_content = "今お話しになったことを自供ととってもよろしいですか？",
  ui_story_5043_50431401_172_dialog_content = "そんな煩わしい決まりことなど、どうでもいいでしょう？",
  ui_story_5043_50431401_173_dialog_content = "この案件は貴方の勝ちですよ。\n十分な証拠を握っていますからね。",
  ui_story_5043_50431401_174_dialog_content = "私の唯一のミスは「道具」を処分しなかったことです。\n口封じするべきでした。",
  ui_story_5043_50431401_175_dialog_content = "…",
  ui_story_5043_50431401_176_dialog_content = "いいえ、あなたが負けたのは\nそんな複雑な理由ではありません。",
  ui_story_5043_50431401_177_dialog_content = "唯一のミスは、私に手袋を調べさせなかったことです。",
  ui_story_5043_50431401_178_dialog_content = "<size=45>何ですと！？</size>",
  ui_story_5043_50431401_179_dialog_content = "ちょっと待ってよ！\n手袋の内側には決め手になる証拠の傷があるんじゃないの！？",
  ui_story_5043_50431401_180_dialog_content = "まさか…そんなものは存在しないというの？",
  ui_story_5043_50431401_181_dialog_content = "ふぅ。いやはやどうなることかと思ったわ。\n順調に進んだからよかったものを。",
  ui_story_5043_50431401_182_dialog_content = "ライン、お前には詐欺師の才能があると見える。",
  ui_story_5043_50431401_183_dialog_content = "私をだましたのですか！？",
  ui_story_5043_50431401_184_dialog_content = "こ、この暗鬼は手袋の内側に傷など\n残していなかったというのですか！？",
  ui_story_5043_50431401_185_dialog_content = "ふふ、それだけではありませんよ。",
  ui_story_5043_50431401_186_dialog_content = "偶然が重なりすぎているとは思いませんか？",
  ui_story_5043_50431401_187_dialog_content = "唯一あなたの家から逃げ出すことのできた暗鬼が、\nたまたま彫像破壊の任務を与えられた暗鬼だった…",
  ui_story_5043_50431401_188_dialog_content = "まさか…",
  ui_story_5043_50431401_189_dialog_content = "<color=#e8d9bb>昨日</color>",
  ui_story_5043_50431401_190_dialog_content = "お前も残業するのか？",
  ui_story_5043_50431401_191_dialog_content = "まだ調べ切れていないことがありますから。\n開廷までに資料を詳細にチェックしておくのは当然のことです。",
  ui_story_5043_50431401_192_dialog_content = "むしろ意外なのは、あなたが残業なさっていることです。",
  ui_story_5043_50431401_193_dialog_content = "チッ。新人の庶民。お前は私の裁判官としての自覚を疑っておるのか？\nそれともティナを見捨てるような冷血漢だとでも思っておるのか？",
  ui_story_5043_50431401_194_dialog_content = "フン、まあ、よい。今日は言い争いはなしだ。\n何よりも事件に集中しなければ…",
  ui_story_5043_50431401_195_dialog_content = "す、すみません…法廷はまだやってますか？",
  ui_story_5043_50431401_196_dialog_content = "なにぃ！？暗鬼だぞ！？",
  ui_story_5043_50431401_197_dialog_content = "いい度胸しておるではないか！\n法廷までのこのこ出てくるとは！打ちのめしてくれるわ！",
  ui_story_5043_50431401_198_dialog_content = "や、やめてください！！通報しにきたんです！",
  ui_story_5043_50431401_199_dialog_content = "むむ？暗鬼が通報だと？",
  ui_story_5043_50431401_200_dialog_content = "話を聞いてみませんか。どうせ1匹です。\n片付けようと思えばいつでも片づけられます。",
  ui_story_5043_50431401_201_dialog_content = "よかろう。では話してみよ。\n何を通報するというのだ？",
  ui_story_5043_50431401_202_dialog_content = "はい！",
  ui_story_5043_50431401_203_dialog_content = "ま、まず自己紹介します…",
  ui_story_5043_50431401_204_dialog_content = "<color=#e8d9bb>10分後</color>",
  ui_story_5043_50431401_205_dialog_content = "…そ、それから、ほかの暗鬼と一緒にシュワーベ家の、\nち、地下室に閉じ込められました。",
  ui_story_5043_50431401_206_dialog_content = "なんと！どうりで地下室で暗鬼に出くわしたわけだ！",
  ui_story_5043_50431401_207_dialog_content = "はい！僕はあの時地下室から逃げ出したんです！",
  ui_story_5043_50431401_208_dialog_content = "おお！！",
  ui_story_5043_50431401_209_dialog_content = "ならば、我々がお前を救ったということだな！",
  ui_story_5043_50431401_210_dialog_content = "そ、そうだったんですか！ありがとうございます！！",
  ui_story_5043_50431401_211_dialog_content = "それで、あなたはシュワーベを暗鬼監禁で訴えたいというのですか？",
  ui_story_5043_50431401_212_dialog_content = "は、はい！びゃ、白夜城の法律は暗鬼を守ってくれないのは知ってますが、\nあの人はきっともっと大きなことを企んでます！",
  ui_story_5043_50431401_213_dialog_content = "それなら簡単だ。\n明日法廷で今話したことをもう一度話せばよい。",
  ui_story_5043_50431401_214_dialog_content = "皆の者に示してやろうではないか！\nシュワーベの悪党が裏で何をやっていたかを！",
  ui_story_5043_50431401_215_dialog_content = "はい、話します！",
  ui_story_5043_50431401_216_dialog_content = "では、証拠はあるのですか？",
  ui_story_5043_50431401_217_dialog_content = "しょ、証拠？",
  ui_story_5043_50431401_218_dialog_content = "忘れてはなりませんよ。あなたは暗鬼なのです。",
  ui_story_5043_50431401_219_dialog_content = "私たちはシュワーベ家の地下室に行ったことがあるので、\n今のお話を信じますが、他の人はどうでしょう？",
  ui_story_5043_50431401_220_dialog_content = "証拠がない場合、シュワーベが頑として事実を否認すれば、\n私たちにはどうすることもできません。",
  ui_story_5043_50431401_221_dialog_content = "かえって、仕返しを受けることになります。",
  ui_story_5043_50431401_222_dialog_content = "とても危険なことなのです。",
  ui_story_5043_50431401_223_dialog_content = "す、すみません。証拠はありません…",
  ui_story_5043_50431401_224_dialog_content = "に、逃げ出すだけでもう…ありったけの力を、使ってしまいました…",
  ui_story_5043_50431401_225_dialog_content = "おい、これほど重大なことを証拠がないからといって、\nそのままにしておけんだろう！",
  ui_story_5043_50431401_226_dialog_content = "もう一度サラール荘園に忍び込むか？",
  ui_story_5043_50431401_227_dialog_content = "いいえ、そんなことをしなくても済みそうです。\nいい方法を思いつきました…",
  ui_story_5043_50431401_228_dialog_content = "どんな方法だ？",
  ui_story_5043_50431401_229_dialog_content = "証拠がないなら、法廷で奴に罪を認めさせればいいのです。",
  ui_story_5043_50431401_230_dialog_content = "なに？バカなことを言うでない。",
  ui_story_5043_50431401_231_dialog_content = "証拠がないのに、奴が認めるわけなかろうが。",
  ui_story_5043_50431401_232_dialog_content = "奴は暗鬼を囲って何をしていたと思いますか？",
  ui_story_5043_50431401_233_dialog_content = "ううむ…これだけの危険を冒すからには、\n相当大きなことを企んでいるのだろう。",
  ui_story_5043_50431401_234_dialog_content = "私は、奴は暗鬼に命令して彫像を壊していたのだと推測しています。",
  ui_story_5043_50431401_235_dialog_content = "ほう？なぜそう思う？",
  ui_story_5043_50431401_236_dialog_content = "千星の階段でのことを覚えてらっしゃいますか？\n私は犯人の手をつかみました。",
  ui_story_5043_50431401_237_dialog_content = "ですが、皆さんが暗鬼を倒し終えた時には、\n周りには誰一人として残っていませんでした。",
  ui_story_5043_50431401_238_dialog_content = "千星の階段の上は広々としています。\n通常あの短時間で私たちの視界から外れることは考えられません。",
  ui_story_5043_50431401_239_dialog_content = "犯人が暗鬼でない限りは。",
  ui_story_5043_50431401_240_dialog_content = "おお、分かったぞ！暗鬼を倒した時、\n犯人の暗鬼も倒してしまったというわけだな！",
  ui_story_5043_50431401_241_dialog_content = "だから捕らえられなかったのだ！",
  ui_story_5043_50431401_242_dialog_content = "ええ、その可能性が最も高いといえるでしょう。",
  ui_story_5043_50431401_243_dialog_content = "ならば、お前はこの可能性をどう利用する気なのだ？",
  ui_story_5043_50431401_244_dialog_content = "ボーンを犯人に仕立て上げましょう。",
  ui_story_5043_50431401_245_dialog_content = "そして、ボーンの口から私たちの真相に関する推測を話させるのです。",
  ui_story_5043_50431401_246_dialog_content = "私たちの推測が真相に近いものならば、\nシュワーベはきっとボーンが自分の遣わした暗鬼だと信じることでしょう。",
  ui_story_5043_50431401_247_dialog_content = "なるほど！我々が重要な証人を握っていると信じさせ、\n罪を認めぜるを得なくなるよう追い込むというのだな！？",
  ui_story_5043_50431401_248_dialog_content = "はい。一種の心理戦ですね。",
  ui_story_5043_50431401_249_dialog_content = "ボーン、法廷でウソをつけますか？",
  ui_story_5043_50431401_250_dialog_content = "シュワーベの悪行をさらすことができるなら、やります！",
  ui_story_5043_50431401_251_dialog_content = "いいでしょう。\nでは、今晩中に言うべき内容を全部覚えてもらいますよ。",
  ui_story_5043_50431401_252_dialog_content = "この心理戦に勝つために、一緒に知恵を絞りましょう。",
  ui_story_5043_50431401_253_dialog_content = "奴が本当だと信じ込むような、\n一発逆転の証拠を作りだすのです！",
  ui_story_5043_50431401_254_dialog_content = "な、なんと…卑怯者め！",
  ui_story_5043_50431401_255_dialog_content = "あなたと同じ方法を用いたまでのことです。",
  ui_story_5043_50431401_256_dialog_content = "なんということだ！真犯人がまさか裁判長だったとは！",
  ui_story_5043_50431401_257_dialog_content = "ああ、ここは真っ暗だ！\nこの法廷は闇に染まっておる！",
  ui_story_5043_50431401_258_dialog_content = "ですが、真相を明らかにしたのもまた、\nその法廷ではありませんか？",
  ui_story_5043_50431401_259_dialog_content = "闇があるからこそ、その闇を打ち砕き、晴らす力が必要なのです！",
  ui_story_5043_50431401_260_dialog_content = "終わりにしようではないか、シュワーベ裁判長。\n最後くらい堂々と終わらせい。",
  ui_story_5043_50431401_261_dialog_content = "フン、最後ですと？",
  ui_story_5043_50431401_262_dialog_content = "ライン、貴方にも唯一のミスがありますよ。\n何だかお分かりですか？",
  ui_story_5043_50431401_263_dialog_content = "…私にですか？",
  ui_story_5043_50431401_264_dialog_content = "真相を突き止めれば、全てが終わると思ったら大間違いですよ。",
  ui_story_5043_50431401_265_dialog_content = "本法廷は、ライン、ティナ、マシュー3名の裁判官を\n本件の犯人と認めます！",
  ui_story_5043_50431401_266_dialog_content = "以上の3名を判決の言い渡し後、逮捕します！",
  ui_story_5043_50431401_267_dialog_content = "何をバカなことを！",
  ui_story_5043_50431401_268_dialog_content = "ここにいる全員が聞いたのですよ。\nあなたこそ真犯人です！",
  ui_story_5043_50431401_269_dialog_content = "おや？真犯人について、\nいまだ意見が一致していないようですね。",
  ui_story_5043_50431401_270_dialog_content = "それでは、合議制の規則にのっとり、\n投票による裁決を行います。",
  ui_story_5043_50431401_271_dialog_content = "合議制ですと！？",
  ui_story_5043_50431401_272_dialog_content = "ちょっと待って…あれは…！？",
  ui_story_5043_50431401_273_dialog_content = "暗鬼だと！？いつ現れたのだ！？",
  ui_story_5043_50431401_274_dialog_content = "ライン、貴方の結論をお話しください。",
  ui_story_5043_50431401_275_dialog_content = "…シュワーベ・サラールが真犯人です。",
  ui_story_5043_50431401_276_dialog_content = "よろしい。では、彼の結論に同意する方は手を挙げてください。",
  ui_story_5043_50431401_277_dialog_content = "どれどれ…ライン、マシュー、ティナ、下級裁判官…",
  ui_story_5043_50431401_278_dialog_content = "4票ですか。多くの方が貴方の結論を信じたようですね。",
  ui_story_5043_50431401_279_dialog_content = "それが真相だからです！",
  ui_story_5043_50431401_280_dialog_content = "しかし、私はライン、ティナ、マシューの3名が\n真犯人だと考えています。",
  ui_story_5043_50431401_281_dialog_content = "私の結論に同意する方は、机をたたいてください。",
  ui_story_5043_50431401_282_dialog_content = "<color=#e8d9bb>バン！</color>",
  ui_story_5043_50431401_283_dialog_content = "<color=#e8d9bb>バン！</color>",
  ui_story_5043_50431401_284_dialog_content = "<color=#e8d9bb>バン！</color>",
  ui_story_5043_50431401_285_dialog_content = "<color=#e8d9bb>バン！</color>",
  ui_story_5043_50431401_286_dialog_content = "そんな…",
  ui_story_5043_50431401_287_dialog_content = "4票ですね。",
  ui_story_5043_50431401_288_dialog_content = "私シュワーベ・サラール本人を加えて、5票です。",
  ui_story_5043_50431401_289_dialog_content = "どうやら、私の結論の方が賛同が多いようです。",
  ui_story_5043_50431401_290_dialog_content = "ば、陪審員を全員…自分の息のかかった者に変えていたのですね！",
  ui_story_5043_50431401_291_dialog_content = "息のかかった者だと？\nあの被り物の下に隠れているのはどうせ暗鬼であろうが！",
  ui_story_5043_50431401_292_dialog_content = "投票結果が出ました！投票に従い、最終判決を言い渡します！",
  ui_story_5043_50431401_293_dialog_content = "ライン、マシュー、ティナの3名を――",
  ui_story_5043_50431401_294_dialog_content = "有罪とします！",
  ui_story_5043_50431401_295_dialog_content = "<color=#e8d9bb>カン――</color>",
  ui_story_5043_50431401_296_dialog_content = "あの陪審員たち、絶対におかしい！",
  ui_story_5043_50431401_X296_dialog_content = "ものすごい暗力を感じる！あれは暗鬼だ！！",
  ui_story_5043_50431401_X297_dialog_content = "な、何だと！？",
  ui_story_5043_50431401_X298_dialog_content = "そんなはずあるまい。吾輩と並んで座っていた者が\n全員暗鬼だったというか！？",
  ui_story_5043_50431401_297_dialog_content = "陪審員の皆さま、お手伝いを願います。",
  ui_story_5043_50431401_298_dialog_content = "聴衆としてだけではなく、\n私の「騎士」として法を実践してください。",
  ui_story_5043_50431401_299_dialog_content = "法廷は判決を実行する権利に基づき――",
  ui_story_5043_50431401_300_dialog_content = "犯人を逮捕します！",
  ui_story_5043_50431401_301_dialog_content = "ガァ…",
  ui_story_5043_50431401_302_dialog_content = "大変だ。あの被り物をかぶったおかしな陪審員、\nただの暗鬼じゃないみたいだ！",
  ui_story_5043_50431401_303_dialog_content = "ええ。シュワーベの切り札であるからには、\n手ごわい相手に決まっているわ。",
  ui_story_5043_50431401_304_dialog_content = "ええい、お前という奴は！\n道理が通じぬなら力技で押し通す気か！",
  ui_story_5043_50431401_305_dialog_content = "大変です。法廷の構造は向こうに有利です。\nこのままでは囲まれてしまいますわ。",
  ui_story_5043_50431401_306_dialog_content = "私たちが正しいというのに…\nよりによって法廷で正義が闇に打ち勝てないとは…",
  ui_story_5043_50431401_307_dialog_content = "なんて頭が固いのでしょう！勝った側こそ正義ですよ！\n負ければ、ただの「被害者」です！",
  ui_story_5043_50431401_308_dialog_content = "とにかく逃げましょう！",
  ui_story_5043_50431401_309_dialog_content = "そうだよ！ぼうっとしてないで！",
  ui_story_5043_50431401_310_dialog_content = "急いで！こっちへ来て！",
  ui_story_5043_50431402_1_dialog_content = "みんなで愛の真理を高く空にかかげよう♪",
  ui_story_5043_50431402_2_dialog_content = "美しい皮をかぶせて万人を楽しませよう♪",
  ui_story_5043_50431402_3_dialog_content = "愛はどれだけ美しいのかと想像をめぐらせる人々♪",
  ui_story_5043_50431402_4_dialog_content = "愛が花開く瞬間を見るために多少の汚れもいとわない♪",
  ui_story_5043_50431402_5_dialog_content = "今日、月の気球を割るって本当か？",
  ui_story_5043_50431402_6_dialog_content = "もちろん本当だ！みんなそれを見に来てるんだからな。",
  ui_story_5043_50431402_7_dialog_content = "気球の中には花や折り紙、\n色とりどりのシャボン玉が入ってるらしいぞ。",
  ui_story_5043_50431402_8_dialog_content = "愛をたたえる活動のシンボルだ。\nきっとその辺の花火なんかよりもきれいだろうな！",
  ui_story_5043_50431402_9_dialog_content = "あれ？法廷の入口から人が駆け出してくるぞ。",
  ui_story_5043_50431402_10_dialog_content = "何をしてるんだ？",
  ui_story_5043_50431402_11_dialog_content = "ふぅ…何とか逃げ出せたようだな。",
  ui_story_5043_50431402_12_dialog_content = "気を抜いちゃダメだよ。まだ追ってきてるんだから！",
  ui_story_5043_50431402_13_dialog_content = "…",
  ui_story_5043_50431402_14_dialog_content = "ええいっ、しつこいバケモノめ！",
  ui_story_5043_50431402_15_dialog_content = "まさか影ノ街まで逃げないと駄目か？",
  ui_story_5043_50431402_16_dialog_content = "お待ちください！パレード隊がこちらへ向かってくるようです！",
  ui_story_5043_50431402_17_dialog_content = "よりによってこんな時に…",
  ui_story_5043_50431402_18_dialog_content = "これ以上逃げられません。\nあの方たちが暗鬼に襲われてしまいますわ。",
  ui_story_5043_50431402_19_dialog_content = "ええ。ここで引き止めないといけないわね。",
  ui_story_5043_50431402_20_dialog_content = "PlayerName、パレード隊を避難させて。",
  ui_story_5043_50431402_21_dialog_content = "うん、今すぐ避難させるよ…",
  ui_story_5043_50431402_22_dialog_content = "あの人たちはショーを観にきたのですよ。\n前代未聞の素晴らしいショーをね。",
  ui_story_5043_50431402_23_dialog_content = "愛をたたえる素晴らしい風潮に\n冷や水を浴びせてもよいのですか？",
  ui_story_5043_50431402_24_dialog_content = "お前という奴は皮肉しか言えんのか！",
  ui_story_5043_50431402_25_dialog_content = "いいえ、私は心からショーが順調に行われることを\n望んでいるだけですよ。",
  ui_story_5043_50431402_26_dialog_content = "このふざけた風潮がそれにふさわしい、\n滑稽なクライマックスを迎えることを！",
  ui_story_5043_50431402_27_dialog_content = "<size=45>さあ、皆さん！こちらへ寄ってください！</size>",
  ui_story_5043_50431402_28_dialog_content = "<size=45>ショーが始まりますよ！</size>",
  ui_story_5043_50431402_29_dialog_content = "…シュワーベ、いったい何をするつもりなの？",
  ui_story_5043_50431402_30_dialog_content = "大変です！きっと私たちの活動を台無しにする気です！",
  ui_story_5043_50431402_31_dialog_content = "人混みが押し寄せて来たよ！\n暗鬼の方へ近づいてくる！",
  ui_story_5043_50431402_32_dialog_content = "分かりました！私があの方たちを守ります！",
  ui_story_5043_50431402_33_dialog_content = "そう緊張なさることはありませんよ。\nただのショーなのですから。",
  ui_story_5043_50431402_34_dialog_content = "今日、月の気球を割るのですよね？",
  ui_story_5043_50431402_35_dialog_content = "では、皆さんに見ていただこうではありませんか。\n貴方たちの見上げていた愛の中にいったい何が隠されていたのかを。",
  ui_story_5043_50431402_36_dialog_content = "まさか…",
  ui_story_5043_50431402_37_dialog_content = "バカげた信仰が花を開きますよ。",
  ui_story_5043_50431402_38_dialog_content = "<color=#e8d9bb>バン！！</color>",
  ui_story_5043_50431402_39_dialog_content = "わあああああ！！！",
  ui_story_5043_50431402_40_dialog_content = "皆さん、気を付けてください！！",
  ui_story_5043_50431402_41_dialog_content = "おい、空から降ってくるのって…",
  ui_story_5043_50431402_42_dialog_content = "どういうことなのです？古来の祝日からの贈り物――\n私のクローバーの花束がどうして…",
  ui_story_5043_50431402_43_dialog_content = "これは…枯れた花？",
  ui_story_5043_50431402_44_dialog_content = "ええ。しかも、愛のシンボルである赤いクローバーの花ですわ…",
  ui_story_5043_50431402_45_dialog_content = "空いっぱいに枯れた花が…",
  ui_story_5043_50431402_46_dialog_content = "なんて醜いんだ。\nこんなものを見せられて最低な気分になったよ。",
  ui_story_5043_50431402_47_dialog_content = "月の気球を割ったら、こうなったのか？",
  ui_story_5043_50431402_48_dialog_content = "ええ、その通りですよ。",
  ui_story_5043_50431402_49_dialog_content = "シュワーベ、止まってください！",
  ui_story_5043_50431402_50_dialog_content = "恋愛とは、しょせんこういうことでしょう？",
  ui_story_5043_50431402_51_dialog_content = "中身を知らない時は、想像を膨れませ、\n完璧なものかのように美化してしまう…",
  ui_story_5043_50431402_52_dialog_content = "空に浮かぶ月であり、手の届かない、測り知ることのできない、\n最も神秘的で美しいものと想像するのです。",
  ui_story_5043_50431402_53_dialog_content = "その美しさはすべて無知がもたらすもの。\n本当の姿を誰も知らないからこそ生まれる空想なのです。",
  ui_story_5043_50431402_54_dialog_content = "さあ、空想はおしまいです。\n今はもう全員が知ってしまいました。",
  ui_story_5043_50431402_55_dialog_content = "恋愛など、しょせんこの程度のものです。",
  ui_story_5043_50431402_56_dialog_content = "バカげたお祭り騒ぎの後の雑然とした残骸に過ぎないのですよ。",
  ui_story_5043_50431402_57_dialog_content = "そして、もう二度と空に月は昇らないでしょう。",
  ui_story_5043_50431402_58_dialog_content = "そうだな。この先もう二度と月の気球は見られないんだな。",
  ui_story_5043_50431402_59_dialog_content = "見られなくたっていいじゃないか。\n枯れた花束しか入ってなかったんだ。ゴミ袋も同然だ…",
  ui_story_5043_50431402_60_dialog_content = "そんなのき弁ですわ！\nきっとあなたが前もって気球の中身をすり替えたに違いありません！",
  ui_story_5043_50431402_61_dialog_content = "気球の中身には触れていませんよ。\nただ気球に施されていた光力術の層を破壊しただけです。",
  ui_story_5043_50431402_62_dialog_content = "なんてことを…！",
  ui_story_5043_50431402_63_dialog_content = "どうかされましたか？貴方は光力術で生花の状態を保ち、\n大衆をだまそうとしていたのでしょう？",
  ui_story_5043_50431402_64_dialog_content = "私はただ真相を明らかにしただけですよ。",
  ui_story_5043_50431402_65_dialog_content = "大衆が美しいものを見られるのは、\n誰かが醜悪さを一人で引き受けてくれているからです。",
  ui_story_5043_50431402_66_dialog_content = "私を慕う女性たちが恋愛の美しさを享受できるのは、\n私が彼女たちの押しつけがましい思いに耐えているからです。",
  ui_story_5043_50431402_67_dialog_content = "愛の真の姿とはそういうものなのでしょうか…",
  ui_story_5043_50431402_68_dialog_content = "重すぎる愛はかえってその人に負担を強いてしまう…",
  ui_story_5043_50431402_69_dialog_content = "その通りですよ。一つ学びましたね。",
  ui_story_5043_50431402_70_dialog_content = "…",
  ui_story_5043_50431402_71_dialog_content = "（私も…そのような過ちを犯したのですね…）",
  ui_story_5043_50431402_72_dialog_content = "そんなことないよ、ティナ！\nシュワーベの口車にだまされちゃいけないよ！",
  ui_story_5043_50431402_73_dialog_content = "えっ？",
  ui_story_5043_50431402_74_dialog_content = "シュワーベの言っていることが恋愛のすべてじゃないでしょ？",
  ui_story_5043_50431402_75_dialog_content = "同じことでも、一人一人感じ方は違うものだよ。",
  ui_story_5043_50431402_76_dialog_content = "恋愛の真相が何かなんて、僕には分からない。\nでも、皆がサロンを毎回楽しんでたのは知ってる。それで十分だよ！",
  ui_story_5043_50431402_77_dialog_content = "それにシュワーベは恋愛なんてしたことないでしょ！？",
  ui_story_5043_50431402_78_dialog_content = "恋愛について、偉そうに語る資格なんてないよ！",
  ui_story_5043_50431402_79_dialog_content = "クッ…",
  ui_story_5043_50431402_80_dialog_content = "恋愛のような汚らわしいものに、\nこの私が触れるわけないでしょう！？",
  ui_story_5043_50431402_81_dialog_content = "そうです！PlayerNameさんの言う通りですわ！",
  ui_story_5043_50431402_82_dialog_content = "真相などそもそも存在しないのです。\nあなたはただ恋愛の可能性の中で最悪の結果を誇張しているだけです！",
  ui_story_5043_50431402_83_dialog_content = "それに、美しいことばかりを想像する過程こそが恋愛ではないのですか？",
  ui_story_5043_50431402_84_dialog_content = "恋愛は法廷での裁決とは違います。\n結果だけですべてを語れるものではありません！",
  ui_story_5043_50431402_85_dialog_content = "片思い、告白、交際、別れ…\nそうした心と心のふれあいのすべてが恋愛を作り上げているのです！",
  ui_story_5043_50431402_86_dialog_content = "シュワーベさん、あなたは恋愛が何たるかを理解できていません！",
  ui_story_5043_50431402_87_dialog_content = "ふふ。確かに貴方のおっしゃる通り、\n私は恋愛を理解できていないのかもしれませんね。",
  ui_story_5043_50431402_88_dialog_content = "恋愛のどこに貴方たちが夢中になるような価値があるのか\n理解できません。",
  ui_story_5043_50431402_89_dialog_content = "私にとっては、煩わしい虫のようなもの。静かな暮らしを乱し、\n他人が私の生活に干渉する理由を与えるものでしかありません。",
  ui_story_5043_50431402_90_dialog_content = "いいえ、暮らしだけではありません。\n最も忌まわしいのは私の仕事にも悪影響を与え、白夜城の公正にまで悪影響を与えたことです！",
  ui_story_5043_50431402_91_dialog_content = "なぜそうなるのです？",
  ui_story_5043_50431402_92_dialog_content = "くだらない感情のために、\n周りの者たちがことごとく理性を失いました。",
  ui_story_5043_50431402_93_dialog_content = "しかも、それだけでは飽き足らず、「恋愛法廷」などという\n法廷の本質に反したものまで生み出しました！",
  ui_story_5043_50431402_94_dialog_content = "愛情が何をもたらしたか、よく考えてみてください。\n愛情は罪人が罪を逃れる言い訳になり、罪のないものに濡れ衣を着せました。",
  ui_story_5043_50431402_95_dialog_content = "白夜城が数百年かけて築いた法制度を汚したのです！",
  ui_story_5043_50431402_96_dialog_content = "ですから、私は戦わなければなりません。\n法廷に立ち、この邪悪な風潮に立ち向かわなければなりません。",
  ui_story_5043_50431402_97_dialog_content = "私のしたことは全て、ありとあらゆる愛情の要素を排除する\n法廷を築き上げるためです。",
  ui_story_5043_50431402_98_dialog_content = "私には考えを同じくする陪審員が必要です。\n彼らの意志はいかなる感情にも毒されてはなりません。",
  ui_story_5043_50431402_99_dialog_content = "この醜い怪物たちはその条件を満たしています。",
  ui_story_5043_50431402_100_dialog_content = "…",
  ui_story_5043_50431402_101_dialog_content = "そんな風に考えてたんだ…",
  ui_story_5043_50431402_102_dialog_content = "極端で、身勝手な道理でこじつけた考え方だわ。",
  ui_story_5043_50431402_103_dialog_content = "こういう人は名利に目のくらんだ罪人よりも恐ろしい。",
  ui_story_5043_50431402_104_dialog_content = "さあ、愛に関するつまらぬ話はここまでとしましょう。",
  ui_story_5043_50431402_105_dialog_content = "皆さんにも私と同じように、\n事件とその判決に注意を戻していただきたいですね。",
  ui_story_5043_50431402_106_dialog_content = "お忘れになってはいけませんよ。\n貴方たちは全員<color=#FFB400>有罪</color>なのです！",
  ui_story_5043_50431402_107_dialog_content = "おい、あっちを見ろ！",
  ui_story_5043_50431402_108_dialog_content = "暗鬼が法廷から飛び出して来たぞ！",
  ui_story_5043_50431402_109_dialog_content = "今日はなんてツイてないんだ！逃げるぞ！",
  ui_story_5043_50431402_110_dialog_content = "大変だ！シュワーベがまた襲ってきた！",
  ui_story_5043_50431402_111_dialog_content = "公然と暗鬼を召喚するとは、完全におかしくなったようね。\nすぐに衛兵が捕らえるわ。",
  ui_story_5043_50431402_112_dialog_content = "けれど、今は私たちでこの状況を抑えなければ！\n一般民衆に被害を出すわけにはいかない！",
  ui_story_5043_50431402_113_dialog_content = "そうは言っても、あの石膏の被り物をかぶった暗鬼は\nなかなか手ごわいよ…",
  ui_story_5043_50431402_114_dialog_content = "私が相手いたします。",
  ui_story_5043_50431402_115_dialog_content = "キャンベル家の名誉にかけて――",
  ui_story_5043_50431402_116_dialog_content = "「神の手」の力にかけて私が仕留めます！",
  ui_story_5043_50431402_117_dialog_content = "わ、すごい光力だ！",
  ui_story_5043_50431402_118_dialog_content = "この威力なら、本当に…",
  ui_story_5043_50431402_119_dialog_content = "ふわぁ――",
  ui_story_5043_50431402_120_dialog_content = "え！？こんな時にあくび！？",
  ui_story_5043_50431402_121_dialog_content = "今日はもう…長く…起きていたので…",
  ui_story_5043_50431402_122_dialog_content = "フン。四騎士、奴らを捕らえろ。",
  ui_story_5043_50431402_123_dialog_content = "こんな時に手を出すなんて、卑怯だよ！",
  ui_story_5043_50431402_124_dialog_content = "ティナ！しっかりして！",
  ui_story_5043_50431402_125_dialog_content = "うう…神の手で私が…",
  ui_story_5043_50431402_126_dialog_content = "<color=#e8d9bb>バタン――</color>",
  ui_story_5043_50431402_127_dialog_content = "まだ戦いも始まってないのに、眠っちゃったよ！！",
  ui_story_5043_50431402_128_dialog_content = "どうしよう！？戦いの場で眠るなんて危険すぎるよ！",
  ui_story_5043_50431402_129_dialog_content = "ティナ、起きてください！敵が来ますよ！",
  ui_story_5043_50431402_130_dialog_content = "星が…ラインさんの頭の上に…星が出ていますわ…",
  ui_story_5043_50431402_131_dialog_content = "星などどうでもいいのです！戦ってください！",
  ui_story_5043_50431402_132_dialog_content = "もう…限界ですわ…",
  ui_story_5043_50431402_133_dialog_content = "さあ、口を開けて。飲み込んでください。",
  ui_story_5043_50431402_134_dialog_content = "こんな時に何を食べさせてるの！？それは…チョコレート？",
  ui_story_5043_50431402_135_dialog_content = "私はもう…限界…",
  ui_story_5043_50431402_136_dialog_content = "どうしよう…敵はもう目の前まで来てる…",
  ui_story_5043_50431402_137_dialog_content = "目が覚めましたわ！",
  ui_story_5043_50431402_138_dialog_content = "え！？",
  ui_story_5043_50431402_139_dialog_content = "落差が激しすぎるんだけど…",
  ui_story_5043_50431402_140_dialog_content = "ふふ、直球型のアタックしかお出来になりませんの？\nそれでは振り向いていただけませんよ！",
  ui_story_5043_50431402_141_dialog_content = "私がどうすればよいか教えて差し上げます！",
  ui_story_5043_50431402_142_dialog_content = "え？どうするの？",
  ui_story_5043_50431402_143_dialog_content = "お忘れですか？皆さんが教えてくださったのですよ。",
  ui_story_5043_50431402_144_dialog_content = "相手を振り向かせるには色々な方法があります。それにはもちろん――\n<color=#FFB400>自分から告白</color>することも含まれていますわ！",
  ui_story_5043_50431402_145_dialog_content = "ラインさん、あなたのおっしゃったとおりですわ。\n自分から相手の注意力を引き付けるのはとても大切です！",
  ui_story_5043_50431402_X145_dialog_content = "バケモノたちを人混みから離れたところへ誘い出しましょう！",
  ui_story_5043_50431402_146_dialog_content = "何を…？",
  ui_story_5043_50431402_147_dialog_content = "彫像の被り物をかぶった、そこのあなたたち、\n食らいなさい！",
  ui_story_5043_50431402_148_dialog_content = "ガァ…",
  ui_story_5043_50431402_149_dialog_content = "「神の手」のごあいさつを気に入っていただけたら嬉しいですわ。",
  ui_story_5043_50431402_X149_dialog_content = "グア！！！",
  ui_story_5043_50431402_X150_dialog_content = "その程度では私の騎士は倒せませんよ。\n攻撃を続けろ！",
  ui_story_5043_50431402_150_dialog_content = "続いては、マシューさんに教えていただいた方法です。\nマシューさん、覚えていらっしゃいますか？",
  ui_story_5043_50431402_151_dialog_content = "積極的なだけでは足りません。\n<color=#FFB400>己を隠す</color>ことも必要ですよね！",
  ui_story_5043_50431402_152_dialog_content = "むろんだ！私が援護しようではないか！",
  ui_story_5043_50431402_153_dialog_content = "急ぐのだ！壁の後ろへ隠れるぞ！",
  ui_story_5043_50431402_154_dialog_content = "フン、これしきの挫折であきらめるとは、\n貴方たちの恋愛はやはり大したものではありませんね。",
  ui_story_5043_50431402_155_dialog_content = "一般人を守るのではなかったのですか？",
  ui_story_5043_50431402_156_dialog_content = "ガァ…",
  ui_story_5043_50431402_157_dialog_content = "グア？",
  ui_story_5043_50431402_158_dialog_content = "思った通り、見つけられないようですわ！",
  ui_story_5043_50431402_159_dialog_content = "こうして見てみると、あの被り物が弱点である気がしてきましたわ。",
  ui_story_5043_50431402_160_dialog_content = "うむ、いかにも。被り物の下の顔を拝んでみたいものだな！",
  ui_story_5043_50431402_161_dialog_content = "こういう時には3つ目の方法ですわね！",
  ui_story_5043_50431402_162_dialog_content = "進むべきか、引くべきか、最もよい選択はどちらか――\n<color=#FFB400>探りも必要</color>ですわ！",
  ui_story_5043_50431402_163_dialog_content = "最後の一歩を踏み出す前に、\n相手の力量を探らなければなりません！",
  ui_story_5043_50431402_X163_dialog_content = "弱点を見つけさえすれば、一撃で必ず倒せます！",
  ui_story_5043_50431402_164_dialog_content = "彫像の被り物を攻撃してみよう。",
  ui_story_5043_50431402_165_dialog_content = "承知しました。ではすぐに攻撃しましょう！",
  ui_story_5043_50431402_166_dialog_content = "グア――！！！",
  ui_story_5043_50431402_167_dialog_content = "<color=#e8d9bb>バン、バン、バン！！</color>",
  ui_story_5043_50431402_168_dialog_content = "あっ…イタタタタ…これは痛い…",
  ui_story_5043_50431402_169_dialog_content = "被り物を外すのはそう簡単じゃなさそうだね。",
  ui_story_5043_50431402_170_dialog_content = "アハハハハ、貴方たちのバカさ加減には笑いが止まりませんね。",
  ui_story_5043_50431402_171_dialog_content = "その程度の攻撃で私の騎士を倒せるとでも思ったのですか？",
  ui_story_5043_50431402_172_dialog_content = "ふふ、様々な波乱を越えてきた今こそ、\n感情も最高潮に達しましたわ！",
  ui_story_5043_50431402_173_dialog_content = "こういう時はもう、テクニックなど必要ありません。\n必要なのは――",
  ui_story_5043_50431402_174_dialog_content = "そうだ、今だよ！ティナ！",
  ui_story_5043_50431402_175_dialog_content = "君の真心を見せるんだ！！",
  ui_story_5043_50431402_176_dialog_content = "そうです！全身全霊の真心を見せてあげますわ！",
  ui_story_5043_50431402_177_dialog_content = "私の燃えるような情熱の一撃を受けてください！",
  ui_story_5043_50431402_178_dialog_content = "<size=45><color=#FFB400>聖なる輝きよ</color>！</size>",
  ui_story_5043_50431402_179_dialog_content = "ふぅ…うまくいったの？",
  ui_story_5043_50431402_180_dialog_content = "被り物をかぶってた暗鬼が消滅したみたいだ！",
  ui_story_5043_50431402_181_dialog_content = "いや…そんなはずはない…私の騎士が…",
  ui_story_5043_50431402_182_dialog_content = "戦い続けるのだ、私の騎士よ！",
  ui_story_5043_50431402_183_dialog_content = "判決はまだ執行されていないのだぞ！\n今倒れてはならん！！",
  ui_story_5043_50431402_184_dialog_content = "もう終わりましたわ。",
  ui_story_5043_50431402_185_dialog_content = "彼らとの間に感情などなかったのでしょう？\nあなたが無理強いをし、こき使ってきただけです。",
  ui_story_5043_50431402_186_dialog_content = "私の真心の前では、そのような薄っぺらい感情のつながりは、\nもろく粉々に崩れてしまいますの。",
  ui_story_5043_50431402_187_dialog_content = "まだ訳の分からないことをほざく気か！",
  ui_story_5043_50431402_188_dialog_content = "「判決はまだ執行されていない」ことについては、\nなおさらご心配無用です。",
  ui_story_5043_50431402_189_dialog_content = "ここまで大きな騒ぎとなったのです。\n法廷が必ず本件の再審を行います。",
  ui_story_5043_50431402_190_dialog_content = "おそらく、イルンティ様が裁判長席にお座りになるでしょう。",
  ui_story_5043_50431402_191_dialog_content = "イルンティ裁判長が必ず納得のいく裁決を下してくださいますよ。",
  ui_story_5043_50431402_192_dialog_content = "…私を裁判にかける気か？いや、そんなはずはない！",
  ui_story_5043_50431402_193_dialog_content = "誰も私を裁けはしない！私は無罪だ！",
  ui_story_5043_50431402_194_dialog_content = "無罪かどうかを決めるのはあなたではありませんよ。",
  ui_story_5043_50431402_195_dialog_content = "私が決めるに決まっているだろう！\n裁判長は私だ！",
  ui_story_5043_50431402_196_dialog_content = "その身分もあなた自身で決められるものではありませんよ。",
  ui_story_5043_50431402_197_dialog_content = "腐りきっている！この街の法はもう腐りきっている！",
  ui_story_5043_50431402_198_dialog_content = "どけ！父のもとへ行く！",
  ui_story_5043_50431402_199_dialog_content = "サラール家が公正を明らかにしてくれる！",
  ui_story_5043_50431402_200_dialog_content = "行き詰った時は一族を頼ることしかできんのか？\nなんとみじめな。",
  ui_story_5043_50431402_201_dialog_content = "とんだ面汚しだ。",
  ui_story_5043_50431402_202_dialog_content = "どけ！！",
  ui_story_5043_50431402_203_dialog_content = "<color=#e8d9bb>パシッ！</color>",
  ui_story_5043_50431402_204_dialog_content = "わっ！",
  ui_story_5043_50431402_205_dialog_content = "だ、誰だ？私をたたいたのは誰だ！？",
  ui_story_5043_50431402_206_dialog_content = "大人しく私たちと法廷に戻り事件解決に努めれば、\n誰もあなたをたたいたりしません。",
  ui_story_5043_50431402_207_dialog_content = "ライン！貴様！",
  ui_story_5043_50431402_208_dialog_content = "いやしい庶民の分際で、自分が何をしたのか分かっているのか！？",
  ui_story_5043_50431402_209_dialog_content = "あなたのためですよ。",
  ui_story_5043_50431402_210_dialog_content = "もしこれがティナだったら、左か右かなど構わなかったでしょうね。",
  ui_story_5043_50431402_211_dialog_content = "その通りですわ。",
  ui_story_5043_50431402_212_dialog_content = "き…貴様ら…",
  ui_story_5043_50431402_213_dialog_content = "さあ、今はまだ勤務時間だぞ。\n恋愛法廷の裁判官たる我々が外をウロウロしているわけにはいかん。",
  ui_story_5043_50431402_214_dialog_content = "さあさあ、仕事に戻らねば。",
  ui_story_5043_50431402_215_dialog_content = "ええ、そうですね。まだ仕事が山積みです。",
  ui_story_5043_50431402_216_dialog_content = "ふわぁ～…ソファーと枕が待ってますわ～。",
  ui_story_5043_50431402_217_dialog_content = "おい！押すな！",
  ui_story_5043_50431402_218_dialog_content = "汚らわしい手を放せ！！",
  ui_story_5043_50431402_219_dialog_content = "あ、シュワーベを連れて行っちゃった！",
  ui_story_5043_50431402_220_dialog_content = "これで事件も無事解決なのかな？",
  ui_story_5043_50431402_221_dialog_content = "ええ。シュワーベに対する裁きは厳しいものになるわ。",
  ui_story_5043_50431402_222_dialog_content = "実際の損害は大きくなかったとはいっても、\n彼の行いはとても悪質よ。",
  ui_story_5043_50431402_223_dialog_content = "もし彼がもっと腹黒く、暗鬼を使って政局を混乱させでもしていたら…\n想像しただけでも恐ろしいわ。",
  ui_story_5043_50431402_224_dialog_content = "シュワーベがそこまで悪党じゃなくてよかったね。\nただ恋愛を嫌っていただけだったから。",
  ui_story_5043_50431402_225_dialog_content = "確かにそうね。そういう偏った考えだったからこそ、\n他の人には想像のつかないことができたのかもしれないわ。",
  ui_story_5043_50431402_226_dialog_content = "ほんの一瞬ではあったけど、シュワーベは確かに\n自分の思う理想の法廷を実現してみせたわ。",
  ui_story_5043_50431402_227_dialog_content = "これでようやく終わりだね！",
  ui_story_5043_50431402_228_dialog_content = "最初は小さな事件だと思ってたけど、\nこんな騒ぎになるとは思ってもみなかったよ…",
  ui_story_5043_50431402_229_dialog_content = "ええ。これで終わりね。",
  ui_story_5043_50431402_230_dialog_content = "あとは裁決だけね。私たちも最後まで付き合いましょう。",
  ui_story_5043_50431402_231_dialog_content = "うん、そうだね。行こう！",
  ui_story_5043_50431402_232_dialog_content = "最後の判決を聞きに行こう…",
  ui_story_5043_50431402_233_dialog_content = "あれ？修道女さん？",
  ui_story_5043_50431402_234_dialog_content = "…終わりです。",
  ui_story_5043_50431402_235_dialog_content = "ど、どうして泣いてるんですか？",
  ui_story_5043_50431402_236_dialog_content = "パレード隊もバラバラになり、気球もなくなってしまいました。",
  ui_story_5043_50431402_237_dialog_content = "私の赤いクローバーの花も…\n皆、失くなってしまいました…",
  ui_story_5043_50431402_238_dialog_content = "それもこれもシュワーベの起こした騒ぎのせいで…",
  ui_story_5043_50431402_239_dialog_content = "終わりです。何もかも終わってしまいました。",
  ui_story_5043_50431402_240_dialog_content = "白夜城の恋愛も、これでおしまいです…",
  ui_story_5043_50431501_1_dialog_content = "調査の結果が出たわ。ラインが推理した通りよ。",
  ui_story_5043_50431501_2_dialog_content = "シュワーベが事件の黒幕だったわ。\n彼は暗鬼を操り、「連続首なし彫像事件」を起こした。",
  ui_story_5043_50431501_3_dialog_content = "幸い、彫像を破壊した以外、\n光霊を傷つけるようなことはしなかったけど。",
  ui_story_5043_50431501_4_dialog_content = "そうだね。シュワーベがそれなりに正義感を持っててくれてよかった…",
  ui_story_5043_50431501_5_dialog_content = "それにしても、裁判官ってやっぱりすごいね。\n何の手がかりもない状態で正確な推理ができるなんて。",
  ui_story_5043_50431501_6_dialog_content = "そうね。この事件をきっかけに、\n法廷もあの3人の力を重んじるようになるわね。",
  ui_story_5043_50431501_7_dialog_content = "ただ、一つだけ分からないことがあるんだ。",
  ui_story_5043_50431501_8_dialog_content = "シュワーベはどうやって暗鬼を操ってたんだろう？",
  ui_story_5043_50431501_9_dialog_content = "戦ってる時も特殊な装置を使ってるようには見えなかったけど…",
  ui_story_5043_50431501_10_dialog_content = "そのことについても、調査結果が出たわ。",
  ui_story_5043_50431501_11_dialog_content = "サラール荘園で\nシュワーベが暗鬼を閉じ込めていた地下室が見つかったわ。",
  ui_story_5043_50431501_12_dialog_content = "ただ、地下室があっただけで、\n法廷の調査員も暗鬼を操るような装置は一切発見できなかったの。",
  ui_story_5043_50431501_13_dialog_content = "シュワーベに対する尋問と彼の自宅で見つけた証拠品から、\n法廷はある奇妙な結論に達したわ。",
  ui_story_5043_50431501_14_dialog_content = "猛獣をしつけるのと同じような方法で、\n暗鬼を「飼い慣らして」いたのではないかと考えられるの。",
  ui_story_5043_50431501_15_dialog_content = "飼い慣らす！？",
  ui_story_5043_50431501_16_dialog_content = "暗鬼を飼い慣らすことなんてできるの？",
  ui_story_5043_50431501_17_dialog_content = "よく考えてみて。そこまで不可能な話ではないわ。",
  ui_story_5043_50431501_18_dialog_content = "光霊は遠い昔から暗鬼を敵としてきたから、\n暗鬼と聞くと本能的に対立する者と考えてしまう。",
  ui_story_5043_50431501_19_dialog_content = "けれど、種族間の怨恨を除けば、\n暗鬼はただの知能の低い生物にすぎないわ。",
  ui_story_5043_50431501_20_dialog_content = "その他の動物と同じように、自身の習性と欲望を持っている。",
  ui_story_5043_50431501_21_dialog_content = "動物を飼い慣らす時もそうでしょう？よく観察して、特徴をつかみ、\n言うことを聞けばいいことがあると分からせる。",
  ui_story_5043_50431501_22_dialog_content = "シュワーベは先祖たちが狼に対してやってきたことを、\n暗鬼にもやってみせただけのことよ。",
  ui_story_5043_50431501_23_dialog_content = "そういうことか…",
  ui_story_5043_50431501_24_dialog_content = "確かにその通りだね。\nでも、やっぱり不思議だな。",
  ui_story_5043_50431501_25_dialog_content = "実際は色々なところに、その傾向は見えていたわ。",
  ui_story_5043_50431501_26_dialog_content = "シュワーベは光霊を軽蔑していたようだけれど、\n小動物に対してはずいぶんと優しかったわ。",
  ui_story_5043_50431501_27_dialog_content = "同類以外には、不思議なくらい辛抱があったから、\n結果的に不思議な効果をもたらしたのでしょう。",
  ui_story_5043_50431501_28_dialog_content = "そうなると、光霊以外の目から見れば、\nシュワーベもそんなに嫌なヤツじゃないのかもね。",
  ui_story_5043_50431501_29_dialog_content = "あれ？そういえば…僕も光霊じゃないんだったね…",
  ui_story_5043_50431501_30_dialog_content = "さあ、おしゃべりはここまでにしましょ。",
  ui_story_5043_50431501_31_dialog_content = "シュワーベの裁判が始まるわ。",
  ui_story_5043_50431501_32_dialog_content = "被告シュワーベ、裏で暗鬼を操り彫像を破壊。",
  ui_story_5043_50431501_33_dialog_content = "法廷の厳密な調査の結果、証拠は確かなことが分かりました。",
  ui_story_5043_50431501_34_dialog_content = "被告、罪を認めますか？",
  ui_story_5043_50431501_35_dialog_content = "…",
  ui_story_5043_50431501_36_dialog_content = "（以前の偉そうな、大きな態度は今は見る影もないな…）",
  ui_story_5043_50431501_37_dialog_content = "この事件における、被告シュワーベの行為は悪質です。\nしかし、深刻な実質的損害はもたらしていません。",
  ui_story_5043_50431501_38_dialog_content = "被告はまだ若く、改心に十分な時間があることから、\n本法廷はシュワーベに禁固刑を科すことはいたしません。",
  ui_story_5043_50431501_39_dialog_content = "おや？私は牢獄に入らずに済むのですか？",
  ui_story_5043_50431501_40_dialog_content = "確かにそうね。シュワーベはしょせん極端な考え方の変人にすぎないわ。",
  ui_story_5043_50431501_41_dialog_content = "深刻な損害を与えていない限り、\n重い実刑を科す必要はないわ。",
  ui_story_5043_50431501_42_dialog_content = "禁固刑を科さないからといって、\n法の裁きを逃れられるわけではありません。",
  ui_story_5043_50431501_43_dialog_content = "サラール家および被告には、\n本件に関わる一切の再建費用を負担するよう申し渡します。",
  ui_story_5043_50431501_44_dialog_content = "法廷から支払われる賃金もすべて没収します。",
  ui_story_5043_50431501_45_dialog_content = "当然のことです。処罰を受け入れます。",
  ui_story_5043_50431501_46_dialog_content = "まったく気にしてないみたいだね…",
  ui_story_5043_50431501_47_dialog_content = "シュワーベにとって、金銭は重要ではないわ。",
  ui_story_5043_50431501_48_dialog_content = "そうなると…この処罰では軽すぎるのではないかしら？",
  ui_story_5043_50431501_49_dialog_content = "もちろん、処罰はこれだけではありません。",
  ui_story_5043_50431501_50_dialog_content = "法廷は本件を詳細に検討しましたが、その結果、\nシュワーベの極端な行いは、貴族の教育体制に原因があると考えました。",
  ui_story_5043_50431501_51_dialog_content = "その過ちを補うため、本法廷は被告シュワーベに\n専門機関に戻り再度学び直すことを命じます。",
  ui_story_5043_50431501_52_dialog_content = "何ですと！？黎明学院に再び戻れとおっしゃるのですか？",
  ui_story_5043_50431501_53_dialog_content = "暗鬼と結託したことは非常に重い誤ちです。\n厳格な対処が必要です。",
  ui_story_5043_50431501_X53_dialog_content = "本法廷は被告シュワーベに\n再び光の神の導きを受けることを命じます。",
  ui_story_5043_50431501_54_dialog_content = "<color=#FFB400>修道女たちが学ぶ神殿</color>に配属するものとします。",
  ui_story_5043_50431501_55_dialog_content = "修道女ですと！？",
  ui_story_5043_50431501_56_dialog_content = "裁判長、そ、そのような判決に意味はあるのですか！？",
  ui_story_5043_50431501_57_dialog_content = "誤ちを正し、心を改めるように。\nそれでは、あなたの師となる方をご紹介しましょう。",
  ui_story_5043_50431501_58_dialog_content = "ごきげんよう、シュワーベ閣下。\nまたお会いしましたね。",
  ui_story_5043_50431501_59_dialog_content = "なぜ貴方がここに！？まさか、これは貴方の考えですか！？",
  ui_story_5043_50431501_60_dialog_content = "神殿では通常の神学の授業以外にも、\n裁縫や料理といった楽しい授業もございます。",
  ui_story_5043_50431501_61_dialog_content = "今後数年間一緒に学んでいきましょう。\nどうぞよろしくお願いいたします。",
  ui_story_5043_50431501_62_dialog_content = "いいえ、行きません！\n女性しかいないような所には行きません！！",
  ui_story_5043_50431501_63_dialog_content = "どうやら、あなたは価値観も改める必要がありそうですね。",
  ui_story_5043_50431501_64_dialog_content = "シュワーベを連れて行き、入学の準備をさせなさい。",
  ui_story_5043_50431501_65_dialog_content = "本件では、シュワーベの他にも\n処罰を受けるべき者がいます。",
  ui_story_5043_50431501_66_dialog_content = "ライン裁判官。",
  ui_story_5043_50431501_67_dialog_content = "はい！",
  ui_story_5043_50431501_68_dialog_content = "サラール荘園に不法侵入したことを認めますね？",
  ui_story_5043_50431501_69_dialog_content = "はい。",
  ui_story_5043_50431501_70_dialog_content = "（やっぱり自首してたんだね…）",
  ui_story_5043_50431501_71_dialog_content = "分かりました。それでは裁判官規則第127条の規定により…",
  ui_story_5043_50431501_72_dialog_content = "あなたの今月の業績はないものとし、\n給料も白夜城の最低賃金に沿って支払います。",
  ui_story_5043_50431501_73_dialog_content = "わ、分かりました…",
  ui_story_5043_50431501_74_dialog_content = "（ライン、顔色が悪い…ショックなんだろうな…）",
  ui_story_5043_50431501_75_dialog_content = "チッ、まったく…！私も共犯ですぞ！",
  ui_story_5043_50431501_76_dialog_content = "私もサラール荘園に侵入しましたぞ。\nその処罰は我々2人で受けるといたしましょう。",
  ui_story_5043_50431501_77_dialog_content = "おや？マシュー裁判官、あなたもですか？",
  ui_story_5043_50431501_78_dialog_content = "ぼ、僕もです！僕も行きました！",
  ui_story_5043_50431501_79_dialog_content = "自ら罪を認めたこと、同じ裁判官として嬉しく思います。\nでは、マシュー裁判官も今月の給料を全額減給とするほか…",
  ui_story_5043_50431501_80_dialog_content = "あなたたち3名には、\n後ほど法廷の門前を掃除していただきましょう。",
  ui_story_5043_50431501_81_dialog_content = "枯れた花が一面に落ちていては法廷の面子に関わります。",
  ui_story_5043_50431501_82_dialog_content = "何ですと？そのような処罰をこの私が？",
  ui_story_5043_50431501_83_dialog_content = "では、ほかの罰がよろしいですか？",
  ui_story_5043_50431501_84_dialog_content = "いいえ、裁判長！ありがとうございます！\nすぐに掃除してきます！",
  ui_story_5043_50431501_85_dialog_content = "他にもう一つ、最後の罪がありますね。",
  ui_story_5043_50431501_86_dialog_content = "証人ボーンをここへ。",
  ui_story_5043_50431501_87_dialog_content = "は、はい、裁判長！",
  ui_story_5043_50431501_88_dialog_content = "あ…ボーン…",
  ui_story_5043_50431501_89_dialog_content = "（わあ、ボーンがきちんとした格好してる！）",
  ui_story_5043_50431501_90_dialog_content = "（いい服だ。まさに白夜城って感じだ！）",
  ui_story_5043_50431501_91_dialog_content = "あなたは被害者であるにも関わらず、光霊を助け、協力してくれました。\nそれは賞賛に値する行為です。",
  ui_story_5043_50431501_92_dialog_content = "しかし、法廷での偽証が誤ちであることは変わりません。",
  ui_story_5043_50431501_93_dialog_content = "この件については、あなたにそうするように言った\nライン裁判官も同罪です。",
  ui_story_5043_50431501_94_dialog_content = "はい…その通りです…",
  ui_story_5043_50431501_95_dialog_content = "では、2人には共に罰を受けていただきましょう――",
  ui_story_5043_50431501_96_dialog_content = "シュワーベに謝罪してください。",
  ui_story_5043_50431501_97_dialog_content = "は、はい…え？",
  ui_story_5043_50431501_98_dialog_content = "しゃ、謝罪するだけですか？",
  ui_story_5043_50431501_99_dialog_content = "彼はだまされた側ですから、ひどく腹を立てていることでしょう。\n誠意をもって謝罪するのですよ。",
  ui_story_5043_50431501_100_dialog_content = "これで、事件関係者に対するすべての判決、\nおよび処罰の申し渡しが完了しました。",
  ui_story_5043_50431501_101_dialog_content = "「連続首なし彫像事件」の審理を終了し、休廷とします！",
  ui_story_5043_50431501_102_dialog_content = "<color=#e8d9bb>カン――</color>",
  ui_story_5043_50431501_103_dialog_content = "<color=#e8d9bb>数日後</color>",
  ui_story_5043_50431501_104_dialog_content = "…以上が数か月前、僕が龍州で見聞したことの全てです。",
  ui_story_5043_50431501_105_dialog_content = "うむ。報告に感謝する、PlayerName。",
  ui_story_5043_50431501_106_dialog_content = "世界情勢の変化は予測しがたい。\nだが、白夜城の立場は変わらぬ。",
  ui_story_5043_50431501_107_dialog_content = "これからの1年も白夜城と天空ノ谷が\n友好的な往来を続けられることを望んでおる。",
  ui_story_5043_50431501_108_dialog_content = "若者よ、お主も同じ考えであってほしい。",
  ui_story_5043_50431501_109_dialog_content = "お、恐れ入ります。\n僕ももちろん、皆と仲良くやっていきたいと思っています！",
  ui_story_5043_50431501_110_dialog_content = "ならばよい。",
  ui_story_5043_50431501_111_dialog_content = "（ふぅ…なんとか、終わった！）",
  ui_story_5043_50431501_112_dialog_content = "今回の発表、なかなか様になってたわよ、PlayerName。",
  ui_story_5043_50431501_113_dialog_content = "そう？あはは…本当はちょっと緊張してたんだ。",
  ui_story_5043_50431501_114_dialog_content = "会議はこれでおわりとする。\n何か質問のある者はおるか？",
  ui_story_5043_50431501_115_dialog_content = "法廷が報告すべきことはすべて報告いたしました。",
  ui_story_5043_50431501_116_dialog_content = "オットー公爵はどうかな？",
  ui_story_5043_50431501_117_dialog_content = "長いこと座っていたものだから疲れてしまいましたな。",
  ui_story_5043_50431501_118_dialog_content = "ならば、解散するとしよう。",
  ui_story_5043_50431501_119_dialog_content = "（ダメよ。せっかく法廷と元老院がそろっているのに、\nもう一つ大切なことがあるわ）",
  ui_story_5043_50431501_120_dialog_content = "（最近白夜城では、暗鬼と熱狂した民衆の他にも、\nその機に乗じて混乱を起こした者がいる…）",
  ui_story_5043_50431501_121_dialog_content = "（アップタウン護衛隊として、元老院の責任を問うわ！）",
  ui_story_5043_50431501_122_dialog_content = "城主様、オットー公爵、お待ちください。",
  ui_story_5043_50431501_123_dialog_content = "ソルラド殿下、高庭はこのところ様々な突発的事件を\nうまく処理できるようになり、頼もしい限りですな。",
  ui_story_5043_50431501_124_dialog_content = "民衆とこうもうまく付き合えるとは、\nなんとも意外ではありますがな。",
  ui_story_5043_50431501_125_dialog_content = "ハハハ、オットー公爵、そう謙虚になることもあるまい。\n元老院の支持があってこそのことだ。",
  ui_story_5043_50431501_126_dialog_content = "元老院が兵を出して暗鬼を駆逐してくれなければ、\nアップタウン護衛隊とて力を発揮できぬ。",
  ui_story_5043_50431501_127_dialog_content = "どうした、カレン？",
  ui_story_5043_50431501_128_dialog_content = "…",
  ui_story_5043_50431501_129_dialog_content = "おや、それでは私はここで失礼するとしましょう。\nあとは親子水入らずでお話しください。",
  ui_story_5043_50431501_130_dialog_content = "城主様は元老院の衛兵たちが冠月祭のサロンで、\n何をしたか、ご存じだったのですか？",
  ui_story_5043_50431501_131_dialog_content = "むろんだ。",
  ui_story_5043_50431501_132_dialog_content = "ここ1年でお前もずいぶんと落ち着いてきた。\nだが、以前の勇敢さも失われておらぬ。",
  ui_story_5043_50431501_133_dialog_content = "だが、政治は勇敢なだけでは解決できぬのだ。",
  ui_story_5043_50431501_134_dialog_content = "今ある仕事が片付いたら、高庭の皆に休暇をやろう。",
  ui_story_5043_50431501_135_dialog_content = "ありがとうございます。ですが、必要ありません。",
  ui_story_5043_50431501_136_dialog_content = "PlayerName、行きましょう。",
  ui_story_5043_50431501_137_dialog_content = "<color=#e8d9bb>パン――！パン――！パン――！</color>",
  ui_story_5043_50431501_138_dialog_content = "PlayerNameさん、報告会の成功おめでとうございます！！",
  ui_story_5043_50431501_139_dialog_content = "先程会議室から出て来たイルンティ裁判長を見て、\nよい報告だったとすぐに分かりましたわ！",
  ui_story_5043_50431501_140_dialog_content = "以前バイロンさんのために用意したクラッカーです。",
  ui_story_5043_50431501_141_dialog_content = "無駄にせずに済みましたね。",
  ui_story_5043_50431501_142_dialog_content = "どうだ？嬉しいであろうが？",
  ui_story_5043_50431501_143_dialog_content = "殿下もなぜ厳しい顔をなさっているのです？\n一緒に喜んではいかがですかな？",
  ui_story_5043_50431501_144_dialog_content = "PlayerName、順調に仕事が終わってよかった。",
  ui_story_5043_50431501_145_dialog_content = "わぁ…ありがとう！",
  ui_story_5043_50431501_146_dialog_content = "あなたたち…",
  ui_story_5043_50431501_147_dialog_content = "まあ、いいわ。あなたたちにはかなわないわ。",
  ui_story_5043_50431501_148_dialog_content = "皆さん、興ざめすることを言うようですが、\n法廷の仕事はまだ終わっていませんよ。",
  ui_story_5043_50431501_149_dialog_content = "カレン殿下も一緒にいらしてください。",
  ui_story_5043_50431501_150_dialog_content = "この仕事は高庭の協力が必要なものですから。",
  ui_story_5043_50431501_151_dialog_content = "<color=#e8d9bb>アップタウン、法廷</color>",
  ui_story_5043_50431501_152_dialog_content = "なるほど。",
  ui_story_5043_50431501_153_dialog_content = "恋愛訴訟部は解散になったけれど、\n大量の訴訟が未処理のまま残った、と。",
  ui_story_5043_50431501_154_dialog_content = "法廷の仕事はとても丁寧なようね、裁判長。",
  ui_story_5043_50431501_155_dialog_content = "こんなにたくさんの事件記録、\nいつになったら読み終わるんだろう…",
  ui_story_5043_50431501_156_dialog_content = "それは、もちろん――",
  ui_story_5043_50431501_157_dialog_content = "分かりました…",
  ui_story_5043_50431501_158_dialog_content = "カレン殿下、ここの書類に記録されている事件は、\n一見ただの男女間の感情のもつれにすぎません。",
  ui_story_5043_50431501_159_dialog_content = "しかし、同時に社会基盤の建設や安定などに関する、\n隠れた問題を映し出しているものも多くあります。",
  ui_story_5043_50431501_160_dialog_content = "さらにこれらの書類を通して、ミッドタウンやダウンタウンの\n住民の考え方を深く知ることができました。",
  ui_story_5043_50431501_161_dialog_content = "彼らの愛に対する考え方、信仰に対する解釈など…\nどれも新しい視点と考え方を示してくれています。",
  ui_story_5043_50431501_162_dialog_content = "ですから、この事件記録は次の法改正に\n大いに役立つと思うのです。",
  ui_story_5043_50431501_163_dialog_content = "その際には、城主様――特に殿下には、\n法廷の業務と判断を支持していただきたく存じます。",
  ui_story_5043_50431501_164_dialog_content = "もう少し大きな見方をすれば、\n白夜城の今後のためにも、これは非常に重要なのです。",
  ui_story_5043_50431501_165_dialog_content = "分かったわ。支持を約束するわ。",
  ui_story_5043_50431501_166_dialog_content = "同じ考えをもっているのは1人だけではないわ、イルンティ。",
  ui_story_5043_50431501_167_dialog_content = "カレン、嬉しそうだね？",
  ui_story_5043_50431501_168_dialog_content = "そんなに分かりやすいかしら？",
  ui_story_5043_50431501_169_dialog_content = "どうやら、街も知らないうちに元の様子に戻ったようですね。",
  ui_story_5043_50431501_170_dialog_content = "にぎやかなサロンもパレードもなければ、\n宙に浮かぶ月もありません。",
  ui_story_5043_50431501_171_dialog_content = "いちいち感嘆しているのはお前くらいだぞ。\n我々貴族というのはそういうものだ。",
  ui_story_5043_50431501_172_dialog_content = "白夜城は移り気なのだ。\n新しい風潮に乗り遅れるわけにはいかん。",
  ui_story_5043_50431501_173_dialog_content = "見るがいい。",
  ui_story_5043_50431501_174_dialog_content = "あら？私の手袋ですわ？",
  ui_story_5043_50431501_175_dialog_content = "今や最新のファッションアイテムなのだ。\n社交界では貴族たちがこぞってはめておる。",
  ui_story_5043_50431501_176_dialog_content = "はめ心地が少々重いが、私は7対買ったぞ。",
  ui_story_5043_50431501_177_dialog_content = "他にやることはないのか。",
  ui_story_5043_50431501_178_dialog_content = "絵にかいたようなお坊ちゃんですね…",
  ui_story_5043_50431501_179_dialog_content = "ティナ、最新ファッションブームの火付け役として、\n何か言うことはあるか？",
  ui_story_5043_50431501_180_dialog_content = "お前とボーンはその後どうなったのだ？\n見事飼い主となれたのか？",
  ui_story_5043_50431501_181_dialog_content = "白夜城では決して許されぬことではあるが…\n実に面白いではないか！",
  ui_story_5043_50431501_182_dialog_content = "あの…実は私…今日、ボーンとここで会う約束をしていますの。",
  ui_story_5043_50431501_183_dialog_content = "ただ…ボーンに<color=#FFB400>お別れを言う</color>ためですけど。",
  ui_story_5043_50431501_184_dialog_content = "え！？",
  ui_story_5043_50431501_185_dialog_content = "待たぬか！？突然どうしたのだ！？\nティナ、ボーンに対する熱はそうも簡単に消えるものだったのか？",
  ui_story_5043_50431501_186_dialog_content = "いいえ、その反対ですわ。ボーンは可愛くて、善良で、\n色々な所を旅していて…私、そんなボーンが大好きですわ。",
  ui_story_5043_50431501_187_dialog_content = "暗鬼は恐ろしく、恨むべき存在ですが、\nボーンは他の暗鬼とは違います。",
  ui_story_5043_50431501_188_dialog_content = "でも、すべての人がそれを分かってくれるわけではありません。",
  ui_story_5043_50431501_189_dialog_content = "もし私と一緒に白夜城に留まったら、\nボーンの暮らしは居心地の悪いものとなるでしょう。",
  ui_story_5043_50431501_190_dialog_content = "白夜城で過ごしたこの1か月間も楽しい事より、\n怖い思いをしたことの方が多かったに決まっていますわ。",
  ui_story_5043_50431501_191_dialog_content = "…え？",
  ui_story_5043_50431501_192_dialog_content = "うう…",
  ui_story_5043_50431501_193_dialog_content = "ボーン、隠れていないで出ておいで！",
  ui_story_5043_50431501_194_dialog_content = "み、みなさん、こんにちは…",
  ui_story_5043_50431501_X194_dialog_content = "着替えてきたんだね！",
  ui_story_5043_50431501_X195_dialog_content = "いい服だね。まさに白夜城って感じだ！",
  ui_story_5043_50431501_X196_dialog_content = "はい…今日は大切な日なので、\nきちんとした服を着てきました。",
  ui_story_5043_50431501_195_dialog_content = "実は…僕も…みなさんにお別れを言いに来ました。",
  ui_story_5043_50431501_196_dialog_content = "旅を続けるんだね。",
  ui_story_5043_50431501_197_dialog_content = "は、はい。た、ただ…みなさんの思っているのとは…\nちょっと、違います。",
  ui_story_5043_50431501_198_dialog_content = "白夜城にいる間、たくさんこわいことがあって、\nいつもこわい思いばかりしていました。",
  ui_story_5043_50431501_199_dialog_content = "でも、白夜城でのことは、とても幸せでした。",
  ui_story_5043_50431501_200_dialog_content = "みなさんに会えたからです。",
  ui_story_5043_50431501_201_dialog_content = "と、特に…ティナに会えたからです。",
  ui_story_5043_50431501_202_dialog_content = "ボーン…ありがとう…",
  ui_story_5043_50431501_203_dialog_content = "ぼ、僕は初めて、光霊からなんの目的も理由もない善意をもらいました。",
  ui_story_5043_50431501_204_dialog_content = "とても大切なことです。だから僕は幸せです。",
  ui_story_5043_50431501_205_dialog_content = "（何の目的も理由もない善意…）",
  ui_story_5043_50431501_206_dialog_content = "（…そうだね、すごく大切なことだ）",
  ui_story_5043_50431501_207_dialog_content = "…ボーン、行ってください。あなたの旅を続けてください。",
  ui_story_5043_50431501_208_dialog_content = "もし今後また機会があれば、必ずお会いしましょうね。",
  ui_story_5043_50431501_209_dialog_content = "あ、そうでした。ずっと渡したいものがあったのです。",
  ui_story_5043_50431501_210_dialog_content = "さあ、焼いたばかりのクッキーですよ。\n旅は長いのでしょう？お腹の空いた時に食べてください。",
  ui_story_5043_50431501_211_dialog_content = "ううっ…ありがとう…ありがとう、ティナ…",
  ui_story_5043_50431501_212_dialog_content = "大切に…大切に…食べちゃうよ！",
  ui_story_5043_50431501_213_dialog_content = "ふふふ、「大切に食べちゃう」とはどういう食べ方かしら？\nお腹を満たすことの方が大事ですわ！",
  ui_story_5043_50431501_214_dialog_content = "さあ、急いで出発してください。",
  ui_story_5043_50431501_215_dialog_content = "白夜城に日没はありませんが、\n他のところはそうとは限りませんよ。",
  ui_story_5043_50431501_216_dialog_content = "ううっ…うん…じゃあ、行くね！",
  ui_story_5043_50431501_217_dialog_content = "みなさん、さようなら！",
  ui_story_5043_50431501_218_dialog_content = "さようなら、ボーン！",
  ui_story_5043_50431501_219_dialog_content = "おやおや、あの子が旅立った♪",
  ui_story_5043_50431501_220_dialog_content = "みんなの別れの言葉と贈り物と一緒に♪",
  ui_story_5043_50431501_221_dialog_content = "残ったのはあの子の匂いだけ♪",
  ui_story_5043_50431501_222_dialog_content = "白夜城の暁に溶けていく♪"
}
return config
